MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('45° Side Bend', 'ABS', 'OBLIQUES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your arms extended straight down by your sides.', '["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0002', '/media/exercises/0002-Hy9D21L.gif', '/media/posters/0002-Hy9D21L.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0003-1ZFqTDN.gif', poster_url = '/media/posters/0003-1ZFqTDN.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0003', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Air Bike') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('All Fours Squad Stretch', 'QUADS', 'HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips.', '["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1512', '/media/exercises/1512-qBcKorM.gif', '/media/posters/1512-qBcKorM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Alternate Lateral Pulldown', 'BACK', 'BICEPS,RHOMBOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the cable machine with your back straight and feet flat on the ground.', '["Sit on the cable machine with your back straight and feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0007', '/media/exercises/0007-4IKbhHV.gif', '/media/posters/0007-4IKbhHV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Archer Pull Up', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', '["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3293', '/media/exercises/3293-72BC5Za.gif', '/media/posters/3293-72BC5Za.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Archer Push Up', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands slightly wider than shoulder-width apart.', '["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3294', '/media/exercises/3294-A9qxk2F.gif', '/media/posters/3294-A9qxk2F.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Arm Slingers Hanging Bent Knee Legs', 'ABS', 'SHOULDERS,BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.', '["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2355', '/media/exercises/2355-uWpxD4v.gif', '/media/posters/2355-uWpxD4v.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Arm Slingers Hanging Straight Legs', 'ABS', 'SHOULDERS,BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your legs straight down.', '["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2333', '/media/exercises/2333-PXTIwgu.gif', '/media/posters/2333-PXTIwgu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Arms Apart Circular Toe Touch (male)', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and arms extended to the sides.', '["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3214', '/media/exercises/3214-RtyAsy1.gif', '/media/posters/3214-RtyAsy1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Arms Overhead Full Sit-up (male)', 'ABS', 'HIP FLEXORS,LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3204', '/media/exercises/3204-NAkmgdx.gif', '/media/posters/3204-NAkmgdx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Hanging Knee Raise', 'ABS', 'HIP FLEXORS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0011', '/media/exercises/0011-03lzqwk.gif', '/media/posters/0011-03lzqwk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Hanging Knee Raise With Throw Down', 'ABS', 'HIP FLEXORS,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, keeping your legs together.","Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Allow your legs to swing back up and repeat the movement for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0010', '/media/exercises/0010-8K0w2yA.gif', '/media/posters/0010-8K0w2yA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Lying Calves Stretch', 'CALVES', 'HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your legs extended.', '["Lie on your back with your legs extended.","Bend one knee and place your foot flat on the ground.","Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1708', '/media/exercises/1708-GxDwDX0.gif', '/media/posters/1708-GxDwDX0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Lying Glutes Stretch', 'GLUTES', 'HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your legs extended.', '["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1709', '/media/exercises/1709-yn0LjwL.gif', '/media/posters/1709-yn0LjwL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Lying Gluteus And Piriformis Stretch', 'GLUTES', 'HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your legs extended.', '["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1710', '/media/exercises/1710-RQNVT10.gif', '/media/posters/1710-RQNVT10.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Lying Leg Raise With Lateral Throw Down', 'ABS', 'HIP FLEXORS,OBLIQUES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs extended and your arms by your sides.', '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift your legs off the ground, keeping them straight.","While keeping your legs together, lower them to one side until they are a few inches above the ground.","Pause for a moment, then lift your legs back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0012', '/media/exercises/0012-UGhRD1A.gif', '/media/posters/0012-UGhRD1A.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Lying Leg Raise With Throw Down', 'ABS', 'HIP FLEXORS,QUADRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs extended and your arms by your sides.', '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, keeping them straight.","Raise your legs until they are perpendicular to the ground.","Lower your legs back down to the starting position.","Simultaneously, throw your legs down towards the ground, keeping them straight.","Raise your legs back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0013', '/media/exercises/0013-VX5YKR5.gif', '/media/posters/0013-VX5YKR5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Motion Russian Twist', 'ABS', 'OBLIQUES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your knees bent and feet flat on the floor.', '["Sit on the ground with your knees bent and feet flat on the floor.","Hold the medicine ball with both hands in front of your chest.","Lean back slightly, engaging your abs and keeping your back straight.","Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0014', '/media/exercises/0014-r7cT9YD.gif', '/media/posters/0014-r7cT9YD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Parallel Close Grip Pull-up', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to your desired weight and height.', '["Adjust the machine to your desired weight and height.","Place your hands on the parallel bars with a close grip, palms facing each other.","Hang from the bars with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Continue pulling until your chin is above the bars.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0015', '/media/exercises/0015-vrhHa6D.gif', '/media/posters/0015-vrhHa6D.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Prone Hamstring', 'HAMSTRINGS', 'GLUTES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a mat or bench with your legs fully extended.', '["Lie face down on a mat or bench with your legs fully extended.","Have a partner or use a resistance band to secure your ankles.","Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0016', '/media/exercises/0016-VedGSby.gif', '/media/posters/0016-VedGSby.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Prone Lying Quads Stretch', 'QUADS', 'HAMSTRINGS,GLUTES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on the ground with your legs extended.', '["Lie face down on the ground with your legs extended.","Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Hold the stretch for 20-30 seconds, then release.","Repeat with your right leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1713', '/media/exercises/1713-YUYAMEj.gif', '/media/posters/1713-YUYAMEj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Prone Rectus Femoris Stretch', 'ABS', 'QUADRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on the ground with your legs straight.', '["Lie face down on the ground with your legs straight.","Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1714', '/media/exercises/1714-2Ryn564.gif', '/media/posters/1714-2Ryn564.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Seated Pectoralis Major Stretch With Stability Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your back straight.', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a stability ball with both hands and extend your arms straight out in front of you.","Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1716', '/media/exercises/1716-RoV1Rfa.gif', '/media/posters/1716-RoV1Rfa.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Side Lying Adductor Stretch', 'QUADS', 'HAMSTRINGS,GLUTES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs straight and stacked on top of each other.', '["Lie on your side with your legs straight and stacked on top of each other.","Bend your bottom leg slightly for stability.","Place your top foot on a stable surface, such as a bench or step.","Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Hold the stretch for 20-30 seconds.","Return to the starting position and repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1712', '/media/exercises/1712-hC6oYY5.gif', '/media/posters/1712-hC6oYY5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Sit-up', 'ABS', 'HIP FLEXORS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a bench or have someone hold your feet down.', '["Sit on the edge of a bench or have someone hold your feet down.","Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1758', '/media/exercises/1758-aumB2IV.gif', '/media/posters/1758-aumB2IV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Standing Chin-up', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to your desired assistance level.', '["Adjust the machine to your desired assistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1431', '/media/exercises/1431-7OeHptV.gif', '/media/posters/1431-7OeHptV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Standing Pull-up', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to your desired weight and height settings.', '["Adjust the machine to your desired weight and height settings.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Engage your lats and biceps, and pull yourself up towards the handles.","Pause for a moment at the top, squeezing your back muscles.","Slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1432', '/media/exercises/1432-f4xtKBj.gif', '/media/posters/1432-f4xtKBj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Standing Triceps Extension (with Towel)', 'TRICEPS', 'SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.', '["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Keep your elbows close to your ears and your upper arms stationary.","Slowly extend your forearms upward, squeezing your triceps at the top.","Pause for a moment, then slowly lower the towel back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0018', '/media/exercises/0018-7HcfMBP.gif', '/media/posters/0018-7HcfMBP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Assisted Wide-grip Chest Dip (kneeling)', 'CHEST', 'TRICEPS,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to your desired height and secure your knees on the pad.', '["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with a wide grip and keep your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2364', '/media/exercises/2364-PnZJIrk.gif', '/media/posters/2364-PnZJIrk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Astride Jumps (male)', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3220', '/media/exercises/3220-f9lVSSI.gif', '/media/posters/3220-f9lVSSI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Back And Forth Step', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3672', '/media/exercises/3672-fNGumX0.gif', '/media/posters/3672-fNGumX0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Back Extension On Exercise Ball', 'BACK', 'GLUTES,HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1314', '/media/exercises/1314-qLpO4vV.gif', '/media/posters/1314-qLpO4vV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Back Lever', 'BACK', 'BICEPS,FOREARMS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.', '["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3297', '/media/exercises/3297-GaSzzuh.gif', '/media/posters/3297-GaSzzuh.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Backward Jump', 'QUADS', 'HAMSTRINGS,GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1473', '/media/exercises/1473-SaDOwk7.gif', '/media/posters/1473-SaDOwk7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0020-xAySMB0.gif', poster_url = '/media/posters/0020-xAySMB0.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0020', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Balance Board') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Alternating Biceps Curl', 'BICEPS', 'FOREARMS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.', '["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Lower the arm back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0968', '/media/exercises/0968-3omWx6P.gif', '/media/posters/0968-3omWx6P.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Alternating V-up', 'ABS', 'HIP FLEXORS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band.', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Repeat the movement, alternating the position of your legs with each repetition.","Continue for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0969', '/media/exercises/0969-ztAa1RK.gif', '/media/posters/0969-ztAa1RK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Assisted Wheel Rollerout', 'ABS', 'LOWER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Kneel on the floor and hold the handles of the band with both hands, palms facing down.', '["Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Place the band on the ground in front of you and position your hands shoulder-width apart.","Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0971', '/media/exercises/0971-zhF9lW4.gif', '/media/posters/0971-zhF9lW4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, pushing the bands away from your chest.","Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1254', '/media/exercises/1254-khlHMqs.gif', '/media/posters/1254-khlHMqs.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Bent-over Hip Extension', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a sturdy anchor point at ankle height.', '["Attach the band to a sturdy anchor point at ankle height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step back to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and lean forward, maintaining a neutral spine.","Extend your right leg straight back, squeezing your glutes at the top.","Lower your right leg back down and repeat with the left leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0980', '/media/exercises/0980-wSScovH.gif', '/media/posters/0980-wSScovH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Bicycle Crunch', 'ABS', 'HIP FLEXORS,OBLIQUES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your hands behind your head and your knees bent.', '["Lie flat on your back with your hands behind your head and your knees bent.","Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0972', '/media/exercises/0972-tZkGYZ9.gif', '/media/posters/0972-tZkGYZ9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Close-grip Pulldown', 'BACK', 'BICEPS,FOREARMS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.', '["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step back to create tension in the band, keeping your feet hip-width apart.","Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0974', '/media/exercises/0974-DptumMx.gif', '/media/posters/0974-DptumMx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Close-grip Push-up', 'TRICEPS', 'CHEST,SHOULDERS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Place a band around your upper arms, just above the elbows.', '["Place a band around your upper arms, just above the elbows.","Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0975', '/media/exercises/0975-ufaxB52.gif', '/media/posters/0975-ufaxB52.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Concentration Curl', 'BICEPS', 'FOREARMS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your legs spread apart and your feet flat on the ground.', '["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Hold one end of the band in your hand and step on the other end with your foot on the same side.","Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0976', '/media/exercises/0976-kmVVAfu.gif', '/media/posters/0976-kmVVAfu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Fixed Back Close Grip Pulldown', 'BACK', 'BICEPS,FOREARMS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.', '["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Grasp the band with a close grip, palms facing towards you.","Keep your back straight and engage your core.","Pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the band back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3117', '/media/exercises/3117-4LoWllp.gif', '/media/posters/3117-4LoWllp.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Fixed Back Underhand Pulldown', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a sturdy anchor point above your head.', '["Attach the band to a sturdy anchor point above your head.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step back to create tension in the band, keeping your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull the band down towards your chest, leading with your elbows.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3116', '/media/exercises/3116-ZH68exZ.gif', '/media/posters/3116-ZH68exZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Front Lateral Raise', 'SHOULDERS', 'TRAPS,UPPER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.', '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the band back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0977', '/media/exercises/0977-sTg7iys.gif', '/media/posters/0977-sTg7iys.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Front Raise', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.', '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0978', '/media/exercises/0978-TFA88iB.gif', '/media/posters/0978-TFA88iB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Hip Lift', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your knees bent and feet flat on the ground.', '["Lie on your back with your knees bent and feet flat on the ground.","Place a resistance band just above your knees.","Engage your glutes and core muscles.","Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1408', '/media/exercises/1408-E4R8Hz1.gif', '/media/posters/1408-E4R8Hz1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Horizontal Pallof Press', 'ABS', 'OBLIQUES,GLUTES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a sturdy anchor point at waist height.', '["Attach the band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with your feet shoulder-width apart.","Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Bring your hands to your chest, keeping your elbows bent and close to your body.","Engage your core and maintain a stable stance.","Extend your arms straight out in front of you, pushing the band away from your body.","Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Slowly bring your hands back to your chest, resisting the pull of the band.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0979', '/media/exercises/0979-9pa4H5m.gif', '/media/posters/0979-9pa4H5m.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Jack Knife Sit-up', 'ABS', 'HIP FLEXORS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band.', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0981', '/media/exercises/0981-KCBKjma.gif', '/media/posters/0981-KCBKjma.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Kneeling One Arm Pulldown', 'BACK', 'BICEPS,RHOMBOIDS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a sturdy anchor point above your head.', '["Attach the band to a sturdy anchor point above your head.","Kneel down and hold the band with one hand, palm facing down.","Extend your arm fully overhead, keeping your elbow slightly bent.","Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0983', '/media/exercises/0983-pmnrOp0.gif', '/media/posters/0983-pmnrOp0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Kneeling Twisting Crunch', 'ABS', 'OBLIQUES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a sturdy anchor point at waist height.', '["Attach the band to a sturdy anchor point at waist height.","Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Pause for a moment, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0985', '/media/exercises/0985-225x2Vd.gif', '/media/posters/0985-225x2Vd.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Lying Hip Internal Rotation', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your legs straight and a resistance band looped around your feet.', '["Lie on your back with your legs straight and a resistance band looped around your feet.","Bend your knees and bring them towards your chest, keeping your feet together.","Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0984', '/media/exercises/0984-vIICElP.gif', '/media/posters/0984-vIICElP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Lying Straight Leg Raise', 'ABS', 'HIP FLEXORS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs straight and your feet together.', '["Lie flat on your back with your legs straight and your feet together.","Place the band around the arches of your feet and hold the ends of the band with your hands.","Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1002', '/media/exercises/1002-bbLR7fB.gif', '/media/posters/1002-bbLR7fB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band One Arm Overhead Biceps Curl', 'BICEPS', 'FOREARMS,SHOULDERS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place one end of the band under your foot.', '["Stand with your feet shoulder-width apart and place one end of the band under your foot.","Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0986', '/media/exercises/0986-UNAB8ak.gif', '/media/posters/0986-UNAB8ak.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band One Arm Single Leg Split Squat', 'QUADS', 'GLUTES,HAMSTRINGS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart and place a resistance band around your ankles.', '["Stand with your feet hip-width apart and place a resistance band around your ankles.","Extend one leg forward and rest the top of your foot on a bench or step behind you.","Hold onto a support with one hand for balance.","Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0987', '/media/exercises/0987-arsYEd3.gif', '/media/posters/0987-arsYEd3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band One Arm Standing Low Row', 'BACK', 'BICEPS,SHOULDERS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a stable anchor point at waist height.', '["Attach the band to a stable anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0988', '/media/exercises/0988-km0sQC0.gif', '/media/posters/0988-km0sQC0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band One Arm Twisting Chest Press', 'CHEST', 'SHOULDERS,TRICEPS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a sturdy anchor point at chest height.', '["Attach the band to a sturdy anchor point at chest height.","Stand with your side facing the anchor point and grab the band with one hand.","Step away from the anchor point to create tension in the band.","Position your feet shoulder-width apart and slightly bend your knees.","Bring your hand holding the band across your body, towards the opposite shoulder.","While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Slowly return to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other hand."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0989', '/media/exercises/0989-c16nYGA.gif', '/media/posters/0989-c16nYGA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band One Arm Twisting Seated Row', 'BACK', 'BICEPS,SHOULDERS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the ground and your back straight.', '["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold the band with one hand and extend your arm fully in front of you.","Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","At the same time, twist your torso towards the side of the pulling arm.","Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0990', '/media/exercises/0990-DKBwJrL.gif', '/media/posters/0990-DKBwJrL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Pull Through', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach a resistance band to a sturdy anchor point at ground level.', '["Attach a resistance band to a sturdy anchor point at ground level.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step forward to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Drive your hips forward and squeeze your glutes to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0991', '/media/exercises/0991-VtTbiP3.gif', '/media/posters/0991-VtTbiP3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Push Sit-up', 'ABS', 'SHOULDERS,CHEST', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band securely to a stable anchor point.', '["Attach the band securely to a stable anchor point.","Lie flat on your back with your knees bent and feet flat on the ground.","Hold the band with both hands and extend your arms straight up towards the ceiling.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0992', '/media/exercises/0992-zFzbBfL.gif', '/media/posters/0992-zFzbBfL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Reverse Fly', 'SHOULDERS', 'UPPER BACK,TRAPEZIUS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a stationary object at chest height.', '["Attach the band to a stationary object at chest height.","Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0993', '/media/exercises/0993-sTfvVsG.gif', '/media/posters/0993-sTfvVsG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Reverse Wrist Curl', 'FOREARMS', 'FOREARMS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the ground.', '["Sit on a bench or chair with your feet flat on the ground.","Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0994', '/media/exercises/0994-Ezpnw9d.gif', '/media/posters/0994-Ezpnw9d.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Seated Hip Internal Rotation', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a chair or bench with your back straight and feet flat on the ground.', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Place a resistance band around your thighs, just above your knees.","Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0996', '/media/exercises/0996-9gbyYKk.gif', '/media/posters/0996-9gbyYKk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Seated Twist', 'ABS', 'OBLIQUES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your legs extended in front of you and your back straight.', '["Sit on the ground with your legs extended in front of you and your back straight.","Wrap the band around your waist and hold the ends with both hands.","Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1011', '/media/exercises/1011-S1JXDAG.gif', '/media/posters/1011-S1JXDAG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Shoulder Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place the band under your feet.', '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Press the band overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the band back to shoulder height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0997', '/media/exercises/0997-peAeMR3.gif', '/media/posters/0997-peAeMR3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Shrug', 'BACK', 'SHOULDERS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.', '["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1018', '/media/exercises/1018-trmte8s.gif', '/media/posters/1018-trmte8s.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Side Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.', '["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Extend your arms straight out to the sides, keeping them parallel to the ground.","Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Pause for a moment, then slowly extend your arms back out to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0998', '/media/exercises/0998-obe5LMq.gif', '/media/posters/0998-obe5LMq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Single Leg Calf Raise', 'CALVES', 'ANKLES,FEET', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart and place the band around the ball of your left foot.', '["Stand with your feet hip-width apart and place the band around the ball of your left foot.","Hold onto a stable object for balance if needed.","Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the right leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0999', '/media/exercises/0999-9JprnPh.gif', '/media/posters/0999-9JprnPh.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Single Leg Reverse Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart and place the band around the ball of your foot.', '["Stand with your feet hip-width apart and place the band around the ball of your foot.","Hold onto a stable object for balance.","Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1000', '/media/exercises/1000-QsSQWbf.gif', '/media/posters/1000-QsSQWbf.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Single Leg Split Squat', 'QUADS', 'GLUTES,HAMSTRINGS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart and place a resistance band around your ankles.', '["Stand with your feet hip-width apart and place a resistance band around your ankles.","Take a big step forward with your right foot and a smaller step back with your left foot.","Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Push through your right heel to return to the starting position.","Repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1001', '/media/exercises/1001-y8bYM8w.gif', '/media/posters/1001-y8bYM8w.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, with the band placed just above your knees.', '["Stand with your feet shoulder-width apart, with the band placed just above your knees.","Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Make sure your knees are tracking over your toes and your weight is in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1004', '/media/exercises/1004-TUZLh71.gif', '/media/posters/1004-TUZLh71.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Squat Row', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a sturdy anchor point at waist height.', '["Attach the band to a sturdy anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1003', '/media/exercises/1003-w1NOByi.gif', '/media/posters/1003-w1NOByi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Standing Crunch', 'ABS', 'OBLIQUES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a sturdy anchor point at waist height.', '["Attach the band to a sturdy anchor point at waist height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1005', '/media/exercises/1005-Kzg30R7.gif', '/media/posters/1005-Kzg30R7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Standing Rear Delt Row', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS,BICEPS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place the band under your feet.', '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1022', '/media/exercises/1022-tc5dYrf.gif', '/media/posters/1022-tc5dYrf.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Standing Twisting Crunch', 'ABS', 'OBLIQUES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.', '["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1007', '/media/exercises/1007-euq4pwp.gif', '/media/posters/1007-euq4pwp.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Step-up', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Place a band around your thighs, just above your knees.', '["Place a band around your thighs, just above your knees.","Stand facing a step or platform with your feet hip-width apart.","Step up onto the platform with your right foot, pushing through your heel.","Extend your left leg behind you, keeping it straight.","Lower your left foot back down to the ground.","Repeat with your left foot stepping up onto the platform.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1008', '/media/exercises/1008-d5bTEPV.gif', '/media/posters/1008-d5bTEPV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Stiff Leg Deadlift', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place the band around your ankles.', '["Stand with your feet shoulder-width apart and place the band around your ankles.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","As you lower, push your hips back and allow your knees to bend slightly.","Lower the band towards the ground, feeling a stretch in your hamstrings.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1009', '/media/exercises/1009-kuMiR2T.gif', '/media/posters/1009-kuMiR2T.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Straight Back Stiff Leg Deadlift', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place the band around your upper legs.', '["Stand with your feet shoulder-width apart and place the band around your upper legs.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Feel the stretch in your hamstrings as you lower the band.","Engage your glutes and hamstrings to lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1023', '/media/exercises/1023-lHeUULr.gif', '/media/posters/1023-lHeUULr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Straight Leg Deadlift', 'BACK', 'HAMSTRINGS,GLUTES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place the band around your feet.', '["Stand with your feet shoulder-width apart and place the band around your feet.","Hold the band with both hands, palms facing your body, and keep your arms straight.","Engage your core and maintain a slight bend in your knees.","Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Lower the band towards the ground while keeping your legs straight.","Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1010', '/media/exercises/1010-KUaoUV8.gif', '/media/posters/1010-KUaoUV8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Twisting Overhead Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place the band under your feet.', '["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles at shoulder height with your palms facing forward.","Engage your core and press the band overhead, fully extending your arms.","As you press, twist your torso to one side, keeping your hips stable.","Pause for a moment at the top, then return to the starting position.","Repeat the press and twist on the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1012', '/media/exercises/1012-u4bAmKp.gif', '/media/posters/1012-u4bAmKp.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Two Legs Calf Raise - (band Under Both Legs) V. 2', 'CALVES', 'ANKLES,FEET', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and place a resistance band under both feet.', '["Stand with your feet shoulder-width apart and place a resistance band under both feet.","Hold the ends of the band with your hands for stability.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1369', '/media/exercises/1369-jl6uxZV.gif', '/media/posters/1369-jl6uxZV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Underhand Pulldown', 'BACK', 'BICEPS,FOREARMS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.', '["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Extend your arms fully overhead, keeping your elbows slightly bent.","Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1013', '/media/exercises/1013-k6tUeqS.gif', '/media/posters/1013-k6tUeqS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band V-up', 'ABS', 'HIP FLEXORS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs straight and your arms extended overhead, holding the band.', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1014', '/media/exercises/1014-H6ETwO9.gif', '/media/posters/1014-H6ETwO9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Vertical Pallof Press', 'ABS', 'OBLIQUES,GLUTES', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.', '["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Hold the band with both hands and step away from the anchor point, creating tension in the band.","Position yourself perpendicular to the anchor point, with your side facing the band.","Extend your arms straight out in front of you, keeping your hands at chest height.","Engage your core and press the band away from your chest, fully extending your arms.","Hold the position for a few seconds, then slowly bring the band back towards your chest.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1015', '/media/exercises/1015-G7PXMlT.gif', '/media/posters/1015-G7PXMlT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Wrist Curl', 'FOREARMS', 'BICEPS,TRICEPS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the ground.', '["Sit on a bench or chair with your feet flat on the ground.","Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1016', '/media/exercises/1016-vUTfFHw.gif', '/media/posters/1016-vUTfFHw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Band Y-raise', 'SHOULDERS', 'TRAPS,RHOMBOIDS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.', '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1017', '/media/exercises/1017-aHDy5O5.gif', '/media/posters/1017-aHDy5O5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Alternate Biceps Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.', '["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the barbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0023', '/media/exercises/0023-Yza7XrQ.gif', '/media/posters/0023-Yza7XrQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Bench Front Squat', 'QUADS', 'HAMSTRINGS,GLUTES,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.', '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0024', '/media/exercises/0024-Y7YcmIJ.gif', '/media/posters/0024-Y7YcmIJ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Bench Squat', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up a barbell on a squat rack at chest height.', '["Set up a barbell on a squat rack at chest height.","Stand facing away from the rack, with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Lower your body down into a squat, keeping your knees in line with your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0026', '/media/exercises/0026-W9pFVv1.gif', '/media/posters/0026-W9pFVv1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Bent Arm Pullover', 'BACK', 'TRICEPS,CHEST', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your head at one end and your feet on the floor.', '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Lower the barbell behind your head while keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1316', '/media/exercises/1316-cA9FuWG.gif', '/media/posters/1316-cA9FuWG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the hips while keeping your back straight and chest up.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0027', '/media/exercises/0027-eZyBC3j.gif', '/media/posters/0027-eZyBC3j.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Biceps Curl (with Arm Blaster)', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2407', '/media/exercises/2407-aee2Fcj.gif', '/media/posters/2407-aee2Fcj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Clean And Press', 'QUADS', 'HAMSTRINGS,GLUTES,SHOULDERS,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and the barbell on the floor in front of you.', '["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0028', '/media/exercises/0028-SGY8Zui.gif', '/media/posters/0028-SGY8Zui.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Clean-grip Front Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.', '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0029', '/media/exercises/0029-qi996YS.gif', '/media/posters/0029-qi996YS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Close-grip Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0030', '/media/exercises/0030-J6Dx1Mu.gif', '/media/posters/0030-J6Dx1Mu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0032-ila4NZS.gif', poster_url = '/media/posters/0032-ila4NZS.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0032', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Deadlift') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Decline Bent Arm Pullover', 'BACK', 'TRICEPS,CHEST', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie down on a decline bench with your head lower than your hips and your feet secured.', '["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0034', '/media/exercises/0034-hMEptv0.gif', '/media/posters/0034-hMEptv0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Decline Close Grip To Skull Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.', '["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0035', '/media/exercises/0035-LMGXZn8.gif', '/media/posters/0035-LMGXZn8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Decline Pullover', 'CHEST', 'TRICEPS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie down on a decline bench with your head lower than your hips and your feet secured.', '["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Extend your arms above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Pause for a moment, then return the barbell to the starting position by reversing the motion.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1255', '/media/exercises/1255-9sgNE2O.gif', '/media/posters/1255-9sgNE2O.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Decline Wide-grip Press', 'CHEST', 'TRICEPS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your feet secured and your head lower than your hips.', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows out to the sides.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0036', '/media/exercises/0036-hl8DUh8.gif', '/media/posters/0036-hl8DUh8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Decline Wide-grip Pullover', 'BACK', 'TRICEPS,CHEST', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your head lower than your hips and your feet secured.', '["Lie on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a wide grip and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0037', '/media/exercises/0037-Hj4FOCd.gif', '/media/posters/0037-Hj4FOCd.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Floor Calf Raise', 'CALVES', 'HAMSTRINGS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Place a barbell on the floor in front of you.', '["Place a barbell on the floor in front of you.","Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Hold onto a stable object for balance if needed.","Raise your heels as high as possible, using your calves to lift your body.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1370', '/media/exercises/1370-2IHEa2T.gif', '/media/posters/1370-2IHEa2T.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Front Chest Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart, toes slightly turned out.', '["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0039', '/media/exercises/0039-IeTIEqg.gif', '/media/posters/0039-IeTIEqg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Front Raise', 'SHOULDERS', 'BICEPS,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.', '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0041', '/media/exercises/0041-b2Uoz54.gif', '/media/posters/0041-b2Uoz54.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0042-zG0zs85.gif', poster_url = '/media/posters/0042-zG0zs85.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0042', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Front Squat') AND (media_url IS NULL OR media_url = '');
UPDATE exercises SET media_url = '/media/exercises/0043-qXTaZnJ.gif', poster_url = '/media/posters/0043-qXTaZnJ.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0043', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Full Squat') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Full Squat (back Pov)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes slightly turned out.', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1461', '/media/exercises/1461-DhMl549.gif', '/media/posters/1461-DhMl549.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Full Squat (side Pov)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes slightly turned out.', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1462', '/media/exercises/1462-iYzB0Cz.gif', '/media/posters/1462-iYzB0Cz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Full Zercher Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and toes slightly turned out.', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1545', '/media/exercises/1545-vR1vold.gif', '/media/posters/1545-vR1vold.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Glute Bridge Two Legs On Bench (male)', 'GLUTES', 'HAMSTRINGS,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.', '["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3562', '/media/exercises/3562-qg2PGl6.gif', '/media/posters/3562-qg2PGl6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0046-5VCj6iH.gif', poster_url = '/media/posters/0046-5VCj6iH.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0046', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Hack Squat') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell High Bar Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes slightly turned out.', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell on your upper back, resting it on your traps.","Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1436', '/media/exercises/1436-Gnfo4FM.gif', '/media/posters/1436-Gnfo4FM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Incline Bench Press', 'CHEST', 'SHOULDERS,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0047', '/media/exercises/0047-3TZduzM.gif', '/media/posters/0047-3TZduzM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Incline Close Grip Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1719', '/media/exercises/1719-gx7s7uF.gif', '/media/posters/1719-gx7s7uF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Incline Reverse-grip Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0048', '/media/exercises/0048-641mIfk.gif', '/media/posters/0048-641mIfk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Incline Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0049', '/media/exercises/0049-dmgMp3n.gif', '/media/posters/0049-dmgMp3n.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0050-xi0yckC.gif', poster_url = '/media/posters/0050-xi0yckC.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0050', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Incline Shoulder Raise') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Jefferson Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and toes slightly turned out.', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Push through your heels to stand back up to the starting position.","Repeat the movement, alternating your forward and back foot with each repetition."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0051', '/media/exercises/0051-pkSoCW9.gif', '/media/posters/0051-pkSoCW9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Jm Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0052', '/media/exercises/0052-ZsiqXYa.gif', '/media/posters/0052-ZsiqXYa.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Jump Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Once you reach the bottom of the squat, explode upwards by jumping off the ground.","As you jump, extend your hips, knees, and ankles, pushing through your toes.","Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0053', '/media/exercises/0053-1gFNTZV.gif', '/media/posters/0053-1gFNTZV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lateral Lunge', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back.', '["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Push off with your right foot and return to the starting position.","Repeat on the other side, stepping with your left foot."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1410', '/media/exercises/1410-py1HSzx.gif', '/media/posters/1410-py1HSzx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Low Bar Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and the barbell resting on your upper back.', '["Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1435', '/media/exercises/1435-bTpEUcm.gif', '/media/posters/1435-bTpEUcm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0054-t8iSghb.gif', poster_url = '/media/posters/0054-t8iSghb.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0054', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Lunge') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lying Back Of The Head Tricep Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1720', '/media/exercises/1720-yg8Totb.gif', '/media/posters/1720-yg8Totb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lying Close-grip Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0055', '/media/exercises/0055-EcaV7aL.gif', '/media/posters/0055-EcaV7aL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lying Close-grip Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Extend your arms fully, lifting the barbell above your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0056', '/media/exercises/0056-HJ63mSO.gif', '/media/posters/0056-HJ63mSO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lying Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0057', '/media/exercises/0057-EMpUwRI.gif', '/media/posters/0057-EMpUwRI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lying Lifting (on Hip)', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back on a bench with your feet flat on the ground and your knees bent.', '["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Hold the barbell with an overhand grip and position it on your hips.","Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0058', '/media/exercises/0058-SNFfUff.gif', '/media/posters/0058-SNFfUff.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lying Preacher Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.', '["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0059', '/media/exercises/0059-SYJ4Bkt.gif', '/media/posters/0059-SYJ4Bkt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lying Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0061', '/media/exercises/0061-iZop9xO.gif', '/media/posters/0061-iZop9xO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Lying Triceps Extension Skull Crusher', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0060', '/media/exercises/0060-h8LFzo9.gif', '/media/posters/0060-h8LFzo9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Narrow Stance Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and toes pointing slightly outward.', '["Stand with your feet shoulder-width apart and toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0063', '/media/exercises/0063-elhhVgj.gif', '/media/posters/0063-elhhVgj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell One Arm Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Bend forward at the hips, keeping your back straight and your head in a neutral position.","Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0064', '/media/exercises/0064-Jsgsc27.gif', '/media/posters/0064-Jsgsc27.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell One Arm Side Deadlift', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Keep your back straight and your core engaged.","Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Lower the barbell as far as you can while maintaining good form.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0066', '/media/exercises/0066-2DxtqHL.gif', '/media/posters/0066-2DxtqHL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell One Arm Snatch', 'SHOULDERS', 'TRAPS,FOREARMS,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes pointing slightly outwards.', '["Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0067', '/media/exercises/0067-xHKN2s8.gif', '/media/posters/0067-xHKN2s8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell One Leg Squat', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back.', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0068', '/media/exercises/0068-uKyN64F.gif', '/media/posters/0068-uKyN64F.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Palms Up Wrist Curl Over A Bench', 'FOREARMS', 'BICEPS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.', '["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1412', '/media/exercises/1412-SJAA2IQ.gif', '/media/posters/1412-SJAA2IQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Pendlay Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and your chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3017', '/media/exercises/3017-r0z6xzQ.gif', '/media/posters/3017-r0z6xzQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Prone Incline Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a barbell with an underhand grip, shoulder-width apart.","Extend your arms fully, allowing the barbell to hang down towards the floor.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0072', '/media/exercises/0072-WLvTAv5.gif', '/media/posters/0072-WLvTAv5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0073-i6LWjok.gif', poster_url = '/media/posters/0073-i6LWjok.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0073', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Pullover') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Pullover To Press', 'BACK', 'TRICEPS,CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your head at one end and your feet on the ground.', '["Lie flat on a bench with your head at one end and your feet on the ground.","Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0022', '/media/exercises/0022-znLogoF.gif', '/media/posters/0022-znLogoF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Rack Pull', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up a barbell on a rack at knee height.', '["Set up a barbell on a rack at knee height.","Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Lower the barbell back down to the starting position by bending at the hips and knees.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0074', '/media/exercises/0074-za9Ni4z.gif', '/media/posters/0074-za9Ni4z.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Rear Delt Raise', 'SHOULDERS', 'TRAPS,RHOMBOIDS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0075', '/media/exercises/0075-Ln9iTbU.gif', '/media/posters/0075-Ln9iTbU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Rear Lunge', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.', '["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0078', '/media/exercises/0078-VaP75jl.gif', '/media/posters/0078-VaP75jl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Rear Lunge V. 2', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back.', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0077', '/media/exercises/0077-62Nw60O.gif', '/media/posters/0077-62Nw60O.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Revers Wrist Curl V. 2', 'FOREARMS', 'BICEPS,BRACHIALIS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and your knees bent.', '["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0079', '/media/exercises/0079-qDnGfDb.gif', '/media/posters/0079-qDnGfDb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Close-grip Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a reverse grip, hands shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2187', '/media/exercises/2187-YqJw82s.gif', '/media/posters/2187-YqJw82s.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0080', '/media/exercises/0080-xNrS20v.gif', '/media/posters/0080-xNrS20v.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Grip Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0118', '/media/exercises/0118-SzX3uzM.gif', '/media/posters/0118-SzX3uzM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Grip Decline Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your feet secured and your head lower than your hips.', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1256', '/media/exercises/1256-DotAgEF.gif', '/media/posters/1256-DotAgEF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Grip Incline Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1257', '/media/exercises/1257-DU7I633.gif', '/media/posters/1257-DU7I633.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Grip Incline Bench Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Sit on the bench facing the backrest with your chest against it.","Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1317', '/media/exercises/1317-8d8qJQI.gif', '/media/posters/1317-8d8qJQI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Grip Skullcrusher', 'TRICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1721', '/media/exercises/1721-yRLPCLu.gif', '/media/posters/1721-yRLPCLu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Preacher Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.', '["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0081', '/media/exercises/0081-4LIG9xr.gif', '/media/posters/0081-4LIG9xr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Reverse Wrist Curl', 'FOREARMS', 'BICEPS,BRACHIALIS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.', '["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0082', '/media/exercises/0082-LsZkfU6.gif', '/media/posters/0082-LsZkfU6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Rollerout', 'ABS', 'LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Kneel on the floor and hold a barbell with both hands, shoulder-width apart.', '["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Roll the barbell forward, extending your arms and keeping your core engaged.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0084', '/media/exercises/0084-7M66AVi.gif', '/media/posters/0084-7M66AVi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Rollerout From Bench', 'ABS', 'SHOULDERS,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by kneeling on the floor with a barbell placed on a bench in front of you.', '["Start by kneeling on the floor with a barbell placed on a bench in front of you.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0083', '/media/exercises/0083-Gxg9lDc.gif', '/media/posters/0083-Gxg9lDc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0085-wQ2c4XD.gif', poster_url = '/media/posters/0085-wQ2c4XD.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0085', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Romanian Deadlift') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Seated Behind Head Military Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Press the barbell upward until your arms are fully extended.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0086', '/media/exercises/0086-ngPpyRS.gif', '/media/posters/0086-ngPpyRS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Seated Bradford Rocky Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.","Press the barbell overhead, fully extending your arms.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0087', '/media/exercises/0087-0dCyly0.gif', '/media/posters/0087-0dCyly0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1371-ipvgBnC.gif', poster_url = '/media/posters/1371-ipvgBnC.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1371', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Seated Calf Raise') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Seated Close Grip Behind Neck Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with a close grip behind your neck, palms facing forward.","Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1718', '/media/exercises/1718-4CBIBOM.gif', '/media/posters/1718-4CBIBOM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Seated Close-grip Concentration Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.', '["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0089', '/media/exercises/0089-1V1gj1u.gif', '/media/posters/0089-1V1gj1u.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Seated Good Morning', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.', '["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Keep your back straight and your chest up.","Slowly hinge forward at the hips, lowering your torso towards the ground.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0090', '/media/exercises/0090-d960PgE.gif', '/media/posters/0090-d960PgE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Seated Overhead Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Press the barbell overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0091', '/media/exercises/0091-kTbSH9h.gif', '/media/posters/0091-kTbSH9h.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Seated Overhead Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0092', '/media/exercises/0092-5uFK1xr.gif', '/media/posters/0092-5uFK1xr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Seated Twist', 'ABS', 'OBLIQUES,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat bench with your feet flat on the ground and your knees bent.', '["Sit on a flat bench with your feet flat on the ground and your knees bent.","Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Engage your core and slowly twist your torso to one side, keeping your back straight.","Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0094', '/media/exercises/0094-dFSNDOA.gif', '/media/posters/0094-dFSNDOA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Side Bent V. 2', 'ABS', 'OBLIQUES,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.', '["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Pause for a moment, then return to the starting position.","Repeat the movement on the left side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0096', '/media/exercises/0096-i4JkUaL.gif', '/media/posters/0096-i4JkUaL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Side Split Squat V. 2', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Hold a barbell across your upper back, resting it on your shoulders.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping out with your left foot.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0097', '/media/exercises/0097-HUEqZ1y.gif', '/media/posters/0097-HUEqZ1y.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Single Leg Deadlift', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.', '["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Shift your weight onto your left foot and lift your right foot slightly off the ground.","Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1756', '/media/exercises/1756-gEyURal.gif', '/media/posters/1756-gEyURal.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Single Leg Split Squat', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back.', '["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with one leg, keeping your torso upright.","Lower your body by bending your front knee and hip, while keeping your back leg straight.","Continue lowering until your front thigh is parallel to the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0099', '/media/exercises/0099-gGNQmVt.gif', '/media/posters/0099-gGNQmVt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Sitted Alternate Leg Raise', 'ABS', 'HIP FLEXORS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and hold a barbell across your thighs.', '["Sit on a bench with your back straight and hold a barbell across your thighs.","Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Lower the raised leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2799', '/media/exercises/2799-G7xoEzr.gif', '/media/posters/2799-G7xoEzr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Sitted Alternate Leg Raise (female)', 'ABS', 'HIP FLEXORS,QUADRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and hold a barbell across your thighs.', '["Sit on a bench with your back straight and hold a barbell across your thighs.","Place your hands on the sides of the bench for support.","Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Lower the leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2800', '/media/exercises/2800-BCs0G2F.gif', '/media/posters/2800-BCs0G2F.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Skier', 'SHOULDERS', 'TRICEPS,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.', '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0100', '/media/exercises/0100-4Leypho.gif', '/media/posters/0100-4Leypho.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Speed Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes slightly turned out.', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0101', '/media/exercises/0101-euI1BwR.gif', '/media/posters/0101-euI1BwR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Split Squat V. 2', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with your right foot, keeping your torso upright.","Lower your body by bending your knees and hips until your right thigh is parallel to the ground.","Pause for a moment, then push through your right heel to return to the starting position.","Repeat with your left leg forward for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2810', '/media/exercises/2810-HBYyX94.gif', '/media/posters/2810-HBYyX94.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Squat (on Knees)', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.', '["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0102', '/media/exercises/0102-oR7O9LW.gif', '/media/posters/0102-oR7O9LW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Squat Jump Step Rear Lunge', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Explode upwards, jumping off the ground as high as you can.","Land softly on your feet and immediately step back with one leg into a reverse lunge.","Lower your body down until your front thigh is parallel to the ground, keeping your back straight.","Push through your front heel to return to the starting position.","Repeat the jump and lunge sequence on the other leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2798', '/media/exercises/2798-RYcV1kH.gif', '/media/posters/2798-RYcV1kH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Ab Rollerout', 'ABS', 'SHOULDERS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.', '["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.","Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.","Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.","Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0103', '/media/exercises/0103-xnInPfE.gif', '/media/posters/0103-xnInPfE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Back Wrist Curl', 'FOREARMS', 'BICEPS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.","Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.","Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0104', '/media/exercises/0104-2qTvJAZ.gif', '/media/posters/0104-2qTvJAZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Close Grip Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0106', '/media/exercises/0106-4dUn2iv.gif', '/media/posters/0106-4dUn2iv.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Close Grip Military Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.', '["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows close to your body.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1456', '/media/exercises/1456-wdRZISl.gif', '/media/posters/1456-wdRZISl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Concentration Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.', '["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.","Rest your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2414', '/media/exercises/2414-vsMcDi9.gif', '/media/posters/2414-vsMcDi9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Front Raise Over Head', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.","Keep your back straight and engage your core.","Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.","Continue lifting until the barbell is slightly above shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0107', '/media/exercises/0107-S8mo30S.gif', '/media/posters/0107-S8mo30S.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Overhead Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0109', '/media/exercises/0109-dZl9Q27.gif', '/media/posters/0109-dZl9Q27.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Reverse Grip Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0110', '/media/exercises/0110-LWuA3aZ.gif', '/media/posters/0110-LWuA3aZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Rocking Leg Calf Raise', 'CALVES', 'HAMSTRINGS,QUADRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back.', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Raise your heels off the ground as high as possible, balancing on the balls of your feet.","Slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0111', '/media/exercises/0111-6HiHHe0.gif', '/media/posters/0111-6HiHHe0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Twist', 'ABS', 'OBLIQUES,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.', '["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.","Engage your core and keep your back straight throughout the exercise.","Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0112', '/media/exercises/0112-yQe5HpE.gif', '/media/posters/0112-yQe5HpE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Wide Grip Biceps Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.', '["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your back straight and your elbows close to your torso.","Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1629', '/media/exercises/1629-faHKVkK.gif', '/media/posters/1629-faHKVkK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Wide Military Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.', '["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.","Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1457', '/media/exercises/1457-Kyd9Rz5.gif', '/media/posters/1457-Kyd9Rz5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Standing Wide-grip Curl', 'BICEPS', 'FOREARMS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body.","Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0113', '/media/exercises/0113-NdIb5Z1.gif', '/media/posters/0113-NdIb5Z1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Step-up', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of a bench or step with a barbell resting on your upper back.', '["Stand in front of a bench or step with a barbell resting on your upper back.","Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your heel and step up onto the bench or step, fully extending your hip and knee.","Pause briefly at the top, then lower yourself back down to the starting position.","Repeat with the opposite leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0114', '/media/exercises/0114-Kxquu2E.gif', '/media/posters/0114-Kxquu2E.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Stiff Leg Good Morning', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the barbell across your upper back, resting it on your traps.","Keeping your back straight, hinge forward at the hips, pushing your glutes back.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0115', '/media/exercises/0115-JrOHAZc.gif', '/media/posters/0115-JrOHAZc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Straight Leg Deadlift', 'HAMSTRINGS', 'GLUTES,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your toes pointing forward.', '["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Lower the barbell until you feel a stretch in your hamstrings.","Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0116', '/media/exercises/0116-hrVQWvE.gif', '/media/posters/0116-hrVQWvE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Sumo Deadlift', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,LOWER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards.', '["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Place a barbell on the ground in front of you, centered between your feet.","Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.","Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.","As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0117', '/media/exercises/0117-KgI0tqW.gif', '/media/posters/0117-KgI0tqW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/3305-f7Y9eDZ.gif', poster_url = '/media/posters/3305-f7Y9eDZ.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_3305', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Thruster') AND (media_url IS NULL OR media_url = '');
UPDATE exercises SET media_url = '/media/exercises/0120-UDlhcO8.gif', poster_url = '/media/posters/0120-UDlhcO8.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0120', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Upright Row') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Upright Row V. 2', 'SHOULDERS', 'TRAPS,BICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0119', '/media/exercises/0119-83HoW9X.gif', '/media/posters/0119-83HoW9X.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Upright Row V. 3', 'SHOULDERS', 'TRAPS,BICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0121', '/media/exercises/0121-fI18Rbc.gif', '/media/posters/0121-fI18Rbc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Wide Bench Press', 'CHEST', 'SHOULDERS,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0122', '/media/exercises/0122-JsKq9so.gif', '/media/posters/0122-JsKq9so.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Wide Reverse Grip Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1258', '/media/exercises/1258-945zpRg.gif', '/media/posters/1258-945zpRg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Wide Squat', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0124', '/media/exercises/0124-s7HX1BY.gif', '/media/posters/0124-s7HX1BY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Wide-grip Upright Row', 'SHOULDERS', 'TRAPS,BICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0123', '/media/exercises/0123-RgJDRR1.gif', '/media/posters/0123-RgJDRR1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0126-82LxxkW.gif', poster_url = '/media/posters/0126-82LxxkW.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0126', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Barbell Wrist Curl') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Wrist Curl V. 2', 'FOREARMS', 'BICEPS,BRACHIALIS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and your knees bent.', '["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0125', '/media/exercises/0125-6kSxYnw.gif', '/media/posters/0125-6kSxYnw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Barbell Zercher Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and toes slightly turned out.', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0127', '/media/exercises/0127-LSTChY9.gif', '/media/posters/0127-LSTChY9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Basic Toe Touch (male)', 'GLUTES', 'HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your arms by your sides.', '["Stand with your feet shoulder-width apart and your arms by your sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with your hands, keeping your legs as straight as possible.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3212', '/media/exercises/3212-BbfB8Gb.gif', '/media/posters/3212-BbfB8Gb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0128-RJa4tCo.gif', poster_url = '/media/posters/0128-RJa4tCo.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0128', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Battling Ropes') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bear Crawl', 'CARDIO', 'CORE,SHOULDERS,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start on all fours with your hands directly under your shoulders and your knees directly under your hips.', '["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Continue crawling forward, alternating your hand and foot movements.","Maintain a steady pace and keep your core tight throughout the exercise.","Continue for the desired distance or time."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3360', '/media/exercises/3360-0Yz8WdV.gif', '/media/posters/3360-0Yz8WdV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bench Dip (knees Bent)', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.', '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0129', '/media/exercises/0129-RrLske5.gif', '/media/posters/0129-RrLske5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bench Hip Extension', 'GLUTES', 'HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back against the bench and your feet flat on the ground.', '["Sit on a bench with your back against the bench and your feet flat on the ground.","Place your hands on the bench for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0130', '/media/exercises/0130-u27Kcdz.gif', '/media/posters/0130-u27Kcdz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bench Pull-ups', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Position yourself under a bar or a sturdy horizontal surface that is at chest height.', '["Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Continue pulling until your chin is above the bar or surface.","Lower yourself back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3019', '/media/exercises/3019-mExgrF9.gif', '/media/posters/3019-mExgrF9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bent Knee Lying Twist (male)', 'GLUTES', 'OBLIQUES,HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms out to the sides, perpendicular to your body.","Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3639', '/media/exercises/3639-6sYyrRX.gif', '/media/posters/3639-6sYyrRX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Biceps Narrow Pull-ups', 'BICEPS', 'FOREARMS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.', '["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0139', '/media/exercises/0139-50BETrz.gif', '/media/posters/0139-50BETrz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Biceps Pull-up', 'BICEPS', 'FOREARMS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.', '["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0140', '/media/exercises/0140-guT8YnS.gif', '/media/posters/0140-guT8YnS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Drop Jump Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump up explosively, extending your hips, knees, and ankles.","While in mid-air, quickly bring your feet together.","Land softly on the balls of your feet and immediately drop back into a squat position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3543', '/media/exercises/3543-wfotm7S.gif', '/media/posters/3543-wfotm7S.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Incline Side Plank', 'ABS', 'OBLIQUES,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by lying on your side with your legs extended and stacked on top of each other.', '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the ground and repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3544', '/media/exercises/3544-5VXmnV5.gif', '/media/posters/3544-5VXmnV5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Kneeling Triceps Extension', 'TRICEPS', 'SHOULDERS,CHEST', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Kneel down on the ground with your knees hip-width apart.', '["Kneel down on the ground with your knees hip-width apart.","Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1771', '/media/exercises/1771-s0HKO2I.gif', '/media/posters/1771-s0HKO2I.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Side Lying Biceps Curl', 'BICEPS', 'FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs extended and your head supported by your arm.', '["Lie on your side with your legs extended and your head supported by your arm.","Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1769', '/media/exercises/1769-gscGLOU.gif', '/media/posters/1769-gscGLOU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Squatting Row', 'BACK', 'BICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.', '["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Lower your body into a squat position, keeping your back straight and your knees behind your toes.","From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3168', '/media/exercises/3168-3xK09Sk.gif', '/media/posters/3168-3xK09Sk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Squatting Row (with Towel)', 'BACK', 'BICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.', '["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3167', '/media/exercises/3167-BReCuOn.gif', '/media/posters/3167-BReCuOn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Standing Close-grip One Arm Row', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3156', '/media/exercises/3156-v2DfH14.gif', '/media/posters/3156-v2DfH14.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Standing Close-grip Row', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3158', '/media/exercises/3158-tig3PXb.gif', '/media/posters/3158-tig3PXb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Standing One Arm Row', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down in front of you, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3162', '/media/exercises/3162-xbkPfaw.gif', '/media/posters/3162-xbkPfaw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Standing One Arm Row (with Towel)', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3161', '/media/exercises/3161-O4oIqQD.gif', '/media/posters/3161-O4oIqQD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Standing Row', 'BACK', 'BICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Grasp a bar or handles with an overhand grip, palms facing down.","Keep your back straight and core engaged.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3166', '/media/exercises/3166-wd4ds3s.gif', '/media/posters/3166-wd4ds3s.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bodyweight Standing Row (with Towel)', 'BACK', 'BICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.', '["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3165', '/media/exercises/3165-uTv34oq.gif', '/media/posters/3165-uTv34oq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Box Jump Down With One Leg Stabilization', 'CALVES', 'QUADRICEPS,HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of a box or platform with your feet shoulder-width apart.', '["Stand in front of a box or platform with your feet shoulder-width apart.","Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Slowly step down with the foot that is on the box, returning to the starting position.","Repeat the exercise with the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1374', '/media/exercises/1374-iPm26QU.gif', '/media/posters/1374-iPm26QU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Bridge - Mountain Climber (cross Body)', 'ABS', 'GLUTES,QUADRICEPS,HAMSTRINGS,SHOULDERS,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Continue alternating sides, moving at a controlled pace.","Keep your hips level and avoid lifting your hips too high or sagging them too low.","Maintain a steady breathing pattern throughout the exercise.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2466', '/media/exercises/2466-9c6T1YX.gif', '/media/posters/2466-9c6T1YX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1160-dK9394r.gif', poster_url = '/media/posters/1160-dK9394r.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1160', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Burpee') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Alternate Shoulder Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.', '["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.","Position your hands at shoulder height, with your palms facing forward.","Keep your core engaged and your back straight.","Press one handle up and forward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0148', '/media/exercises/0148-KHPZL0b.gif', '/media/posters/0148-KHPZL0b.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Alternate Triceps Extension', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing the cable machine with your feet shoulder-width apart.', '["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.","Pause for a moment, then slowly return to the starting position.","Repeat with your left arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0149', '/media/exercises/0149-Gchi5Tr.gif', '/media/posters/0149-Gchi5Tr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Assisted Inverse Leg Curl', 'HAMSTRINGS', 'GLUTES,CALVES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine so that the ankle attachment is at the lowest setting.', '["Adjust the cable machine so that the ankle attachment is at the lowest setting.","Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Hold onto the handles of the bench for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3235', '/media/exercises/3235-zHEpuuc.gif', '/media/posters/3235-zHEpuuc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Bar Lateral Pulldown', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable pulley to a high position and attach a straight bar.', '["Adjust the cable pulley to a high position and attach a straight bar.","Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0150', '/media/exercises/0150-eYnzaCm.gif', '/media/posters/0150-eYnzaCm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine to chest height and attach the handles.', '["Adjust the cable machine to chest height and attach the handles.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step forward to create tension in the cables.","Position your feet firmly on the ground and engage your core.","Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.","Push the handles forward, extending your arms fully in front of you.","Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0151', '/media/exercises/0151-7xI5MXA.gif', '/media/posters/0151-7xI5MXA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Close Grip Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a low pulley cable machine.', '["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1630', '/media/exercises/1630-BCGQ6J5.gif', '/media/posters/1630-BCGQ6J5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Concentration Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.', '["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.","Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1631', '/media/exercises/1631-NvfE43H.gif', '/media/posters/1631-NvfE43H.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Concentration Extension (on Knee)', 'TRICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your knees bent and feet flat on the ground.', '["Sit on a bench or chair with your knees bent and feet flat on the ground.","Hold the cable handle with your right hand and place your elbow on the inside of your right knee.","Extend your arm fully, keeping your elbow stationary and close to your knee.","Pause for a moment at the top, then slowly lower your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0152', '/media/exercises/0152-Db7eEgw.gif', '/media/posters/0152-Db7eEgw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Cross-over Lateral Pulldown', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable handle to each side of a cable machine at shoulder height.', '["Attach a cable handle to each side of a cable machine at shoulder height.","Stand in the middle of the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step back to create tension in the cables.","Lean forward slightly from the hips, keeping your back straight and your chest up.","Pull the handles down and across your body, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0153', '/media/exercises/0153-OQ1otBN.gif', '/media/posters/0153-OQ1otBN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Cross-over Revers Fly', 'SHOULDERS', 'RHOMBOIDS,TRAPEZIUS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.', '["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.","Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.","With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0154', '/media/exercises/0154-aqvSOQE.gif', '/media/posters/0154-aqvSOQE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Cross-over Variation', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable pulleys to chest height.', '["Adjust the cable pulleys to chest height.","Stand in the center of the cable machine with one foot in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Take a step forward, keeping your arms slightly bent.","With a slight bend in your elbows, bring your hands together in front of your chest.","Pause for a moment, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0155', '/media/exercises/0155-0CXGHya.gif', '/media/posters/0155-0CXGHya.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Deadlift', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,LOWER BACK', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing the cable machine with your feet shoulder-width apart.', '["Stand facing the cable machine with your feet shoulder-width apart.","Bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.","Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.","Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0157', '/media/exercises/0157-eGDudUV.gif', '/media/posters/0157-eGDudUV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Decline Fly', 'CHEST', 'SHOULDERS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine to a decline position.', '["Adjust the cable machine to a decline position.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0158', '/media/exercises/0158-7saC5zz.gif', '/media/posters/0158-7saC5zz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Decline One Arm Press', 'CHEST', 'TRICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine to a decline position.', '["Adjust the cable machine to a decline position.","Stand facing away from the machine and grab the handle with one hand.","Position yourself with your back against the decline bench and your arm extended straight in front of you.","Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.","Pause for a moment at the bottom, then push the handle back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1260', '/media/exercises/1260-KHGNa16.gif', '/media/posters/1260-KHGNa16.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Decline Press', 'CHEST', 'TRICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine to a decline position.', '["Adjust the cable machine to a decline position.","Sit on the decline bench facing the cable machine.","Grasp the handles with an overhand grip and position them at chest level.","Keep your feet flat on the ground and your back firmly against the bench.","Exhale and push the handles away from your body, extending your arms fully.","Pause for a moment at the end of the movement, squeezing your chest muscles.","Inhale and slowly return the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1261', '/media/exercises/1261-2Pya1cP.gif', '/media/posters/1261-2Pya1cP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Decline Seated Wide-grip Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.', '["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.","Grasp the cable attachment with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0159', '/media/exercises/0159-kesXOpB.gif', '/media/posters/0159-kesXOpB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Drag Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1632', '/media/exercises/1632-dXz8zjF.gif', '/media/posters/1632-dXz8zjF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Floor Seated Wide-grip Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the floor with your legs extended and your back straight.', '["Sit on the floor with your legs extended and your back straight.","Attach a cable handle to a low pulley and position the cable machine behind you.","Grasp the handle with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your chest lifted.","Pull the handle towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0160', '/media/exercises/0160-veXwo0D.gif', '/media/posters/0160-veXwo0D.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Forward Raise', 'SHOULDERS', 'TRICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.","Keeping your arms straight, raise the cable handle up to shoulder level.","Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0161', '/media/exercises/0161-hvHhCv8.gif', '/media/posters/0161-hvHhCv8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Front Raise', 'SHOULDERS', 'TRICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.', '["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0162', '/media/exercises/0162-u2X71Np.gif', '/media/posters/0162-u2X71Np.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Front Shoulder Raise', 'SHOULDERS', 'TRAPEZIUS,BICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.', '["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0164', '/media/exercises/0164-mTT3KLn.gif', '/media/posters/0164-mTT3KLn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Hammer Curl (with Rope)', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand upright with your feet shoulder-width apart and a slight bend in your knees.', '["Stand upright with your feet shoulder-width apart and a slight bend in your knees.","Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the cable rope attachment back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0165', '/media/exercises/0165-HPlPoQA.gif', '/media/posters/0165-HPlPoQA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable High Pulley Overhead Tricep Extension', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to a high pulley and stand facing away from the machine.', '["Attach a rope to a high pulley and stand facing away from the machine.","Grasp the rope with both hands and extend your arms overhead.","Keep your elbows close to your head and your upper arms stationary.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1722', '/media/exercises/1722-1xHyxys.gif', '/media/posters/1722-1xHyxys.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable High Row (kneeling)', 'BACK', 'BICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a cable machine at chest height.', '["Attach a straight bar to a cable machine at chest height.","Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Sit back on your heels, keeping your back straight and your core engaged.","Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0167', '/media/exercises/0167-ZSJNetl.gif', '/media/posters/0167-ZSJNetl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Incline Bench Press', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the bench to a 45-degree incline.', '["Adjust the bench to a 45-degree incline.","Attach the cable handles to the high pulleys.","Sit on the bench facing the cable machine with your feet flat on the ground.","Grasp the handles with an overhand grip and bring them to shoulder height.","Push the handles forward and upward until your arms are fully extended.","Pause for a moment, then slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0169', '/media/exercises/0169-Vh0GsK4.gif', '/media/posters/0169-Vh0GsK4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Incline Bench Row', 'BACK', 'BICEPS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.', '["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the cable handle with an overhand grip and extend your arms fully in front of you.","Lean forward from your hips while keeping your back straight and your core engaged.","Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1318', '/media/exercises/1318-yaMIo4D.gif', '/media/posters/1318-yaMIo4D.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Incline Fly', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine to a low position and attach the handles.', '["Adjust the cable machine to a low position and attach the handles.","Sit on an incline bench with your back against the pad and feet flat on the floor.","Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0171', '/media/exercises/0171-tBWXbIT.gif', '/media/posters/0171-tBWXbIT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Incline Fly (on Stability Ball)', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Set up a stability ball at an incline angle.', '["Set up a stability ball at an incline angle.","Attach the cable handles to the high pulleys of a cable machine.","Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.","Grasp the cable handles with an overhand grip, palms facing forward.","Lean forward slightly, keeping your back straight and core engaged.","With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.","Continue the motion until your arms are parallel to the ground.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0170', '/media/exercises/0170-27NNGFr.gif', '/media/posters/0170-27NNGFr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0172-1PK5Uo3.gif', poster_url = '/media/posters/0172-1PK5Uo3.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0172', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Cable Incline Pushdown') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Kickback', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and step back to create tension in the cable.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your upper arm close to your body and your elbow bent at a 90-degree angle.","Extend your forearm backward, straightening your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0860', '/media/exercises/0860-HEJ6DIX.gif', '/media/posters/0860-HEJ6DIX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Kneeling Rear Delt Row (with Rope) (male)', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS,BICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope handle to a low cable pulley and kneel down facing the machine.', '["Attach a rope handle to a low cable pulley and kneel down facing the machine.","Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3697', '/media/exercises/3697-G61cXLk.gif', '/media/posters/3697-G61cXLk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Kneeling Triceps Extension', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope handle to a high pulley and kneel down facing the cable machine.', '["Attach a rope handle to a high pulley and kneel down facing the cable machine.","Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Extend your forearms by contracting your triceps until your arms are fully extended.","Pause for a moment, then slowly return to the starting position by bending your elbows.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0176', '/media/exercises/0176-KWdF2JI.gif', '/media/posters/0176-KWdF2JI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lat Pulldown Full Range Of Motion', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the lat pulldown machine with your knees positioned under the pads.', '["Sit on the lat pulldown machine with your knees positioned under the pads.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2330', '/media/exercises/2330-LEprlgG.gif', '/media/posters/2330-LEprlgG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lateral Pulldown (with Rope Attachment)', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope attachment to the cable machine at a high position.', '["Attach a rope attachment to the cable machine at a high position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back.","Pull the rope down towards your sides, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement.","Slowly release the tension and allow the rope to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0177', '/media/exercises/0177-CuaWCmC.gif', '/media/posters/0177-CuaWCmC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lateral Pulldown With V-bar', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.', '["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.","Adjust the knee pad so that your thighs are secured under it.","Keep your back straight and lean back slightly.","Pull the v-bar down towards your upper chest while keeping your elbows close to your body.","Squeeze your back muscles at the bottom of the movement.","Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2616', '/media/exercises/2616-4c9BhzB.gif', '/media/posters/2616-4c9BhzB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lateral Raise', 'SHOULDERS', 'TRAPS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.', '["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.","Keep your arms straight and your core engaged.","Raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0178', '/media/exercises/0178-goJ6ezq.gif', '/media/posters/0178-goJ6ezq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Low Fly', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach the handles to the low pulleys of a cable machine and select an appropriate weight.', '["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.","Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.","Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.","Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.","Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0179', '/media/exercises/0179-FVmZVhk.gif', '/media/posters/0179-FVmZVhk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Low Seated Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the machine with your feet flat on the footrests and your knees slightly bent.', '["Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0180', '/media/exercises/0180-hvV79Si.gif', '/media/posters/0180-hvV79Si.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lying Bicep Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a low pulley cable machine.', '["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1634', '/media/exercises/1634-otqIxU4.gif', '/media/posters/1634-otqIxU4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lying Close-grip Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a low pulley cable machine.', '["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0182', '/media/exercises/0182-61GrD55.gif', '/media/posters/0182-61GrD55.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lying Extension Pullover (with Rope Attachment)', 'BACK', 'TRICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to a cable machine and set the pulley at the highest position.', '["Attach a rope to a cable machine and set the pulley at the highest position.","Lie down on a bench with your head towards the cable machine.","Hold the rope with both hands and extend your arms straight up above your chest.","Keeping your arms straight, slowly lower the rope behind your head while maintaining control.","Pause for a moment at the bottom, then slowly raise the rope back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0184', '/media/exercises/0184-Q2Eu1Ax.gif', '/media/posters/0184-Q2Eu1Ax.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lying Fly', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.', '["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.","Hold the handles with your palms facing each other and your arms extended straight above your chest.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0185', '/media/exercises/0185-lJJ7Yq8.gif', '/media/posters/0185-lJJ7Yq8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Lying Triceps Extension V. 2', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope handle to a low pulley cable machine.', '["Attach a rope handle to a low pulley cable machine.","Lie down on a flat bench facing up, with your head towards the cable machine.","Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0186', '/media/exercises/0186-uxJcFUU.gif', '/media/posters/0186-uxJcFUU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Middle Fly', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach cables to both sides of a cable machine at chest height.', '["Attach cables to both sides of a cable machine at chest height.","Stand in the center of the machine with one foot slightly in front of the other.","Grasp the handles with an overhand grip and extend your arms out to the sides.","Keep a slight bend in your elbows and maintain a slight forward lean.","Engage your chest muscles and bring your arms forward in a sweeping motion.","Pause for a moment at the center, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0188', '/media/exercises/0188-xLYSdtg.gif', '/media/posters/0188-xLYSdtg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.","Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.","Pause for a moment, then slowly extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0189', '/media/exercises/0189-EIsE3u8.gif', '/media/posters/0189-EIsE3u8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing the cable machine with your feet shoulder-width apart.', '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing up.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0190', '/media/exercises/0190-YTur5nR.gif', '/media/posters/0190-YTur5nR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Decline Chest Fly', 'CHEST', 'SHOULDERS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.', '["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.","Lie down on the bench with your head towards the machine and grab the handle with your right hand.","Extend your arm straight up above your chest, keeping a slight bend in your elbow.","With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then reverse the motion and bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1262', '/media/exercises/1262-w4dLzSx.gif', '/media/posters/1262-w4dLzSx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Fly On Exercise Ball', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Keep your elbow slightly bent and your palm facing forward.","Slowly bring your arm across your body, squeezing your chest muscles.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1263', '/media/exercises/1263-hHy8tQG.gif', '/media/posters/1263-hHy8tQG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Incline Fly On Exercise Ball', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.', '["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.","Hold a cable handle in one hand with your arm extended and palm facing inward.","Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1264', '/media/exercises/1264-P14Dz9D.gif', '/media/posters/1264-P14Dz9D.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Incline Press', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine to a low pulley position.', '["Adjust the cable machine to a low pulley position.","Sit on an incline bench facing away from the cable machine.","Grasp the handle with one hand and bring it up to shoulder height.","Position your feet firmly on the ground and maintain a stable position.","Press the handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1265', '/media/exercises/1265-GKEH6jj.gif', '/media/posters/1265-GKEH6jj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Incline Press On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.', '["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.","Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Press the cable handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1266', '/media/exercises/1266-6t00BsF.gif', '/media/posters/1266-6t00BsF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Lateral Bent-over', 'CHEST', 'DELTOIDS,TRAPEZIUS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, facing a cable machine.', '["Stand with your feet shoulder-width apart, facing a cable machine.","Grasp the handle with one hand and step back to create tension on the cable.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.","Slowly bring your arm back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0191', '/media/exercises/0191-dB07vDu.gif', '/media/posters/0191-dB07vDu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Lateral Raise', 'SHOULDERS', 'TRAPS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, facing the cable machine.', '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0192', '/media/exercises/0192-wEulIzp.gif', '/media/posters/0192-wEulIzp.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Preacher Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine so that the preacher curl pad is at chest height.', '["Adjust the cable machine so that the preacher curl pad is at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.","Keep your back straight and your core engaged.","Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1633', '/media/exercises/1633-eHBlPsa.gif', '/media/posters/1633-eHBlPsa.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Press On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and position your arm at chest height, elbow bent.","Place your other hand on your hip for stability.","Press the cable handle forward, extending your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1267', '/media/exercises/1267-MKIelrR.gif', '/media/posters/1267-MKIelrR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Pulldown', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a single handle to a high pulley cable machine.', '["Attach a single handle to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip and extend your arm fully.","Keep your back straight and your core engaged.","Pull the handle down towards your side while keeping your elbow close to your body.","Pause for a moment at the bottom of the movement, squeezing your lat muscle.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3563', '/media/exercises/3563-U5INZY6.gif', '/media/posters/3563-U5INZY6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Reverse Preacher Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine so that the pulley is at the lowest position.', '["Adjust the cable machine so that the pulley is at the lowest position.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1635', '/media/exercises/1635-ZXnjcOQ.gif', '/media/posters/1635-ZXnjcOQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Straight Back High Row (kneeling)', 'BACK', 'BICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a handle to a cable machine at waist height.', '["Attach a handle to a cable machine at waist height.","Kneel down facing the cable machine and grab the handle with one hand.","Keep your back straight and your core engaged.","Pull the handle towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0193', '/media/exercises/0193-WrYPP2g.gif', '/media/posters/0193-WrYPP2g.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable One Arm Tricep Pushdown', 'TRICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with a straight bar attachment at chest height.', '["Stand facing a cable machine with a straight bar attachment at chest height.","Grasp the bar with an overhand grip and step back to create tension in the cable.","Position your feet shoulder-width apart and slightly bend your knees.","Keep your back straight and core engaged throughout the exercise.","Start with your arm fully extended and perpendicular to the floor.","Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.","Pause for a moment, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1723', '/media/exercises/1723-qRZ5S1N.gif', '/media/posters/1723-qRZ5S1N.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Overhead Curl', 'BICEPS', 'FOREARMS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a high pulley cable machine.', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1636', '/media/exercises/1636-wDUqY2u.gif', '/media/posters/1636-wDUqY2u.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Overhead Curl On Exercise Ball', 'BICEPS', 'FOREARMS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball and hold the cable handle with an underhand grip.', '["Sit on an exercise ball and hold the cable handle with an underhand grip.","Extend your arms fully overhead, keeping your elbows close to your ears.","Slowly curl the cable down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1637', '/media/exercises/1637-ioTf098.gif', '/media/posters/1637-ioTf098.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Overhead Triceps Extension (rope Attachment)', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to a cable machine at a high position.', '["Attach a rope to a cable machine at a high position.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing each other, and bring your hands above your head.","Keep your upper arms close to your head and your elbows pointing forward.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0194', '/media/exercises/0194-2IxROQ1.gif', '/media/posters/0194-2IxROQ1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Palm Rotational Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a handle to a cable machine at waist height.', '["Attach a handle to a cable machine at waist height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip, palms facing down.","Step back to create tension on the cable, keeping your back straight and knees slightly bent.","Pull the handle towards your body, rotating your palms to face upwards as you do so.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1319', '/media/exercises/1319-OmQ8w0p.gif', '/media/posters/1319-OmQ8w0p.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Press On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.', '["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.","Hold the cable handles at chest height with your palms facing down and your elbows bent.","Engage your core and press the cable handles forward until your arms are fully extended.","Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1268', '/media/exercises/1268-vAwm6rK.gif', '/media/posters/1268-vAwm6rK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Pull Through (with Rope)', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing away from the cable machine with your feet shoulder-width apart.', '["Stand facing away from the cable machine with your feet shoulder-width apart.","Grab the rope attachment with both hands and step forward, creating tension in the cable.","Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.","Engage your glutes and hamstrings to pull your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0196', '/media/exercises/0196-OM46QHm.gif', '/media/posters/0196-OM46QHm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Pulldown', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.', '["Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Sit on the seat with your back straight and your feet flat on the ground.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and engage your core.","Pull the cable bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0198', '/media/exercises/0198-RVwzP10.gif', '/media/posters/0198-RVwzP10.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Pulldown (pro Lat Bar)', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.', '["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.","Sit down and lean back slightly, keeping your chest up and your back straight.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0197', '/media/exercises/0197-qdRxqCj.gif', '/media/posters/0197-qdRxqCj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Pulldown Bicep Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to the cable machine at the highest setting.', '["Attach a straight bar to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1638', '/media/exercises/1638-QTXKWPh.gif', '/media/posters/1638-QTXKWPh.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Pushdown', 'TRICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a high pulley cable machine.', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and push the bar down until your elbows are fully extended.","Pause for a moment, then inhale and slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0201', '/media/exercises/0201-3ZflifB.gif', '/media/posters/0201-3ZflifB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Pushdown (straight Arm) V. 2', 'BACK', 'TRICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a high pulley cable machine.', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.","Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0199', '/media/exercises/0199-PskORrA.gif', '/media/posters/0199-PskORrA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Pushdown (with Rope Attachment)', 'TRICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope attachment to a high pulley on a cable machine.', '["Attach a rope attachment to a high pulley on a cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the rope with an overhand grip, palms facing each other.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and push the rope downward by extending your elbows until your arms are fully extended.","Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0200', '/media/exercises/0200-dU605di.gif', '/media/posters/0200-dU605di.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rear Delt Row (stirrups)', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS,BICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a stirrup handle to a low cable pulley and stand facing the machine.', '["Attach a stirrup handle to a low cable pulley and stand facing the machine.","Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.","Pause for a moment at the top of the movement, squeezing your shoulder blade.","Slowly release the handle back to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your right arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0202', '/media/exercises/0202-yUdIGNs.gif', '/media/posters/0202-yUdIGNs.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rear Delt Row (with Rope)', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS,BICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope handle to a low pulley cable machine.', '["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an overhand grip, palms facing each other.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0203', '/media/exercises/0203-wqNPGCg.gif', '/media/posters/0203-wqNPGCg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rear Drive', 'TRICEPS', 'SHOULDERS,BACK', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a handle to a low pulley cable machine and stand facing away from the machine.', '["Attach a handle to a low pulley cable machine and stand facing away from the machine.","Grasp the handle with an overhand grip and extend your arms straight out in front of you.","Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.","Slowly return the handle to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0204', '/media/exercises/0204-c3QQLPi.gif', '/media/posters/0204-c3QQLPi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rear Pulldown', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine so that the pulley is at the highest position.', '["Adjust the cable machine so that the pulley is at the highest position.","Sit facing the machine with your feet flat on the ground and your knees slightly bent.","Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.","Lean back slightly, keeping your back straight and your chest up.","Pull the cable attachment down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0205', '/media/exercises/0205-SpsOSXk.gif', '/media/posters/0205-SpsOSXk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Reverse Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a low pulley cable machine.', '["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0206', '/media/exercises/0206-eOG0r6v.gif', '/media/posters/0206-eOG0r6v.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Reverse Grip Triceps Pushdown (sz-bar) (with Arm Blaster)', 'TRICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to the cable machine at the highest setting.', '["Attach a straight bar to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and slowly push the bar down until your arms are fully extended.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2406', '/media/exercises/2406-ThKP69G.gif', '/media/posters/2406-ThKP69G.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Reverse One Arm Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing down.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1413', '/media/exercises/1413-gVlnLIJ.gif', '/media/posters/1413-gVlnLIJ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Reverse Preacher Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine so that the preacher curl pad is at chest height.', '["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.","Grab the cable handles with an underhand grip, shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0209', '/media/exercises/0209-IwX5NqK.gif', '/media/posters/0209-IwX5NqK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Reverse Wrist Curl', 'FOREARMS', 'FOREARMS,WRISTS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable to a low pulley and sit on a bench facing the cable machine.', '["Attach a cable to a low pulley and sit on a bench facing the cable machine.","Grasp the cable handle with an overhand grip, palms facing down.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0210', '/media/exercises/0210-eYmsEPR.gif', '/media/posters/0210-eYmsEPR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Reverse-grip Pushdown', 'TRICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a high pulley cable machine.', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.","Pause for a moment, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0207', '/media/exercises/0207-VjYliFZ.gif', '/media/posters/0207-VjYliFZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Reverse-grip Straight Back Seated High Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the seat facing the cable machine with your feet flat on the floor.', '["Sit on the seat facing the cable machine with your feet flat on the floor.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from your hips.","Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0208', '/media/exercises/0208-PNtsX17.gif', '/media/posters/0208-PNtsX17.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope Crossover Seated Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.', '["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable ropes towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1320', '/media/exercises/1320-UFGF6gk.gif', '/media/posters/1320-UFGF6gk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope Elevated Seated Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the elevated seat facing the cable machine.', '["Sit on the elevated seat facing the cable machine.","Grab the cable rope handles with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back, maintaining a slight bend in your knees.","Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the fully contracted position.","Slowly release the tension and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1321', '/media/exercises/1321-c8oybX6.gif', '/media/posters/1321-c8oybX6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope Extension Incline Bench Row', 'BACK', 'BICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.', '["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Attach a rope handle to the cable machine and sit on the incline bench facing the machine.","Grab the rope handle with an overhand grip and lean forward, keeping your back straight.","Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1322', '/media/exercises/1322-MgKwAAo.gif', '/media/posters/1322-MgKwAAo.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope Hammer Preacher Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope attachment to a low pulley cable machine.', '["Attach a rope attachment to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with a neutral grip (palms facing each other).","Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the rope back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1639', '/media/exercises/1639-PcPe0P5.gif', '/media/posters/1639-PcPe0P5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope High Pulley Overhead Tricep Extension', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to a high pulley and adjust the weight accordingly.', '["Attach a rope to a high pulley and adjust the weight accordingly.","Stand facing away from the pulley machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down, and bring your hands above your head.","Keep your upper arms close to your head and perpendicular to the floor.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1724', '/media/exercises/1724-NN8nSNT.gif', '/media/posters/1724-NN8nSNT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope Incline Tricep Extension', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.', '["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Stand facing away from the pulley with your feet shoulder-width apart.","Grasp the rope with an overhand grip and extend your arms straight overhead.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1725', '/media/exercises/1725-ZujAdR9.gif', '/media/posters/1725-ZujAdR9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope Lying On Floor Tricep Extension', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to a cable machine and set it to the lowest position.', '["Attach a rope to a cable machine and set it to the lowest position.","Lie on the floor facing up, with your head towards the cable machine.","Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.","Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1726', '/media/exercises/1726-U3ffHlY.gif', '/media/posters/1726-U3ffHlY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope One Arm Hammer Preacher Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope handle to a low pulley cable machine.', '["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an underhand grip, palms facing up.","Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1640', '/media/exercises/1640-4hATdoB.gif', '/media/posters/1640-4hATdoB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Rope Seated Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.', '["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the cable ropes towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1323', '/media/exercises/1323-SJqRxOt.gif', '/media/posters/1323-SJqRxOt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Russian Twists (on Stability Ball)', 'ABS', 'OBLIQUES,LOWER BACK', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold the cable handle with both hands and extend your arms straight out in front of you.","Lean back slightly while keeping your back straight and your core engaged.","Twist your torso to the right, bringing the cable handle towards your right hip.","Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.","Continue alternating twists for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0211', '/media/exercises/0211-d9Xaxq6.gif', '/media/posters/0211-d9Xaxq6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated Chest Press', 'CHEST', 'SHOULDERS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and cable handles to a comfortable position.', '["Adjust the seat height and cable handles to a comfortable position.","Sit on the bench with your back straight and feet flat on the floor.","Grasp the cable handles with an overhand grip at shoulder height.","Push the handles forward and away from your body, extending your arms fully.","Pause for a moment, then slowly bring the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2144', '/media/exercises/2144-nIR4Rwl.gif', '/media/posters/2144-nIR4Rwl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a cable machine with your feet flat on the ground and your back straight.', '["Sit on a cable machine with your feet flat on the ground and your back straight.","Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1641', '/media/exercises/1641-8oYqOt9.gif', '/media/posters/1641-8oYqOt9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated High Row (v-bar)', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the cable machine with your feet flat on the floor and your knees slightly bent.', '["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from the hips.","Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0213', '/media/exercises/0213-pwt0pnM.gif', '/media/posters/0213-pwt0pnM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated One Arm Alternate Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.', '["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.","Grasp the handle with one hand and keep your arm fully extended in front of you.","Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.","Pause for a moment at the top of the movement, squeezing your back muscles.","Slowly release the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0214', '/media/exercises/0214-vpp9Ku2.gif', '/media/posters/0214-vpp9Ku2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated One Arm Concentration Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the floor and your back straight.', '["Sit on a bench with your feet flat on the floor and your back straight.","Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position while inhaling.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1642', '/media/exercises/1642-rZ80Gbp.gif', '/media/posters/1642-rZ80Gbp.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated Overhead Curl', 'BICEPS', 'FOREARMS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench facing the cable machine with your feet flat on the ground.', '["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your upper arms stationary and your elbows close to your sides.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1643', '/media/exercises/1643-DpWMFP5.gif', '/media/posters/1643-DpWMFP5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated Rear Lateral Raise', 'SHOULDERS', 'TRAPS,RHOMBOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench facing the cable machine with your feet flat on the ground.', '["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable handles with an overhand grip and extend your arms straight in front of you.","Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0215', '/media/exercises/0215-x825CZm.gif', '/media/posters/0215-x825CZm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated Shoulder Internal Rotation', 'SHOULDERS', 'ROTATOR CUFF,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair facing the cable machine with your feet flat on the ground.', '["Sit on a bench or chair facing the cable machine with your feet flat on the ground.","Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back and down.","Slowly rotate your arm inward, bringing the cable handle towards the center of your body.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0216', '/media/exercises/0216-YPoVrBi.gif', '/media/posters/0216-YPoVrBi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated Twist', 'ABS', 'OBLIQUES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a cable machine with your feet flat on the ground and your knees slightly bent.', '["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.","Hold the cable handle with both hands and extend your arms straight in front of you.","Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.","Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2399', '/media/exercises/2399-UEjSrKI.gif', '/media/posters/2399-UEjSrKI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Seated Wide-grip Row', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.', '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handle with a wide overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the handle towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction.","Slowly release the handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0218', '/media/exercises/0218-qcY50ZD.gif', '/media/posters/0218-qcY50ZD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Side Bend', 'ABS', 'OBLIQUES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and grasp the cable handle with one hand.', '["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Keep your back straight and your core engaged.","Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Alternate sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0222', '/media/exercises/0222-wPypxFY.gif', '/media/posters/0222-wPypxFY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Side Bend Crunch (bosu Ball)', 'ABS', 'OBLIQUES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a cable handle in one hand.', '["Stand with your feet shoulder-width apart, holding a cable handle in one hand.","Place the other hand on your hip.","Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0221', '/media/exercises/0221-qatbkEd.gif', '/media/posters/0221-qatbkEd.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Side Crunch', 'ABS', 'OBLIQUES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable handle to a low pulley and stand sideways to the machine.', '["Attach a cable handle to a low pulley and stand sideways to the machine.","Grasp the handle with the hand furthest from the machine and place your other hand on your hip.","Keep your feet shoulder-width apart and your knees slightly bent.","With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0223', '/media/exercises/0223-q2ADGqV.gif', '/media/posters/0223-q2ADGqV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Squat Row (with Rope Attachment)', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to a cable machine at waist height.', '["Attach a rope to a cable machine at waist height.","Stand facing the cable machine with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Keep your elbows close to your body and continue pulling until your hands reach your chest.","Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1717', '/media/exercises/1717-f7fnAIB.gif', '/media/posters/1717-f7fnAIB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Squatting Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable handle to the lowest setting on a cable machine.', '["Attach a cable handle to the lowest setting on a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.","Lower your body into a squat position, keeping your back straight and knees behind your toes.","As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the curl, squeezing your biceps.","Slowly lower the cable handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1644', '/media/exercises/1644-3XFdb1Z.gif', '/media/posters/1644-3XFdb1Z.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Back Wrist Curl', 'FOREARMS', 'BICEPS,BRACHIALIS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with an overhand grip, palms facing down.","Keep your arms straight and your elbows close to your sides.","Slowly curl your wrists upward, bringing the cable handle towards your body.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0224', '/media/exercises/0224-VhX2JdE.gif', '/media/posters/0224-VhX2JdE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine handles or attach a cable ankle strap to your ankles.","Raise your heels off the ground by extending your ankles as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1375', '/media/exercises/1375-yl2IYyy.gif', '/media/posters/1375-yl2IYyy.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Cross-over High Reverse Fly', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a D-handle to each side of a cable machine at shoulder height.', '["Attach a D-handle to each side of a cable machine at shoulder height.","Stand in the middle of the cable machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.","Keep a slight bend in your elbows and maintain a straight back throughout the exercise.","Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.","Pause for a moment at the peak of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0225', '/media/exercises/0225-P5p0j8B.gif', '/media/posters/0225-P5p0j8B.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Crunch', 'ABS', 'OBLIQUES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable handle to a high pulley and stand facing away from the machine.', '["Attach a cable handle to a high pulley and stand facing away from the machine.","Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Stand with your feet shoulder-width apart and your knees slightly bent.","Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0226', '/media/exercises/0226-jpgqxiS.gif', '/media/posters/0226-jpgqxiS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Crunch (with Rope Attachment)', 'ABS', 'OBLIQUES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to a cable machine at chest height.', '["Attach a rope to a cable machine at chest height.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0874', '/media/exercises/0874-XU3ePuv.gif', '/media/posters/0874-XU3ePuv.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Fly', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach the handles to the cables at chest height.', '["Attach the handles to the cables at chest height.","Stand with your feet shoulder-width apart, facing away from the cable machine.","Grasp the handles with an overhand grip, palms facing forward.","Step forward slightly to create tension in the cables.","Keep your core engaged and your back straight throughout the exercise.","With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.","Squeeze your chest muscles at the peak of the movement.","Slowly reverse the movement, returning your arms to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0227', '/media/exercises/0227-Pr9Rhf4.gif', '/media/posters/0227-Pr9Rhf4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Hip Extension', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable to a low pulley and stand facing away from the machine.', '["Attach a cable to a low pulley and stand facing away from the machine.","Place the cable around your ankle and stand with your feet shoulder-width apart.","Keep your core engaged and your back straight throughout the exercise.","Slowly extend your leg straight back, squeezing your glutes at the top of the movement.","Pause for a moment, then return to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat with the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0228', '/media/exercises/0228-Kpajagk.gif', '/media/posters/0228-Kpajagk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Inner Curl', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable handle towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0229', '/media/exercises/0229-YwnI4ja.gif', '/media/posters/0229-YwnI4ja.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Lift', 'ABS', 'OBLIQUES,LOWER BACK', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing the cable machine with your feet shoulder-width apart.', '["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands and position it at waist height.","Engage your core and maintain a straight back throughout the exercise.","Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.","Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0230', '/media/exercises/0230-qFpAkpP.gif', '/media/posters/0230-qFpAkpP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing One Arm Triceps Extension', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, facing the cable machine.', '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Keep your elbow stationary and close to your body.","Slowly bend your elbow, lowering the cable handle towards the back of your head.","Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0231', '/media/exercises/0231-sYCcnon.gif', '/media/posters/0231-sYCcnon.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing One Leg Calf Raise', 'CALVES', 'ANKLES,FEET', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine for support.","Lift one leg off the ground and balance on the other leg.","Slowly raise your heel off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1376', '/media/exercises/1376-fgc9Xdl.gif', '/media/posters/1376-fgc9Xdl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Pulldown (with Rope)', 'BICEPS', 'FOREARMS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to the cable machine at the highest setting.', '["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Pull the rope down towards your thighs, squeezing your biceps.","Pause for a moment at the bottom, then slowly release the rope back up.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0232', '/media/exercises/0232-CvPn9WV.gif', '/media/posters/0232-CvPn9WV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Rear Delt Row (with Rope)', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS,BICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a cable machine with your feet shoulder-width apart.', '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Keep your back straight and your core engaged.","Pull the cable towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0233', '/media/exercises/0233-ZfyAGhK.gif', '/media/posters/0233-ZfyAGhK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Reverse Grip One Arm Overhead Tricep Extension', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing away from the cable machine with your feet shoulder-width apart.', '["Stand facing away from the cable machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.","Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1727', '/media/exercises/1727-i11JWU7.gif', '/media/posters/1727-i11JWU7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Row (v-bar)', 'BACK', 'BICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing the cable machine with your feet shoulder-width apart.', '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar attachment with an overhand grip, palms facing down.","Keep your back straight and your core engaged.","Pull the v-bar towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0234', '/media/exercises/0234-4f8RXP8.gif', '/media/posters/0234-4f8RXP8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Shoulder External Rotation', 'SHOULDERS', 'ROTATOR CUFF,TRAPEZIUS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with your arm extended in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back.","Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0235', '/media/exercises/0235-FWdVhcW.gif', '/media/posters/0235-FWdVhcW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Twist Row (v-bar)', 'BACK', 'BICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a v-bar attachment to a cable machine at chest height.', '["Attach a v-bar attachment to a cable machine at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down.","Take a step back to create tension in the cable.","Keep your back straight and core engaged throughout the exercise.","Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.","As you pull, twist your torso to one side, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, feeling the contraction in your upper back.","Slowly release the tension and return to the starting position, untwisting your torso.","Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0236', '/media/exercises/0236-JOZhu2h.gif', '/media/posters/0236-JOZhu2h.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Standing Up Straight Crossovers', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand in the middle of a cable machine with your feet shoulder-width apart.', '["Stand in the middle of a cable machine with your feet shoulder-width apart.","Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.","Pause for a moment, then slowly return to the starting position, keeping your arms extended.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1269', '/media/exercises/1269-UKWTJWR.gif', '/media/posters/1269-UKWTJWR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Straight Arm Pulldown (with Rope)', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a rope to the cable machine at the highest setting.', '["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down.","Extend your arms fully in front of you, keeping your elbows slightly bent.","Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0237', '/media/exercises/0237-DT14T9T.gif', '/media/posters/0237-DT14T9T.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Straight Back Seated Row', 'BACK', 'BICEPS,FOREARMS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.', '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the cable handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0239', '/media/exercises/0239-Tq6gbK6.gif', '/media/posters/0239-Tq6gbK6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Supine Reverse Fly', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.', '["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.","Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0240', '/media/exercises/0240-PQcUlDi.gif', '/media/posters/0240-PQcUlDi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Thibaudeau Kayak Row', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.', '["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.","Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Lean forward from your hips, keeping your back straight and your abs engaged.","Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.","Squeeze your back muscles at the top of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform with your left arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2464', '/media/exercises/2464-ZgwWBoC.gif', '/media/posters/2464-ZgwWBoC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Triceps Pushdown (v-bar)', 'TRICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a v-bar attachment to the cable machine at the highest setting.', '["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0241', '/media/exercises/0241-gAwDzB3.gif', '/media/posters/0241-gAwDzB3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Triceps Pushdown (v-bar) (with Arm Blaster)', 'TRICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a v-bar attachment to the cable machine at the highest setting.', '["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2405', '/media/exercises/2405-OxJk1fg.gif', '/media/posters/2405-OxJk1fg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Tuck Reverse Crunch', 'ABS', 'HIP FLEXORS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable to a low pulley and lie down on a mat facing up.', '["Attach a cable to a low pulley and lie down on a mat facing up.","Hold the cable with both hands and extend your arms straight up above your chest.","Bend your knees and lift your legs up, bringing your knees towards your chest.","At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.","Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0242', '/media/exercises/0242-TXtXc84.gif', '/media/posters/0242-TXtXc84.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Twist', 'ABS', 'OBLIQUES', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, facing the cable machine.', '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and twist your torso to the right, pulling the cable across your body.","Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.","Slowly return to the starting position, resisting the cable''s pull.","Repeat the movement to the left side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0243', '/media/exercises/0243-aVs3BR3.gif', '/media/posters/0243-aVs3BR3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Twist (up-down)', 'ABS', 'OBLIQUES,LOWER BACK', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, facing the cable machine.', '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0862', '/media/exercises/0862-fhZQPlV.gif', '/media/posters/0862-fhZQPlV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Twisting Pull', 'BACK', 'SHOULDERS,BICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a cable handle to a low pulley and stand facing the machine.', '["Attach a cable handle to a low pulley and stand facing the machine.","Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Position your feet shoulder-width apart, with your knees slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Pull the handle towards your body, rotating your torso to the right as you do so.","Squeeze your back muscles at the end of the movement.","Slowly return to the starting position, keeping tension on the cable.","Repeat for the desired number of repetitions, then switch sides and perform with your right hand."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0244', '/media/exercises/0244-zCgxPbV.gif', '/media/posters/0244-zCgxPbV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Two Arm Curl On Incline Bench', 'BICEPS', 'FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with your back against the pad and your feet flat on the ground.', '["Sit on an incline bench with your back against the pad and your feet flat on the ground.","Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1645', '/media/exercises/1645-H9y3Dkr.gif', '/media/posters/1645-H9y3Dkr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Two Arm Tricep Kickback', 'TRICEPS', 'SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1728', '/media/exercises/1728-vvNjDJS.gif', '/media/posters/1728-vvNjDJS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Underhand Pulldown', 'BACK', 'BICEPS,FOREARMS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine so that the pulldown bar is at a height above your head.', '["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and lean back slightly.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0245', '/media/exercises/0245-xBYcQHj.gif', '/media/posters/0245-xBYcQHj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Upper Chest Crossovers', 'CHEST', 'DELTOIDS,TRICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach the handles to the cables at chest height.', '["Attach the handles to the cables at chest height.","Stand in the center of the cable machine with one foot slightly in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Keep a slight bend in your elbows and engage your core.","Pull the cables together in front of your chest, crossing them over each other.","Squeeze your chest muscles at the peak of the movement.","Slowly release the cables back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1270', '/media/exercises/1270-j7XMAyn.gif', '/media/posters/1270-j7XMAyn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Upper Row', 'BACK', 'BICEPS,SHOULDERS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Attach a straight bar to a cable machine at chest height.', '["Attach a straight bar to a cable machine at chest height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the bar towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1324', '/media/exercises/1324-PQStVXH.gif', '/media/posters/1324-PQStVXH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Upright Row', 'SHOULDERS', 'TRAPS,BICEPS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.","Keep your back straight and your core engaged throughout the exercise.","Pull the cable attachment straight up towards your chin, leading with your elbows.","Pause for a moment at the top, squeezing your shoulder blades together.","Slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0246', '/media/exercises/0246-cALKspW.gif', '/media/posters/0246-cALKspW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cable Wide Grip Rear Pulldown Behind Neck', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine so that the pulldown bar is at a height above your head.', '["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with a wide overhand grip.","Keep your back straight and your chest up as you lean back slightly.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1325', '/media/exercises/1325-CmEr4pM.gif', '/media/posters/1325-CmEr4pM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Calf Push Stretch With Hands Against Wall', 'CALVES', 'HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a wall with your feet hip-width apart.', '["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step back with one foot, keeping your heel on the ground and your leg straight.","Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1407', '/media/exercises/1407-PzNxakt.gif', '/media/posters/1407-PzNxakt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cambered Bar Lying Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.', '["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.","Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.","With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0248', '/media/exercises/0248-R5swFnc.gif', '/media/posters/0248-R5swFnc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Captains Chair Straight Leg Raise', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.', '["Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.","Keep your upper body stable and your back straight.","Engage your abs and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2963', '/media/exercises/2963-weoDEpH.gif', '/media/posters/2963-weoDEpH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1548-xGgAGPm.gif', poster_url = '/media/posters/1548-xGgAGPm.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1548', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Chair Leg Extended Stretch') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Chest Dip (on Dip-pull-up Cage)', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Adjust the dip bars to a height that allows you to comfortably grip them.', '["Adjust the dip bars to a height that allows you to comfortably grip them.","Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Jump up and straighten your arms, supporting your body weight on the bars.","Bend your knees and cross your ankles behind you.","Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Push through your palms and extend your elbows to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1430', '/media/exercises/1430-XgWyAiA.gif', '/media/posters/1430-XgWyAiA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Chest Dip On Straight Bar', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Grab the parallel bars with your palms facing down and your arms fully extended.', '["Grab the parallel bars with your palms facing down and your arms fully extended.","Bend your knees and cross your ankles.","Lower your body by bending your arms until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2462', '/media/exercises/2462-LQFOrMn.gif', '/media/posters/2462-LQFOrMn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Chest Stretch With Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your back straight.', '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the exercise ball with both hands and extend your arms straight out in front of you.","Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1272', '/media/exercises/1272-ykA5tU7.gif', '/media/posters/1272-ykA5tU7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Chest Tap Push-up (male)', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower yourself, tap your chest with your right hand.","Push yourself back up to the starting position.","Repeat the movement, this time tapping your chest with your left hand.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3216', '/media/exercises/3216-7E06s6d.gif', '/media/posters/3216-7E06s6d.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Chin-ups (narrow Parallel Grip)', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.', '["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0253', '/media/exercises/0253-G70mEAJ.gif', '/media/posters/0253-G70mEAJ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Close Grip Chin-up', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.', '["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1327', '/media/exercises/1327-VnfUNW7.gif', '/media/posters/1327-VnfUNW7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Close-grip Push-up (on Knees)', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.', '["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Pause for a moment when your chest is just above the ground.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2398', '/media/exercises/2398-v3vLFW0.gif', '/media/posters/2398-v3vLFW0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Crab Twist Toe Touch', 'ABS', 'OBLIQUES,HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by sitting on the ground with your knees bent and feet flat on the floor.', '["Start by sitting on the ground with your knees bent and feet flat on the floor.","Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1468', '/media/exercises/1468-xgsGFVM.gif', '/media/posters/1468-xgsGFVM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Crunch (on Stability Ball)', 'ABS', 'HIP FLEXORS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso forward.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0271', '/media/exercises/0271-MCUhf1F.gif', '/media/posters/0271-MCUhf1F.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Crunch (on Stability Ball, Arms Straight)', 'ABS', 'HIP FLEXORS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0272', '/media/exercises/0272-Sn8wxAI.gif', '/media/posters/0272-Sn8wxAI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Curl-up', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3016', '/media/exercises/3016-g2oKspu.gif', '/media/posters/3016-g2oKspu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Curtsey Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Bend both knees as if you were curtsying, lowering your body towards the ground.","Keep your torso upright and your weight on your front foot.","Push through your front foot to return to the starting position.","Repeat on the other side, stepping diagonally behind and across your body with your left foot."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3769', '/media/exercises/3769-gUjqdei.gif', '/media/posters/3769-gUjqdei.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Cycle Cross Trainer', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the cycle cross trainer.', '["Adjust the seat height and position yourself on the cycle cross trainer.","Place your feet on the pedals and grip the handlebars.","Start pedaling in a smooth and controlled motion.","Maintain a steady pace and increase the resistance if desired.","Continue pedaling for the desired duration of your cardio workout."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2331', '/media/exercises/2331-XSCHmiI.gif', '/media/posters/2331-XSCHmiI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Decline Sit-up', 'ABS', 'HIP FLEXORS,LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your feet secured and your knees bent.', '["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0282', '/media/exercises/0282-QLL2gdc.gif', '/media/posters/0282-QLL2gdc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Deep Push Up', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1274', '/media/exercises/1274-vptOQ4N.gif', '/media/posters/1274-vptOQ4N.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Drop Push Up', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands slightly wider than shoulder-width apart.', '["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, quickly drop your knees to the ground.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1275', '/media/exercises/1275-Q497lAE.gif', '/media/posters/1275-Q497lAE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Alternate Biceps Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0285', '/media/exercises/0285-BU15nH4.gif', '/media/posters/0285-BU15nH4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Alternate Biceps Curl (with Arm Blaster)', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place the arm blaster on your upper arms, ensuring a secure fit.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2403', '/media/exercises/2403-CfKsRbG.gif', '/media/posters/2403-CfKsRbG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Alternate Hammer Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.', '["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1646', '/media/exercises/1646-fy7Tgy4.gif', '/media/posters/1646-fy7Tgy4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Alternate Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher bench with a dumbbell in each hand, palms facing up.', '["Sit on a preacher bench with a dumbbell in each hand, palms facing up.","Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.","Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.","Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1647', '/media/exercises/1647-NlfIbzq.gif', '/media/posters/1647-NlfIbzq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Alternate Seated Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.', '["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1648', '/media/exercises/1648-6em2Dxj.gif', '/media/posters/1648-6em2Dxj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Alternate Side Press', 'SHOULDERS', 'TRICEPS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.","Press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0286', '/media/exercises/0286-izMnLqz.gif', '/media/posters/0286-izMnLqz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Alternating Bicep Curl With Leg Raised On Exercise Ball', 'BICEPS', 'FOREARMS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place an exercise ball behind you and position one foot on top of it, keeping your balance.","With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.","Lower the dumbbell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1649', '/media/exercises/1649-Zwiw7XR.gif', '/media/posters/1649-Zwiw7XR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Alternating Seated Bicep Curl On Exercise Ball', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with the other arm.","Continue alternating curls for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1650', '/media/exercises/1650-J74XlNf.gif', '/media/posters/1650-J74XlNf.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Arnold Press', 'SHOULDERS', 'TRICEPS,UPPER CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.', '["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2137', '/media/exercises/2137-Xy4jlWA.gif', '/media/posters/2137-Xy4jlWA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Arnold Press V. 2', 'SHOULDERS', 'TRICEPS,UPPER CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.', '["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0287', '/media/exercises/0287-eOrFCnx.gif', '/media/posters/0287-eOrFCnx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Around Pullover', 'CHEST', 'TRICEPS,LATISSIMUS DORSI', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your head at one end and your feet firmly on the ground.', '["Lie flat on a bench with your head at one end and your feet firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0288', '/media/exercises/0288-vi8EhoE.gif', '/media/posters/0288-vi8EhoE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Bench Seated Press', 'SHOULDERS', 'TRICEPS,CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in each hand, resting on your thighs.', '["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Lean back and position the dumbbells to the sides of your chest, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0290', '/media/exercises/0290-3d7wHyd.gif', '/media/posters/0290-3d7wHyd.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Bench Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Place a dumbbell on the ground in front of a bench.', '["Place a dumbbell on the ground in front of a bench.","Stand facing away from the bench with your feet shoulder-width apart.","Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.","Once your glutes touch the bench, push through your heels to stand back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0291', '/media/exercises/0291-mnzcrIB.gif', '/media/posters/0291-mnzcrIB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Let your arms hang straight down towards the floor, with your elbows slightly bent.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0293', '/media/exercises/0293-BJ0Hz5L.gif', '/media/posters/0293-BJ0Hz5L.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Bicep Curl Lunge With Bowling Motion', 'BICEPS', 'FOREARMS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.","As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.","At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.","Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.","Repeat the lunge and curl motion, this time rotating your torso to the left.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1651', '/media/exercises/1651-1VpF8db.gif', '/media/posters/1651-1VpF8db.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Bicep Curl On Exercise Ball With Leg Raised', 'BICEPS', 'FOREARMS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.","While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1652', '/media/exercises/1652-2NImIAG.gif', '/media/posters/1652-2NImIAG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Bicep Curl With Stork Stance', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Extend one leg behind you, balancing on the toes of that foot.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1653', '/media/exercises/1653-uSkDMYl.gif', '/media/posters/1653-uSkDMYl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Biceps Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0294', '/media/exercises/0294-NbVPDMW.gif', '/media/posters/0294-NbVPDMW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Biceps Curl (with Arm Blaster)', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing forward.', '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2401', '/media/exercises/2401-nlJsbkW.gif', '/media/posters/2401-nlJsbkW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Biceps Curl Reverse', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.', '["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1654', '/media/exercises/1654-nFc4FyV.gif', '/media/posters/1654-nFc4FyV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Biceps Curl Squat', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1655', '/media/exercises/1655-niXESDw.gif', '/media/posters/1655-niXESDw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Biceps Curl V Sit On Bosu Ball', 'BICEPS', 'FOREARMS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1656', '/media/exercises/1656-H1XAdpk.gif', '/media/posters/1656-H1XAdpk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0295-7Hg55JG.gif', poster_url = '/media/posters/0295-7Hg55JG.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0295', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Clean') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Close Grip Press', 'TRICEPS', 'CHEST,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat bench with a dumbbell in each hand, resting on your thighs.', '["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1731', '/media/exercises/1731-7jGOBF3.gif', '/media/posters/1731-7jGOBF3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Close-grip Press', 'TRICEPS', 'CHEST,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat bench with a dumbbell in each hand, resting on your thighs.', '["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0296', '/media/exercises/0296-RxayqAZ.gif', '/media/posters/0296-RxayqAZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Contralateral Forward Lunge', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, keeping your back straight and core engaged.","Lower your body by bending both knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3635', '/media/exercises/3635-ecl28tP.gif', '/media/posters/3635-ecl28tP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Cross Body Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your body.', '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0298', '/media/exercises/0298-Qyk5J3p.gif', '/media/posters/0298-Qyk5J3p.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Cross Body Hammer Curl V. 2', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your body.', '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1657', '/media/exercises/1657-HDYiZcY.gif', '/media/posters/1657-HDYiZcY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Cuban Press V. 2', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2136', '/media/exercises/2136-BqgCRif.gif', '/media/posters/2136-BqgCRif.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Deadlift', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes pointing forward.', '["Stand with your feet shoulder-width apart, toes pointing forward.","Hold a dumbbell in each hand, palms facing your body, arms extended downwards.","Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.","Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0300', '/media/exercises/0300-nUwVh7b.gif', '/media/posters/0300-nUwVh7b.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Decline Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie down on a decline bench with your feet secured and your head lower than your hips.', '["Lie down on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0301', '/media/exercises/0301-DwhEmmE.gif', '/media/posters/0301-DwhEmmE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Decline Fly', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your feet secured and your head lower than your hips.', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0302', '/media/exercises/0302-xXm4nYq.gif', '/media/posters/0302-xXm4nYq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Decline Hammer Press', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your feet secured and your head lower than your hips.', '["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0303', '/media/exercises/0303-1qrWgZ2.gif', '/media/posters/0303-1qrWgZ2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Decline One Arm Fly', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.', '["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.","Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Rotate your wrist so that the palm of your hand is facing forward.","As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.","Exhale and use your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1276', '/media/exercises/1276-NL6YBwN.gif', '/media/posters/1276-NL6YBwN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1617-SHUMp5H.gif', poster_url = '/media/posters/1617-SHUMp5H.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1617', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Decline One Arm Hammer Press') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Decline Shrug', 'BACK', 'SHOULDERS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up a decline bench at a 45-degree angle.', '["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your arms fully extended towards the floor.","Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0305', '/media/exercises/0305-cwsAI4G.gif', '/media/posters/0305-cwsAI4G.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Decline Shrug V. 2', 'BACK', 'SHOULDERS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up a decline bench at a 45-degree angle.', '["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting on it.","Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.","Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.","Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0304', '/media/exercises/0304-bRlbdjK.gif', '/media/posters/0304-bRlbdjK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Decline Triceps Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.', '["Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Extend your arms fully, keeping your elbows close to your head.","Lower the dumbbells slowly behind your head, bending your elbows.","Pause for a moment, then raise the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0306', '/media/exercises/0306-OTgkHwR.gif', '/media/posters/0306-OTgkHwR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Decline Twist Fly', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie down on a decline bench with your head lower than your hips.', '["Lie down on a decline bench with your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0307', '/media/exercises/0307-reFHapa.gif', '/media/posters/0307-reFHapa.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Finger Curls', 'FOREARMS', 'WRIST FLEXORS,WRIST EXTENSORS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the ground and your back straight.', '["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.","Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.","Repeat for the desired number of repetitions, then switch to the other hand."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1437', '/media/exercises/1437-mtXengz.gif', '/media/posters/1437-mtXengz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Fly', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other.', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0308', '/media/exercises/0308-yz9nUhF.gif', '/media/posters/0308-yz9nUhF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Fly On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball and hold a dumbbell in each hand.', '["Sit on an exercise ball and hold a dumbbell in each hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Extend your arms straight up above your chest, palms facing each other.","Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1277', '/media/exercises/1277-Lt3iWnf.gif', '/media/posters/1277-Lt3iWnf.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Forward Lunge Triceps Extension', 'TRICEPS', 'SHOULDERS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up.","Extend your arms straight overhead, keeping your elbows close to your ears.","Lower the dumbbells behind your head by bending your elbows.","Pause for a moment, then straighten your arms to return to the starting position.","Repeat the movement for the desired number of repetitions, then switch legs and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1732', '/media/exercises/1732-XalXcvM.gif', '/media/posters/1732-XalXcvM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Front Raise', 'SHOULDERS', 'BICEPS,TRAPEZIUS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0310', '/media/exercises/0310-3eGE2JC.gif', '/media/posters/0310-3eGE2JC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Front Raise V. 2', 'SHOULDERS', 'TRAPEZIUS,BICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keep your back straight and engage your core.","Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0309', '/media/exercises/0309-Rr7S3yg.gif', '/media/posters/0309-Rr7S3yg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Full Can Lateral Raise', 'SHOULDERS', 'TRAPS,ROTATOR CUFF', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0311', '/media/exercises/0311-AQ0mC4Y.gif', '/media/posters/0311-AQ0mC4Y.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1760-yn8yg1r.gif', poster_url = '/media/posters/1760-yn8yg1r.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1760', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Goblet Squat') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Hammer Curl On Exercise Ball', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1659', '/media/exercises/1659-fY68AyX.gif', '/media/posters/1659-fY68AyX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Hammer Curl V. 2', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your torso.', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0312', '/media/exercises/0312-2NpxjC1.gif', '/media/posters/0312-2NpxjC1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Hammer Curls (with Arm Blaster)', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your torso.', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2402', '/media/exercises/2402-GNhAeJ0.gif', '/media/posters/2402-GNhAeJ0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell High Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing forward.', '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1664', '/media/exercises/1664-qAmNMJY.gif', '/media/posters/1664-qAmNMJY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Alternate Press', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs.', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.","Push the dumbbells up with your chest and shoulders, extending your arms fully.","Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.","Repeat for the desired number of repetitions, alternating arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3545', '/media/exercises/3545-TVdivgY.gif', '/media/posters/3545-TVdivgY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Biceps Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.', '["Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0315', '/media/exercises/0315-F3xgbjF.gif', '/media/posters/0315-F3xgbjF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Breeding', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing forward.","Start with your arms fully extended, perpendicular to the ground.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0316', '/media/exercises/0316-B3Rxp6L.gif', '/media/posters/0316-B3Rxp6L.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Curl V. 2', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.', '["Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0317', '/media/exercises/0317-RaflbWD.gif', '/media/posters/0317-RaflbWD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Fly', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set an incline bench to a 45-degree angle.', '["Set an incline bench to a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0319', '/media/exercises/0319-ESOd5Pl.gif', '/media/posters/0319-ESOd5Pl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Fly On Exercise Ball', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1278', '/media/exercises/1278-HYe1ZqR.gif', '/media/posters/1278-HYe1ZqR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Hammer Press', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.","Press the dumbbells up and away from your body until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0321', '/media/exercises/0321-PG1kcIb.gif', '/media/posters/0321-PG1kcIb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Hammer Press On Exercise Ball', 'TRICEPS', 'CHEST,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with a dumbbell in each hand, palms facing each other.', '["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells up and slightly inward, keeping your palms facing each other.","Extend your arms fully, squeezing your triceps at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1618', '/media/exercises/1618-wkgnGfb.gif', '/media/posters/1618-wkgnGfb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline One Arm Fly', 'CHEST', 'DELTOIDS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Adjust the incline bench to a 30-45 degree angle.', '["Adjust the incline bench to a 30-45 degree angle.","Sit on the bench with a dumbbell in one hand, resting it on your thigh.","Lie back on the bench, keeping your feet flat on the ground.","Hold the dumbbell with your arm extended straight up over your chest.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1279', '/media/exercises/1279-Gw2HFvW.gif', '/media/posters/1279-Gw2HFvW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline One Arm Fly On Exercise Ball', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with a dumbbell in one hand.', '["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1280', '/media/exercises/1280-LLNh6q5.gif', '/media/posters/1280-LLNh6q5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1619-LL1UiTX.gif', poster_url = '/media/posters/1619-LL1UiTX.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1619', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Incline One Arm Hammer Press') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline One Arm Hammer Press On Exercise Ball', 'TRICEPS', 'SHOULDERS,CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with a dumbbell in one hand.', '["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.","Press the dumbbell up towards the ceiling, straightening your arm.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1620', '/media/exercises/1620-jDnrkar.gif', '/media/posters/1620-jDnrkar.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline One Arm Lateral Raise', 'SHOULDERS', 'TRAPEZIUS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.', '["Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.","Lean forward and position your upper arm against the inside of your thigh.","Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.","Continue lifting until your arm is parallel to the floor.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0323', '/media/exercises/0323-aTNKZiC.gif', '/media/posters/0323-aTNKZiC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline One Arm Press', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with a dumbbell in one hand, resting on your thigh.', '["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.","Press the dumbbell upward and slightly inward, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1281', '/media/exercises/1281-rDAiRf9.gif', '/media/posters/1281-rDAiRf9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline One Arm Press On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.', '["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbell at shoulder height with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1282', '/media/exercises/1282-Bg5JKSH.gif', '/media/posters/1282-Bg5JKSH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Palm-in Press', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Plant your feet firmly on the ground and keep your back straight against the bench.","Start with the dumbbells at shoulder level, elbows bent and palms facing each other.","Press the dumbbells up and away from your body, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0324', '/media/exercises/0324-OVLmUuL.gif', '/media/posters/0324-OVLmUuL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Press On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with a dumbbell in each hand, palms facing forward.', '["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.","Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells upward, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1283', '/media/exercises/1283-bfiHMpI.gif', '/media/posters/1283-bfiHMpI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Raise', 'SHOULDERS', 'TRAPEZIUS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs.', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.","Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0325', '/media/exercises/0325-nxW6BkN.gif', '/media/posters/0325-nxW6BkN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Rear Lateral Raise', 'SHOULDERS', 'TRAPS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.","Extend your arms straight down with your palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0326', '/media/exercises/0326-vYk8lqw.gif', '/media/posters/0326-vYk8lqw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0328-6e2DcYX.gif', poster_url = '/media/posters/0328-6e2DcYX.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0328', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Incline Shoulder Raise') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Shrug', 'BACK', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.","Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0329', '/media/exercises/0329-JymLInS.gif', '/media/posters/0329-JymLInS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline T-raise', 'SHOULDERS', 'TRAPS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward and let your arms hang straight down, perpendicular to the floor.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3542', '/media/exercises/3542-jgbvVJ0.gif', '/media/posters/3542-jgbvVJ0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Triceps Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with a dumbbell in each hand, palms facing inwards.', '["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0330', '/media/exercises/0330-OVIKwsd.gif', '/media/posters/0330-OVIKwsd.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Twisted Flyes', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0331', '/media/exercises/0331-1PLE8e9.gif', '/media/posters/0331-1PLE8e9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Two Arm Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an incline bench with a dumbbell in each hand, resting on your thighs.', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Slowly lie back on the bench, keeping the dumbbells close to your chest.","Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1733', '/media/exercises/1733-U7D9Fx3.gif', '/media/posters/1733-U7D9Fx3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Incline Y-raise', 'BACK', 'SHOULDERS,REAR DELTOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3541', '/media/exercises/3541-PbzNu7c.gif', '/media/posters/3541-PbzNu7c.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Kickback', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0333', '/media/exercises/0333-W6PxUkg.gif', '/media/posters/0333-W6PxUkg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Kickbacks On Exercise Ball', 'TRICEPS', 'SHOULDERS,BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1734', '/media/exercises/1734-cAvTaSg.gif', '/media/posters/1734-cAvTaSg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Kneeling Bicep Curl Exercise Ball', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Kneel on the floor with an exercise ball in front of you.', '["Kneel on the floor with an exercise ball in front of you.","Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1660', '/media/exercises/1660-2JCuFTU.gif', '/media/posters/1660-2JCuFTU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lateral To Front Raise', 'SHOULDERS', 'TRAPEZIUS,BICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0335', '/media/exercises/0335-xMjBKwn.gif', '/media/posters/0335-xMjBKwn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lunge', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up as you lower your body.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0336', '/media/exercises/0336-RRWFUcw.gif', '/media/posters/0336-RRWFUcw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lunge With Bicep Curl', 'BICEPS', 'QUADRICEPS,HAMSTRINGS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.","Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1658', '/media/exercises/1658-Mz6lLcW.gif', '/media/posters/1658-Mz6lLcW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Extension (across Face)', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.","Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0337', '/media/exercises/0337-L2V5Nan.gif', '/media/posters/0337-L2V5Nan.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Alternate Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other.', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.","Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.","Repeat with the other arm, alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1729', '/media/exercises/1729-NfP83rA.gif', '/media/posters/1729-NfP83rA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Elbow Press', 'TRICEPS', 'CHEST,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0338', '/media/exercises/0338-eOCOwIR.gif', '/media/posters/0338-eOCOwIR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying External Shoulder Rotation', 'SHOULDERS', 'ROTATOR CUFF,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.', '["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Hold a dumbbell in your hand with your palm facing down.","Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0863', '/media/exercises/0863-bmBf7LN.gif', '/media/posters/0863-bmBf7LN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Femoral', 'HAMSTRINGS', 'GLUTES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.', '["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.","Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0339', '/media/exercises/0339-FkBIE6a.gif', '/media/posters/0339-FkBIE6a.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Hammer Press', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0340', '/media/exercises/0340-7gdLIXa.gif', '/media/posters/0340-7gdLIXa.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying On Floor Rear Delt Raise', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on the floor with a dumbbell in each hand, palms facing each other.', '["Lie face down on the floor with a dumbbell in each hand, palms facing each other.","Extend your arms straight out in front of you, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2470', '/media/exercises/2470-Ion0XWz.gif', '/media/posters/2470-Ion0XWz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying One Arm Deltoid Rear', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Extend your arm straight down towards the floor, keeping it close to your body.","Raise your arm up and back, squeezing your shoulder blade towards your spine.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0341', '/media/exercises/0341-gSw59a4.gif', '/media/posters/0341-gSw59a4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying One Arm Press', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.', '["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.","Hold the dumbbell at shoulder level with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0343', '/media/exercises/0343-zGSIWQi.gif', '/media/posters/0343-zGSIWQi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying One Arm Press V. 2', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your back supported and feet flat on the ground.', '["Lie flat on a bench with your back supported and feet flat on the ground.","Hold a dumbbell in one hand with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0342', '/media/exercises/0342-K3dIO25.gif', '/media/posters/0342-K3dIO25.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying One Arm Pronated Triceps Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground.', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0344', '/media/exercises/0344-wyaqzOS.gif', '/media/posters/0344-wyaqzOS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying One Arm Supinated Triceps Extension', 'TRICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground.', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0346', '/media/exercises/0346-zZlORz6.gif', '/media/posters/0346-zZlORz6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Pronation On Floor', 'FOREARMS', 'BICEPS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.', '["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Rotate your palms so they are facing down towards the floor.","Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.","Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.","Hold for a moment, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2705', '/media/exercises/2705-7RWNjiB.gif', '/media/posters/2705-7RWNjiB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Pullover On Exercise Ball', 'CHEST', 'TRICEPS,SHOULDERS,BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball and roll forward until your upper back is resting on the ball.', '["Sit on an exercise ball and roll forward until your upper back is resting on the ball.","Hold a dumbbell with both hands and extend your arms straight up over your chest.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1284', '/media/exercises/1284-iK59oEA.gif', '/media/posters/1284-iK59oEA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Rear Delt Row', 'BACK', 'SHOULDERS,BICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.', '["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1328', '/media/exercises/1328-XUUD0Fs.gif', '/media/posters/1328-XUUD0Fs.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Single Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.', '["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.","Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.","Pause briefly at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1735', '/media/exercises/1735-6MfS53i.gif', '/media/posters/1735-6MfS53i.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Supination On Floor', 'FOREARMS', 'BICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.', '["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Rotate your palms to face up, keeping your elbows close to your sides.","Slowly curl the dumbbells towards your shoulders, squeezing your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2706', '/media/exercises/2706-rEhi2o5.gif', '/media/posters/2706-rEhi2o5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Supine Biceps Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your back and head supported, and your feet flat on the ground.', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1661', '/media/exercises/1661-XVzF3iZ.gif', '/media/posters/1661-XVzF3iZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Supine Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.', '["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0350', '/media/exercises/0350-KUaZst7.gif', '/media/posters/0350-KUaZst7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Triceps Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other.', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping your elbows close to your body.","Lower the dumbbells down towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0351', '/media/exercises/0351-mpKZGWz.gif', '/media/posters/0351-mpKZGWz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Lying Wide Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.', '["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1662', '/media/exercises/1662-qm9veZw.gif', '/media/posters/1662-qm9veZw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Neutral Grip Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0352', '/media/exercises/0352-pP8wP2P.gif', '/media/posters/0352-pP8wP2P.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Bench Fly', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.', '["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Lie back on the bench, keeping the dumbbell pressed against your thigh.","Using your free hand, help lift the dumbbell up to the starting position.","Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1285', '/media/exercises/1285-o5Jsk92.gif', '/media/posters/1285-o5Jsk92.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Chest Fly On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.', '["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inward.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1286', '/media/exercises/1286-Bpkf41o.gif', '/media/posters/1286-Bpkf41o.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Concentration Curl (on Stability Ball)', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0353', '/media/exercises/0353-k5IpyHg.gif', '/media/posters/0353-k5IpyHg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Decline Chest Press', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with a dumbbell in one hand, resting on your chest.', '["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Place your feet flat on the ground and keep your back pressed against the bench.","Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1287', '/media/exercises/1287-REGM1dE.gif', '/media/posters/1287-REGM1dE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Fly On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.', '["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1288', '/media/exercises/1288-Am02iPd.gif', '/media/posters/1288-Am02iPd.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm French Press On Exercise Ball', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1736', '/media/exercises/1736-ziFKQXP.gif', '/media/posters/1736-ziFKQXP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Hammer Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.', '["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Hold the dumbbell with a neutral grip (palms facing your body).","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1663', '/media/exercises/1663-4dF3maG.gif', '/media/posters/1663-4dF3maG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Hammer Press On Exercise Ball', 'TRICEPS', 'SHOULDERS,CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Place your other hand on your hip for stability.","Press the dumbbell upwards, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1621', '/media/exercises/1621-VYmYxK5.gif', '/media/posters/1621-VYmYxK5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Incline Chest Press', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Adjust the incline bench to a 45-degree angle.', '["Adjust the incline bench to a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.","Push the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1289', '/media/exercises/1289-PDaMuyV.gif', '/media/posters/1289-PDaMuyV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Kickback', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps at the top of the movement.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0354', '/media/exercises/0354-bQy2Eni.gif', '/media/posters/0354-bQy2Eni.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Lateral Raise', 'SHOULDERS', 'TRAPEZIUS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Keep your back straight and your core engaged throughout the exercise.","Raise the dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0355', '/media/exercises/0355-n5cWCsI.gif', '/media/posters/0355-n5cWCsI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Lateral Raise With Support', 'SHOULDERS', 'TRAPEZIUS,ROTATOR CUFF', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.","Place your other hand on a stable surface, such as a bench or wall, for support.","Keep your back straight and engage your core.","Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0356', '/media/exercises/0356-Yg7MJAT.gif', '/media/posters/0356-Yg7MJAT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Press On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1290', '/media/exercises/1290-QZFv5ui.gif', '/media/posters/1290-QZFv5ui.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Prone Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing down.', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.","Extend your arm fully, letting it hang straight down towards the floor.","Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1665', '/media/exercises/1665-JWjujiY.gif', '/media/posters/1665-JWjujiY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Prone Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1666', '/media/exercises/1666-LIGZSTA.gif', '/media/posters/1666-LIGZSTA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Pullover On Exercise Ball', 'CHEST', 'TRICEPS,LATISSIMUS DORSI,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with one hand and extend your arm straight up above your chest.","Slowly lower the dumbbell behind your head while keeping your arm straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1291', '/media/exercises/1291-bQHPBU3.gif', '/media/posters/1291-bQHPBU3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Reverse Wrist Curl', 'FOREARMS', 'WRIST EXTENSORS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the ground.', '["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, palm facing down.","Rest your forearm on your thigh, with your wrist hanging off the edge.","Slowly lower the dumbbell towards the ground by flexing your wrist.","Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0358', '/media/exercises/0358-BwSNDGt.gif', '/media/posters/0358-BwSNDGt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Reverse Fly (with Support)', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and your back straight.', '["Sit on a bench with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards.","Lean forward and place your free hand on the bench for support.","Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0359', '/media/exercises/0359-e25F58f.gif', '/media/posters/0359-e25F58f.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Reverse Grip Press', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.', '["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.","Place your feet flat on the ground and keep your back straight.","Raise the dumbbell to shoulder height, keeping your elbow close to your body.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1622', '/media/exercises/1622-Ze7MoIb.gif', '/media/posters/1622-Ze7MoIb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Reverse Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.', '["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.","Lower the dumbbell slowly until your arm is fully extended.","Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1414', '/media/exercises/1414-bWxq4op.gif', '/media/posters/1414-bWxq4op.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Reverse Spider Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.', '["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1667', '/media/exercises/1667-VdLZ3nB.gif', '/media/posters/1667-VdLZ3nB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Seated Bicep Curl On Exercise Ball', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1668', '/media/exercises/1668-s999Hdo.gif', '/media/posters/1668-s999Hdo.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Seated Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand with a neutral grip (palms facing each other).","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1669', '/media/exercises/1669-jK2hZ6n.gif', '/media/posters/1669-jK2hZ6n.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Seated Neutral Wrist Curl', 'FOREARMS', 'BICEPS,BRACHIALIS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your forearm on your thigh, allowing your wrist to hang off the edge.","Keeping your forearm stationary, curl your wrist upward as far as possible.","Pause for a moment at the top, then slowly lower your wrist back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other hand."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1415', '/media/exercises/1415-YtaCTYl.gif', '/media/posters/1415-YtaCTYl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Shoulder Press V. 2', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Engage your core and press the dumbbell straight up overhead, fully extending your arm.","Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0360', '/media/exercises/0360-1TkiAFK.gif', '/media/posters/0360-1TkiAFK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Snatch', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Lower the dumbbell towards the ground, keeping it close to your body.","Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.","As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.","Catch the dumbbell overhead with a slight bend in your knees and hips.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3888', '/media/exercises/3888-6pTkI99.gif', '/media/posters/3888-6pTkI99.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Standing Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.', '["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.","Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1670', '/media/exercises/1670-ffQsyBj.gif', '/media/posters/1670-ffQsyBj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Standing Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your torso.', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1671', '/media/exercises/1671-2sQGZ5b.gif', '/media/posters/1671-2sQGZ5b.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Triceps Extension (on Bench)', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand and place your other hand on the bench for support.","Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Extend your arm back up to the starting position, fully straightening your elbow.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0362', '/media/exercises/0362-nAuHPcD.gif', '/media/posters/0362-nAuHPcD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Arm Zottman Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.', '["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.","Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.","Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","At the top of the curl, rotate your wrist so that your palm faces up.","Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1672', '/media/exercises/1672-sxY5Biu.gif', '/media/posters/1672-sxY5Biu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell One Leg Fly On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with a dumbbell in each hand, palms facing each other.', '["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Place one foot on the ground and extend the other leg straight out in front of you.","Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1292', '/media/exercises/1292-pH2x2jj.gif', '/media/posters/1292-pH2x2jj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Over Bench Neutral Wrist Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0365', '/media/exercises/0365-BKa8dmT.gif', '/media/posters/0365-BKa8dmT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Over Bench One Arm Neutral Wrist Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.', '["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0366', '/media/exercises/0366-IvV6C9M.gif', '/media/posters/0366-IvV6C9M.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Over Bench One Arm Reverse Wrist Curl', 'FOREARMS', 'BICEPS,BRACHIALIS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1441', '/media/exercises/1441-4Jc36XM.gif', '/media/posters/1441-4Jc36XM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Over Bench One Arm Wrist Curl', 'FOREARMS', 'BICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0367', '/media/exercises/0367-KI1DjNN.gif', '/media/posters/0367-KI1DjNN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Over Bench Revers Wrist Curl', 'FOREARMS', 'BICEPS,BRACHIALIS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0368', '/media/exercises/0368-3tAXPQ6.gif', '/media/posters/0368-3tAXPQ6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Over Bench Wrist Curl', 'FOREARMS', 'BICEPS,BRACHIALIS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.', '["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Allow your wrists to hang over the edge of the bench.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0369', '/media/exercises/0369-D1xYJAU.gif', '/media/posters/0369-D1xYJAU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Palm Rotational Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend forward at the hips, keeping your back straight and your knees slightly bent.","Let your arms hang straight down, palms facing your body.","Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.","As you pull the dumbbells up, rotate your palms so they face away from your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1329', '/media/exercises/1329-wt6rwjk.gif', '/media/posters/1329-wt6rwjk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Peacher Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your torso.', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0370', '/media/exercises/0370-F1KxjBa.gif', '/media/posters/0370-F1KxjBa.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Plyo Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explode upward, jumping off the ground.","While in the air, quickly switch the position of your feet, landing with your opposite foot forward.","Immediately lower your body back into a squat position and repeat the jump, switching your feet again.","Continue alternating the position of your feet with each jump for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0371', '/media/exercises/0371-S4pwGlc.gif', '/media/posters/0371-S4pwGlc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Preacher Curl Over Exercise Ball', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1673', '/media/exercises/1673-hwygydB.gif', '/media/posters/1673-hwygydB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Press On Exercise Ball', 'CHEST', 'SHOULDERS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.', '["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1293', '/media/exercises/1293-O8o7q4d.gif', '/media/posters/1293-O8o7q4d.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Pronate-grip Triceps Extension', 'TRICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your back straight and feet flat on the ground.', '["Sit on a bench or chair with your back straight and feet flat on the ground.","Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0373', '/media/exercises/0373-bpJL2Qs.gif', '/media/posters/0373-bpJL2Qs.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Prone Incline Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Adjust the bench to a 45-degree incline.', '["Adjust the bench to a 45-degree incline.","Lie face down on the bench with a dumbbell in each hand, palms facing each other.","Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1674', '/media/exercises/1674-cWemPG8.gif', '/media/posters/1674-cWemPG8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0375-9XjtHvS.gif', poster_url = '/media/posters/0375-9XjtHvS.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0375', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Pullover') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Pullover Hip Extension On Exercise Ball', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.', '["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Pause for a moment, then raise the dumbbell back to the starting position.","While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1294', '/media/exercises/1294-lI7easp.gif', '/media/posters/1294-lI7easp.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Pullover On Exercise Ball', 'CHEST', 'TRICEPS,LATISSIMUS DORSI', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.', '["Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1295', '/media/exercises/1295-FSD6PGL.gif', '/media/posters/1295-FSD6PGL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Push Press', 'SHOULDERS', 'TRICEPS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.","Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1700', '/media/exercises/1700-FS63wTN.gif', '/media/posters/1700-FS63wTN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Rear Delt Raise', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2292', '/media/exercises/2292-mu5Guxt.gif', '/media/posters/2292-mu5Guxt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Rear Delt Row_shoulder', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with your palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight down towards the floor, with a slight bend in your elbows.","Raise the dumbbells out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0377', '/media/exercises/0377-EKXOMEh.gif', '/media/posters/0377-EKXOMEh.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Rear Fly', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down towards the ground, palms facing each other.","Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0378', '/media/exercises/0378-8DiFDVA.gif', '/media/posters/0378-8DiFDVA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Rear Lateral Raise (support Head)', 'SHOULDERS', 'TRAPS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0379', '/media/exercises/0379-UzkLrem.gif', '/media/posters/0379-UzkLrem.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0381-SSsBDwB.gif', poster_url = '/media/posters/0381-SSsBDwB.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0381', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Rear Lunge') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Revers Grip Biceps Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.', '["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0382', '/media/exercises/0382-e4ojVhP.gif', '/media/posters/0382-e4ojVhP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Reverse Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your knees bent.', '["Lie flat on a bench with your feet flat on the ground and your knees bent.","Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.","Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.","Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1624', '/media/exercises/1624-UIbGx6H.gif', '/media/posters/1624-UIbGx6H.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Reverse Fly', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down in front of you, palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0383', '/media/exercises/0383-EAs3xL9.gif', '/media/posters/0383-EAs3xL9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Reverse Grip Incline Bench One Arm Row', 'BACK', 'BICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Place a dumbbell on the floor next to the bench.","Stand facing the bench with your feet shoulder-width apart.","Bend at the waist and place your left knee and left hand on the bench for support.","Pick up the dumbbell with your right hand using a reverse grip (palm facing down).","Keep your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your back muscles at the top of the movement.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your left arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1330', '/media/exercises/1330-ZIViNh1.gif', '/media/posters/1330-ZIViNh1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Reverse Grip Incline Bench Two Arm Row', 'BACK', 'BICEPS,FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and your feet flat on the ground.","Hold a dumbbell in each hand with an underhand grip.","Lean forward and let your arms hang straight down, fully extended.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1331', '/media/exercises/1331-9pQSkH8.gif', '/media/posters/1331-9pQSkH8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Reverse Grip Row (female)', 'BACK', 'BICEPS,FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with an overhand grip, palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2327', '/media/exercises/2327-Nh3mvOO.gif', '/media/posters/2327-Nh3mvOO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Reverse Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.', '["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Hold a dumbbell in each hand with an underhand grip, palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.","Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0384', '/media/exercises/0384-O8Aq69u.gif', '/media/posters/0384-O8Aq69u.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Reverse Spider Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.', '["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1675', '/media/exercises/1675-6sMAmNv.gif', '/media/posters/1675-6sMAmNv.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Reverse Wrist Curl', 'FOREARMS', 'BICEPS,BRACHIALIS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the ground.', '["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0385', '/media/exercises/0385-BLCvwr2.gif', '/media/posters/0385-BLCvwr2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Romanian Deadlift', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.","Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1459', '/media/exercises/1459-rR0LJzx.gif', '/media/posters/1459-rR0LJzx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Rotation Reverse Fly', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Rotate your arms so that your palms are facing downwards.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0386', '/media/exercises/0386-prbWx1D.gif', '/media/posters/0386-prbWx1D.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Scott Press', 'SHOULDERS', 'TRICEPS,CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in each hand, palms facing forward.', '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2397', '/media/exercises/2397-5vfAI0I.gif', '/media/posters/2397-5vfAI0I.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Alternate Front Raise', 'SHOULDERS', 'TRAPEZIUS,BICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0387', '/media/exercises/0387-gH5fRsC.gif', '/media/posters/0387-gH5fRsC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Alternate Hammer Curl On Exercise Ball', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1676', '/media/exercises/1676-QLRmNeT.gif', '/media/posters/1676-QLRmNeT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Alternate Press', 'SHOULDERS', 'TRICEPS,CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in each hand, palms facing forward.', '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press one dumbbell up overhead, fully extending your arm.","Lower the dumbbell back down to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0388', '/media/exercises/0388-QT5Q0nK.gif', '/media/posters/0388-QT5Q0nK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Alternate Shoulder', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.","Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.","Continue alternating between arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3546', '/media/exercises/3546-q7qkONO.gif', '/media/posters/3546-q7qkONO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Bench Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up above your head.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0389', '/media/exercises/0389-JhYSVwT.gif', '/media/posters/0389-JhYSVwT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Bent Arm Lateral Raise', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2317', '/media/exercises/2317-JzQbv7J.gif', '/media/posters/2317-JzQbv7J.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Bent Over Alternate Kickback', 'TRICEPS', 'SHOULDERS,BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in each hand, palms facing inwards.', '["Sit on a bench with a dumbbell in each hand, palms facing inwards.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend one arm straight back, keeping it close to your body, until your arm is fully extended.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1730', '/media/exercises/1730-x0lwvfq.gif', '/media/posters/1730-x0lwvfq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Bent Over Triceps Extension', 'TRICEPS', 'SHOULDERS,BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your head up.","Extend your arms straight back, keeping your elbows close to your head.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1737', '/media/exercises/1737-4ievMJ9.gif', '/media/posters/1737-4ievMJ9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Bicep Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1677', '/media/exercises/1677-xiA6lRr.gif', '/media/posters/1677-xiA6lRr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Biceps Curl (on Stability Ball)', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your back straight.', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0390', '/media/exercises/0390-WgJnBH5.gif', '/media/posters/0390-WgJnBH5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Biceps Curl To Shoulder Press', 'BICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing forward and arms fully extended.","Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.","Once your forearms are vertical, rotate your wrists so that your palms are facing forward.","Press the dumbbells overhead until your arms are fully extended.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3547', '/media/exercises/3547-OeL23VY.gif', '/media/posters/3547-OeL23VY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Calf Raise', 'CALVES', 'HAMSTRINGS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Hold onto the dumbbell for stability.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1379', '/media/exercises/1379-r29jP7S.gif', '/media/posters/1379-r29jP7S.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0391', '/media/exercises/0391-TiaZTxx.gif', '/media/posters/0391-TiaZTxx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Front Raise', 'SHOULDERS', 'TRAPEZIUS,BICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0392', '/media/exercises/0392-Ys97II0.gif', '/media/posters/0392-Ys97II0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Hammer Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.', '["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1678', '/media/exercises/1678-IGtBdNT.gif', '/media/posters/1678-IGtBdNT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Inner Biceps Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your upper arms on your thighs, allowing the dumbbells to hang down.","Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0393', '/media/exercises/0393-KXyoEtA.gif', '/media/posters/0393-KXyoEtA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Kickback', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend your knees slightly and lean forward from your hips, keeping your back straight.","Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0394', '/media/exercises/0394-en550rk.gif', '/media/posters/0394-en550rk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Lateral Raise', 'SHOULDERS', 'TRAPS,UPPER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0396', '/media/exercises/0396-hxyTtWj.gif', '/media/posters/0396-hxyTtWj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Lateral Raise V. 2', 'SHOULDERS', 'TRAPS,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0395', '/media/exercises/0395-hrrS0Ed.gif', '/media/posters/0395-hrrS0Ed.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Neutral Wrist Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.","Rest your forearms on your thighs, allowing the dumbbells to hang down.","Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0397', '/media/exercises/0397-uJmK7Z1.gif', '/media/posters/0397-uJmK7Z1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated One Arm Bicep Curl On Exercise Ball With Leg Raised', 'BICEPS', 'FOREARMS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your back straight.', '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Place your other hand on your hip for stability.","Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1679', '/media/exercises/1679-84sESNy.gif', '/media/posters/1679-84sESNy.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated One Arm Kickback', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.","Bend your torso forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0398', '/media/exercises/0398-VQ3sNCn.gif', '/media/posters/0398-VQ3sNCn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated One Arm Rotate', 'FOREARMS', 'SHOULDERS,BICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.', '["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Rotate your forearm outward, away from your body, while keeping your upper arm stationary.","Pause for a moment at the top, then slowly rotate your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0399', '/media/exercises/0399-7f2jsqP.gif', '/media/posters/0399-7f2jsqP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated One Leg Calf Raise - Hammer Grip', 'CALVES', 'HAMSTRINGS,GLUTES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1380', '/media/exercises/1380-FxhcxUW.gif', '/media/posters/1380-FxhcxUW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated One Leg Calf Raise - Palm Up', 'CALVES', 'HAMSTRINGS,GLUTES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench or chair with your back straight and your feet flat on the ground.', '["Sit on a bench or chair with your back straight and your feet flat on the ground.","Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.","Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.","Raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1381', '/media/exercises/1381-VW88JNd.gif', '/media/posters/1381-VW88JNd.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Palms Up Wrist Curl', 'FOREARMS', 'BICEPS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0401', '/media/exercises/0401-2dImyQ8.gif', '/media/posters/0401-2dImyQ8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher curl bench with your feet flat on the floor.', '["Sit on a preacher curl bench with your feet flat on the floor.","Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0402', '/media/exercises/0402-7D5bgLT.gif', '/media/posters/0402-7D5bgLT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Revers Grip Concentration Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0403', '/media/exercises/0403-lyKCLmK.gif', '/media/posters/0403-lyKCLmK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Reverse Grip One Arm Overhead Tricep Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with an underhand grip and extend your arm straight up overhead.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Pause for a moment, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1738', '/media/exercises/1738-5fKX7wi.gif', '/media/posters/1738-5fKX7wi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Shoulder Press (parallel Grip)', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in each hand, palms facing inward.', '["Sit on a bench with a dumbbell in each hand, palms facing inward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0404', '/media/exercises/0404-f1jf47L.gif', '/media/posters/0404-f1jf47L.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Seated Triceps Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up overhead.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Pause for a moment, then straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2188', '/media/exercises/2188-kont8Ut.gif', '/media/posters/2188-kont8Ut.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Side Lying One Hand Raise', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs extended and your head supported by your arm.', '["Lie on your side with your legs extended and your head supported by your arm.","Hold a dumbbell in your top hand with your palm facing down.","Keeping your arm straight, raise the dumbbell up to shoulder height.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0408', '/media/exercises/0408-fTlkJop.gif', '/media/posters/0408-fTlkJop.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Side Plank With Rear Fly', 'BACK', 'SHOULDERS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by lying on your side with your legs extended and stacked on top of each other.', '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.","Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.","While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3664', '/media/exercises/3664-X6ytgYZ.gif', '/media/posters/3664-X6ytgYZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Single Arm Overhead Carry', 'SHOULDERS', 'TRAPS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.', '["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.","Continue walking for the desired distance or time.","Switch hands and repeat the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3548', '/media/exercises/3548-mWBtgmb.gif', '/media/posters/3548-mWBtgmb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Single Leg Deadlift', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart, holding a dumbbell in your right hand.', '["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Shift your weight onto your left leg and lift your right foot slightly off the ground.","Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.","At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.","Lower the dumbbell until your torso and right leg are parallel to the ground.","Pause for a moment, then engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1757', '/media/exercises/1757-gKozT8X.gif', '/media/posters/1757-gKozT8X.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Single Leg Deadlift With Stepbox Support', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart, holding a dumbbell in your right hand.', '["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Place your left foot on a stepbox or elevated surface behind you.","Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.","As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.","Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2805', '/media/exercises/2805-daBmy1Y.gif', '/media/posters/2805-daBmy1Y.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Single Leg Split Squat', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.","Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0410', '/media/exercises/0410-qx4fgX7.gif', '/media/posters/0410-qx4fgX7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Single Leg Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Extend one leg forward and keep it off the ground throughout the exercise.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Pause for a moment at the bottom, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0411', '/media/exercises/0411-H6ybluc.gif', '/media/posters/0411-H6ybluc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0413-HsvHqgf.gif', poster_url = '/media/posters/0413-HsvHqgf.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0413', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Squat') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Alternate Hammer Curl And Press', 'BICEPS', 'FOREARMS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your body.', '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your back straight.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with your left hand.","After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.","Extend your arm fully and hold for a moment at the top.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the press with your left hand.","Continue alternating between curls and presses for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3560', '/media/exercises/3560-LeaZOIz.gif', '/media/posters/3560-LeaZOIz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Alternate Overhead Press', 'SHOULDERS', 'TRICEPS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press one dumbbell overhead, fully extending your arm.","Lower the dumbbell back to shoulder level.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0414', '/media/exercises/0414-bBi35y3.gif', '/media/posters/0414-bBi35y3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Alternate Raise', 'SHOULDERS', 'TRAPS,FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and your core engaged.","Raise one dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0415', '/media/exercises/0415-SxHteRW.gif', '/media/posters/0415-SxHteRW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Alternating Tricep Kickback', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, keeping your elbows close to your body.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat with the other arm, alternating sides with each repetition."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1739', '/media/exercises/1739-Gi2BXfK.gif', '/media/posters/1739-Gi2BXfK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Around World', 'SHOULDERS', 'TRICEPS,FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Extend your arms straight out to the sides at shoulder height, palms facing down.","Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.","Continue the circular motion, bringing the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2143', '/media/exercises/2143-RSOsp5d.gif', '/media/posters/2143-RSOsp5d.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Bent Over One Arm Triceps Extension', 'TRICEPS', 'SHOULDERS,BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1740', '/media/exercises/1740-CJwa0vD.gif', '/media/posters/1740-CJwa0vD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Bent Over Two Arm Triceps Extension', 'TRICEPS', 'SHOULDERS,BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Extend your arms straight back, keeping your elbows close to your body.","Slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1741', '/media/exercises/1741-3T12T87.gif', '/media/posters/1741-3T12T87.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Biceps Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0416', '/media/exercises/0416-3s4NnTh.gif', '/media/posters/0416-3s4NnTh.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Front Raise Above Head', 'SHOULDERS', 'TRAPEZIUS,BICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keep your arms straight and lift the dumbbells in front of you, raising them above your head.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0419', '/media/exercises/0419-laVRfDf.gif', '/media/posters/0419-laVRfDf.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Inner Biceps Curl V. 2', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your torso.', '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","While holding your upper arms stationary, curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2321', '/media/exercises/2321-vKilzz3.gif', '/media/posters/2321-vKilzz3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Kickback', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0420', '/media/exercises/0420-UmpPAAe.gif', '/media/posters/0420-UmpPAAe.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing One Arm Concentration Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.","Place your free hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0421', '/media/exercises/0421-8fgqP5a.gif', '/media/posters/0421-8fgqP5a.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing One Arm Curl (over Incline Bench)', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0422', '/media/exercises/0422-BIb1tGo.gif', '/media/posters/0422-BIb1tGo.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing One Arm Curl Over Incline Bench', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand.', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1680', '/media/exercises/1680-EmlJR2y.gif', '/media/posters/1680-EmlJR2y.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing One Arm Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand.', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Keep your upper arm close to your head and perpendicular to the ground.","Slowly lower the dumbbell behind your head, bending your elbow.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0423', '/media/exercises/0423-BCUR88E.gif', '/media/posters/0423-BCUR88E.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing One Arm Palm In Press', 'SHOULDERS', 'TRICEPS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Engage your core and keep your back straight.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0424', '/media/exercises/0424-ocYc6Db.gif', '/media/posters/0424-ocYc6Db.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing One Arm Reverse Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.","Keep your arm fully extended and close to your body, with your palm facing down.","Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0425', '/media/exercises/0425-DU5Kkj2.gif', '/media/posters/0425-DU5Kkj2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Overhead Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0426', '/media/exercises/0426-A6wtbuL.gif', '/media/posters/0426-A6wtbuL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Palms In Press', 'SHOULDERS', 'TRICEPS,CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0427', '/media/exercises/0427-UilDHSs.gif', '/media/posters/0427-UilDHSs.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', '["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0428', '/media/exercises/0428-hq2hyDH.gif', '/media/posters/0428-hq2hyDH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Reverse Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0429', '/media/exercises/0429-0IgNjSM.gif', '/media/posters/0429-0IgNjSM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Triceps Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Raise the dumbbell overhead, keeping your arm straight.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Extend your arm back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0430', '/media/exercises/0430-PdmaD0N.gif', '/media/posters/0430-PdmaD0N.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Standing Zottman Preacher Curl', 'BICEPS', 'FOREARMS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing forward.', '["Stand up straight with a dumbbell in each hand, palms facing forward.","Place your upper arms against the preacher bench and keep your elbows slightly bent.","Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing downward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2293', '/media/exercises/2293-P2nRiUa.gif', '/media/posters/2293-P2nRiUa.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Step Up Single Leg Balance With Bicep Curl', 'BICEPS', 'QUADRICEPS,GLUTES,HAMSTRINGS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.', '["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1684', '/media/exercises/1684-76vfTdU.gif', '/media/posters/1684-76vfTdU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Step-up', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.', '["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your right heel and lift your body up onto the bench or step, straightening your right leg.","Bring your left foot up onto the bench or step, standing fully upright.","Step back down with your left foot, followed by your right foot, returning to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0431', '/media/exercises/0431-aXtJhlg.gif', '/media/posters/0431-aXtJhlg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Step-up Lunge', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.', '["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Place your right foot on the step, ensuring your entire foot is on the surface.","Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Repeat the movement, alternating which foot you step up with each time.","Continue for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2796', '/media/exercises/2796-gFyFj9z.gif', '/media/posters/2796-gFyFj9z.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Step-up Split Squat', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.', '["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.","As you step up, simultaneously lift your left knee towards your chest.","Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.","Repeat the movement with your left foot on the bench or step.","Continue alternating between your right and left foot for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2812', '/media/exercises/2812-QjE2DcA.gif', '/media/posters/2812-QjE2DcA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Straight Arm Pullover', 'CHEST', 'LATISSIMUS DORSI,TRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your head at one end and your feet planted firmly on the ground.', '["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0433', '/media/exercises/0433-i8BdLTK.gif', '/media/posters/0433-i8BdLTK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Straight Leg Deadlift', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.","Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0434', '/media/exercises/0434-oom75KC.gif', '/media/posters/0434-oom75KC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Sumo Pull Through', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet wider than shoulder-width apart, toes pointed outwards.', '["Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Hold a dumbbell with both hands in front of your body, arms extended.","Bend your knees and lower your hips down into a squat position, keeping your back straight.","Lower the dumbbell down between your legs, keeping your arms straight.","Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2808', '/media/exercises/2808-BmrwWzo.gif', '/media/posters/2808-BmrwWzo.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Supported Squat', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2803', '/media/exercises/2803-r5DgrW9.gif', '/media/posters/2803-r5DgrW9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Tricep Kickback With Stork Stance', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1742', '/media/exercises/1742-wOLmCXc.gif', '/media/posters/1742-wOLmCXc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Twisting Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with an overhand grip, palms facing away from you.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbells down towards your chest, keeping your elbows close to your body.","As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.","Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.","As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1743', '/media/exercises/1743-z6TAHoT.gif', '/media/posters/1743-z6TAHoT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0437-ainizkb.gif', poster_url = '/media/posters/0437-ainizkb.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0437', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Dumbbell Upright Row') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Upright Row (back Pov)', 'SHOULDERS', 'TRAPS,BICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1765', '/media/exercises/1765-Iptlv6x.gif', '/media/posters/1765-Iptlv6x.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Upright Shoulder External Rotation', 'SHOULDERS', 'ROTATOR CUFF,TRAPEZIUS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.","Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0864', '/media/exercises/0864-x306lCW.gif', '/media/posters/0864-x306lCW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell Waiter Biceps Curl', 'BICEPS', 'FOREARMS,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing forward.', '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms close to your body and your elbows tucked in.","Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_5201', '/media/exercises/5201-KOpzGBL.gif', '/media/posters/5201-KOpzGBL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbell W-press', 'SHOULDERS', 'TRICEPS,CHEST', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with a dumbbell in each hand, palms facing forward.', '["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0438', '/media/exercises/0438-vmwLyCg.gif', '/media/posters/0438-vmwLyCg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dumbbells Seated Triceps Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in both hands with an overhand grip, and raise it above your head.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Extend your arms and raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2189', '/media/exercises/2189-FQXdXzY.gif', '/media/posters/2189-FQXdXzY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Dynamic Chest Stretch (male)', 'CHEST', 'SHOULDERS,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand tall with your feet shoulder-width apart.', '["Stand tall with your feet shoulder-width apart.","Extend your arms straight out to the sides, parallel to the ground.","Slowly bring your arms forward, crossing them in front of your body.","Feel the stretch in your chest muscles.","Hold the stretch for 10-30 seconds.","Return to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1167', '/media/exercises/1167-3uj0Ozg.gif', '/media/posters/1167-3uj0Ozg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Elbow Dips', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.', '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3287', '/media/exercises/3287-LkoAWAE.gif', '/media/posters/3287-LkoAWAE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Elbow Lift - Reverse Push-up', 'BACK', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.', '["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Pause at the top for a moment, squeezing your upper back muscles.","Slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1772', '/media/exercises/1772-wbUYILZ.gif', '/media/posters/1772-wbUYILZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Elevator', 'BACK', 'SHOULDERS,TRAPEZIUS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or cross them in front of your chest.","Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3292', '/media/exercises/3292-zYmNaoY.gif', '/media/posters/3292-zYmNaoY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Alternating Arm Ups', 'BACK', 'SHOULDERS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your back straight.', '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat the movement with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1332', '/media/exercises/1332-EyLrNC2.gif', '/media/posters/1332-EyLrNC2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Back Extension With Arms Extended', 'BACK', 'GLUTES,HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Extend your arms straight out in front of you, with your palms facing down.","Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1333', '/media/exercises/1333-PERjVm8.gif', '/media/posters/1333-PERjVm8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Back Extension With Hands Behind Head', 'BACK', 'GLUTES,HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.', '["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.","Position your feet against a wall or other stable surface for support.","Cross your arms behind your head, with your hands touching the back of your head.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1334', '/media/exercises/1334-o1HGDSq.gif', '/media/posters/1334-o1HGDSq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Back Extension With Knees Off Ground', 'BACK', 'GLUTES,HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.', '["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1335', '/media/exercises/1335-WME869U.gif', '/media/posters/1335-WME869U.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Back Extension With Rotation', 'BACK', 'GLUTES,HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.', '["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.","Return to the center and repeat the rotation to the other side.","Lower your upper body back down to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1336', '/media/exercises/1336-WVD66ff.gif', '/media/posters/1336-WVD66ff.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Dip', 'TRICEPS', 'CHEST,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the ball beside your hips, fingers pointing forward.","Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.","Lower your body back down by bending your elbows, keeping them close to your sides.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1744', '/media/exercises/1744-kprile3.gif', '/media/posters/1744-kprile3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Hip Flexor Stretch', 'GLUTES', 'QUADRICEPS,HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the stability ball on the ground and kneel in front of it.', '["Place the stability ball on the ground and kneel in front of it.","Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Extend your left leg behind you, keeping it straight.","Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1559', '/media/exercises/1559-2LQkNPW.gif', '/media/posters/1559-2LQkNPW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Hug', 'BACK', 'SHOULDERS,CHEST', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your back straight.', '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the stability ball with both hands, hugging it close to your chest.","Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.","Continue leaning back until you feel a stretch in your back muscles.","Hold the position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1338', '/media/exercises/1338-d7z1Y7V.gif', '/media/posters/1338-d7z1Y7V.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Lat Stretch', 'BACK', 'SHOULDERS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your back straight.', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up overhead.","Slowly lean to the opposite side, feeling a stretch in your lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1339', '/media/exercises/1339-sM84pE4.gif', '/media/posters/1339-sM84pE4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Lower Back Stretch (pyramid)', 'BACK', 'GLUTES,HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1341', '/media/exercises/1341-yU7w7CA.gif', '/media/posters/1341-yU7w7CA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Lying Side Lat Stretch', 'BACK', 'SHOULDERS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs extended and your head supported by the stability ball.', '["Lie on your side with your legs extended and your head supported by the stability ball.","Place your top arm on the ball for stability.","Reach your top arm overhead and allow your torso to rotate slightly.","Feel the stretch in your lat muscles on the side of your body.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1342', '/media/exercises/1342-rTbyBYV.gif', '/media/posters/1342-rTbyBYV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball On The Wall Calf Raise', 'CALVES', 'HAMSTRINGS,QUADRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your back against a wall and place an exercise ball between your lower back and the wall.', '["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart, with your toes pointing forward.","Hold a dumbbell in each hand, with your arms extended by your sides.","Raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1382', '/media/exercises/1382-xo6sENf.gif', '/media/posters/1382-xo6sENf.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball On The Wall Calf Raise (tennis Ball Between Ankles)', 'CALVES', 'HAMSTRINGS,QUADRICEPS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a wall with your feet shoulder-width apart.', '["Stand facing a wall with your feet shoulder-width apart.","Place an exercise ball between the wall and your lower back.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your ankles.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3241', '/media/exercises/3241-FY3UdNT.gif', '/media/posters/3241-FY3UdNT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball On The Wall Calf Raise (tennis Ball Between Knees)', 'CALVES', 'QUADRICEPS,HAMSTRINGS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your back against a wall and place an exercise ball between your lower back and the wall.', '["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart and slightly in front of you.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your knees.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3240', '/media/exercises/3240-j74M6Zn.gif', '/media/posters/3240-j74M6Zn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball One Leg Prone Lower Body Rotation', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.', '["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for support.","Engage your glutes and core muscles to stabilize your body.","Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Repeat the rotation with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1416', '/media/exercises/1416-M72BExt.gif', '/media/posters/1416-M72BExt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball One Legged Diagonal Kick Hamstring Curl', 'GLUTES', 'HAMSTRINGS,CALVES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by lying on your back with your legs extended and your heels resting on top of the stability ball.', '["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.","Place your arms by your sides for stability.","Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.","Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.","Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.","Slowly return your right leg to the starting position, maintaining control and stability.","Repeat the movement with your left leg, alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1417', '/media/exercises/1417-GOJKFfO.gif', '/media/posters/1417-GOJKFfO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Pike Push Up', 'CHEST', 'SHOULDERS,TRICEPS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands on the floor and your shins resting on the stability ball.', '["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.","Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.","Keep your legs straight and your body in a pike position, forming an inverted V shape.","Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1296', '/media/exercises/1296-sVvXT5J.gif', '/media/posters/1296-sVvXT5J.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Prone Leg Raise', 'BACK', 'ABDOMINALS,GLUTES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.', '["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.","Place your hands on the ground, shoulder-width apart, and engage your core muscles.","Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1343', '/media/exercises/1343-lCKm4Rs.gif', '/media/posters/1343-lCKm4Rs.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Seated Hamstring Stretch', 'HAMSTRINGS', 'GLUTES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Place your hands on your hips for support.","Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.","Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.","Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1560', '/media/exercises/1560-yRYyfdA.gif', '/media/posters/1560-yRYyfdA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Seated Triceps Stretch', 'TRICEPS', 'SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your back straight.', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up above your head.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.","Hold the stretch for a few seconds, then return to the starting position.","Repeat with the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1745', '/media/exercises/1745-7ePTw4B.gif', '/media/posters/1745-7ePTw4B.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Exercise Ball Supine Triceps Extension', 'TRICEPS', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1746', '/media/exercises/1746-Gm2Uv1z.gif', '/media/posters/1746-Gm2Uv1z.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Bar French Press On Exercise Ball', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on an exercise ball and hold an EZ barbell with an overhand grip.', '["Sit on an exercise ball and hold an EZ barbell with an overhand grip.","Extend your arms straight up, keeping your elbows close to your head.","Slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1747', '/media/exercises/1747-CFN9P8G.gif', '/media/posters/1747-CFN9P8G.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Bar Lying Bent Arms Pullover', 'BACK', 'TRICEPS,CHEST', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your head at one end and your feet on the floor.', '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.","Extend your arms straight above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.","Pause for a moment, then return the barbell to the starting position by reversing the arc motion.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3010', '/media/exercises/3010-nDK1HJ0.gif', '/media/posters/3010-nDK1HJ0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Bar Lying Close Grip Triceps Extension Behind Head', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1748', '/media/exercises/1748-6CKUx7o.gif', '/media/posters/1748-6CKUx7o.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Bar Reverse Grip Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1344', '/media/exercises/1344-G8dXpNG.gif', '/media/posters/1344-G8dXpNG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Bar Seated Close Grip Concentration Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.', '["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.","Rest your elbow on the inside of your thigh, just above the knee.","Curl the barbell up towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1682', '/media/exercises/1682-Dsfz0Id.gif', '/media/posters/1682-Dsfz0Id.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Bar Standing French Press', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.', '["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1749', '/media/exercises/1749-1cTf2Ux.gif', '/media/posters/1749-1cTf2Ux.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Close Grip Preacher Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.', '["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Slowly curl the barbell towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1627', '/media/exercises/1627-hacCyUv.gif', '/media/posters/1627-hacCyUv.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Close-grip Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0446', '/media/exercises/0446-V4ryaZa.gif', '/media/posters/0446-V4ryaZa.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Decline Close Grip Face Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your head lower than your feet.', '["Lie on a decline bench with your head lower than your feet.","Grasp the ez barbell with a close grip, palms facing each other.","Extend your arms straight up above your chest, keeping your elbows close to your body.","Lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0448', '/media/exercises/0448-DgZQ11d.gif', '/media/posters/0448-DgZQ11d.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Decline Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie on a decline bench with your head lower than your feet and your feet secured.', '["Lie on a decline bench with your head lower than your feet and your feet secured.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your head.","Lower the barbell slowly towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2186', '/media/exercises/2186-CQHoDm0.gif', '/media/posters/2186-CQHoDm0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Incline Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0449', '/media/exercises/0449-KyLtiLT.gif', '/media/posters/0449-KyLtiLT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Jm Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0450', '/media/exercises/0450-hnOYgH3.gif', '/media/posters/0450-hnOYgH3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Reverse Grip Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.","Keep your elbows close to your torso and your upper arms stationary throughout the exercise.","Curl the barbell upwards by contracting your biceps, while exhaling.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the barbell back to the starting position as you inhale.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0451', '/media/exercises/0451-Y5X65IB.gif', '/media/posters/0451-Y5X65IB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Reverse Grip Preacher Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a preacher bench with your chest against the pad and your feet flat on the floor.', '["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.","Grasp the ez barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms on the pad, allowing your forearms to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0452', '/media/exercises/0452-vBNyir7.gif', '/media/posters/0452-vBNyir7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Seated Curls', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your feet flat on the ground and your back straight.', '["Sit on a bench with your feet flat on the ground and your back straight.","Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.","Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1458', '/media/exercises/1458-jtFKbt5.gif', '/media/posters/1458-jtFKbt5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Seated Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0453', '/media/exercises/0453-iaapw0g.gif', '/media/posters/0453-iaapw0g.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez Barbell Spider Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.', '["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1628', '/media/exercises/1628-2kattbR.gif', '/media/posters/1628-2kattbR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez-bar Biceps Curl (with Arm Blaster)', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2404', '/media/exercises/2404-tJ5nYqo.gif', '/media/posters/2404-tJ5nYqo.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez-bar Close-grip Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2432', '/media/exercises/2432-da4cXST.gif', '/media/posters/2432-da4cXST.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ez-barbell Standing Wide Grip Biceps Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2741', '/media/exercises/2741-OVTZ65k.gif', '/media/posters/2741-OVTZ65k.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Farmers Walk', 'QUADS', 'CALVES,FOREARMS,CORE', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with a dumbbell in each hand, palms facing your sides.', '["Stand up straight with a dumbbell in each hand, palms facing your sides.","Keep your back straight and your shoulders back.","Take small, controlled steps forward, maintaining an upright posture.","Continue walking for the desired distance or time.","To finish, stop walking and carefully lower the dumbbells to your sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2133', '/media/exercises/2133-qPEzJjA.gif', '/media/posters/2133-qPEzJjA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Flag', 'ABS', 'OBLIQUES,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.', '["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Engage your core and lift your legs off the ground, keeping them straight.","Using your core and upper body strength, raise your legs until they are parallel to the ground.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3303', '/media/exercises/3303-pQ0Mx1Z.gif', '/media/posters/3303-pQ0Mx1Z.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Flexion Leg Sit Up (bent Knee)', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0456', '/media/exercises/0456-AR0ig3o.gif', '/media/posters/0456-AR0ig3o.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Flexion Leg Sit Up (straight Arm)', 'ABS', 'HIP FLEXORS,QUADRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs extended and arms straight above your head.', '["Lie flat on your back with your legs extended and arms straight above your head.","Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Reach your hands towards your toes as you lift your upper body and legs.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0457', '/media/exercises/0457-KZn52RC.gif', '/media/posters/0457-KZn52RC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Floor Fly (with Barbell)', 'CHEST', 'DELTOIDS,TRICEPS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground.', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold a barbell with an overhand grip, arms extended straight up over your chest.","Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.","Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0458', '/media/exercises/0458-neonEDL.gif', '/media/posters/0458-neonEDL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Forward Jump', 'QUADS', 'CALVES,HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Swing your arms back for momentum.","Jump forward explosively, extending your hips, knees, and ankles.","Land softly on the balls of your feet and immediately go into the next jump.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1472', '/media/exercises/1472-uZKq7lo.gif', '/media/posters/1472-uZKq7lo.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Forward Lunge (male)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart and hands on your hips.', '["Stand with your feet hip-width apart and hands on your hips.","Take a big step forward with your right foot, lowering your body into a lunge position.","Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Push off with your right foot and return to the starting position.","Repeat with your left leg, alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3470', '/media/exercises/3470-kMzUs9Y.gif', '/media/posters/3470-kMzUs9Y.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/3194-bdWcbaU.gif', poster_url = '/media/posters/3194-bdWcbaU.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_3194', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Frankenstein Squat') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Frog Crunch', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2429', '/media/exercises/2429-FFRP97T.gif', '/media/posters/2429-FFRP97T.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Frog Planche', 'ABS', 'SHOULDERS,CHEST,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands shoulder-width apart and your feet together.', '["Start in a push-up position with your hands shoulder-width apart and your feet together.","Bend your elbows and lower your body towards the ground, keeping your back straight.","As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3301', '/media/exercises/3301-rQhGcin.gif', '/media/posters/3301-rQhGcin.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Front Lever', 'ABS', 'LATS,SHOULDERS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.', '["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Hold this position for as long as you can, aiming for a full front lever position.","To release, slowly lower your legs back down and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3296', '/media/exercises/3296-PkCN2lv.gif', '/media/posters/3296-PkCN2lv.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Front Lever Reps', 'BACK', 'CORE,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with an overhand grip, palms facing away from you.', '["Hang from a pull-up bar with an overhand grip, palms facing away from you.","Engage your core and pull your shoulder blades down and back.","Keeping your body straight, lift your legs up until they are parallel to the ground.","Hold this position for as long as you can, aiming for 10-20 seconds.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3295', '/media/exercises/3295-hbY9wqG.gif', '/media/posters/3295-hbY9wqG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Front Plank With Twist', 'ABS', 'OBLIQUES,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and glutes to maintain a stable position.","Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Keep your hips and legs stable as you twist.","Hold for a moment, then return to the starting position.","Repeat the twist on the left side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0464', '/media/exercises/0464-CosupLu.gif', '/media/posters/0464-CosupLu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Full Maltese', 'ABS', 'SHOULDERS,CHEST', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.', '["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Engage your core and hold this position for a few seconds.","Return to the starting position by pushing through your feet and standing back up.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3315', '/media/exercises/3315-YRaCa5Y.gif', '/media/posters/3315-YRaCa5Y.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Full Planche', 'ABS', 'SHOULDERS,CHEST,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.', '["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your feet back to the ground and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3299', '/media/exercises/3299-YZ4961r.gif', '/media/posters/3299-YZ4961r.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Full Planche Push-up', 'CHEST', 'SHOULDERS,TRICEPS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands placed slightly wider than shoulder-width apart.', '["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Continue to lower your body until your chest is just above the ground.","Push through your hands and extend your arms to lift your body back up to the starting position.","Maintain a straight line from your head to your heels throughout the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3327', '/media/exercises/3327-gw9PqGk.gif', '/media/posters/3327-gw9PqGk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Gironda Sternum Chin', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a high bar with your feet shoulder-width apart.', '["Stand facing a high bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0466', '/media/exercises/0466-IL0JUxR.gif', '/media/posters/0466-IL0JUxR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Glute Bridge March', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Lower your foot back to the ground and repeat the movement with the other leg.","Continue alternating legs in a marching motion while maintaining the bridge position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3561', '/media/exercises/3561-GibBPPg.gif', '/media/posters/3561-GibBPPg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Glute Bridge Two Legs On Bench (male)', 'GLUTES', 'HAMSTRINGS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a bench with your back against it and your feet flat on the ground.', '["Sit on the edge of a bench with your back against it and your feet flat on the ground.","Place your hands on the bench beside your hips for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3523', '/media/exercises/3523-aWedzZX.gif', '/media/posters/3523-aWedzZX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Gorilla Chin', 'ABS', 'FOREARMS,BICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your palms facing away from you.","Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0467', '/media/exercises/0467-bmwlYvD.gif', '/media/posters/0467-bmwlYvD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Groin Crunch', 'ABS', 'HIP FLEXORS,INNER THIGHS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0469', '/media/exercises/0469-mWppALS.gif', '/media/posters/0469-mWppALS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hack Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a comfortable weight.', '["Adjust the sled machine to a comfortable weight.","Stand on the sled machine with your toes on the platform and your heels hanging off.","Hold onto the handles for stability.","Raise your heels as high as possible by pushing through the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1383', '/media/exercises/1383-2ORFMoR.gif', '/media/posters/1383-2ORFMoR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hack One Leg Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to an appropriate weight.', '["Adjust the sled machine to an appropriate weight.","Stand on the sled machine with one foot, keeping the other foot off the ground.","Hold onto the handles for stability.","Raise your heel as high as possible, lifting your body up on the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions.","Switch legs and repeat the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1384', '/media/exercises/1384-AxFoqAD.gif', '/media/posters/1384-AxFoqAD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Half Knee Bends (male)', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body down as if you were sitting back into a chair.","Keep your chest up and your weight in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3221', '/media/exercises/3221-ia6kIIl.gif', '/media/posters/3221-ia6kIIl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Half Sit-up (male)', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3202', '/media/exercises/3202-iQ241UP.gif', '/media/posters/3202-iQ241UP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hands Bike', 'CHEST', 'TRICEPS,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and handlebar position to a comfortable level.', '["Adjust the seat height and handlebar position to a comfortable level.","Sit on the ergometer with your back straight and feet on the pedals.","Grasp the handles with your hands and position your arms at a 90-degree angle.","Start pedaling with your hands, pushing and pulling the handles in a controlled motion.","Continue pedaling for the desired duration or number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2139', '/media/exercises/2139-pAIWRGu.gif', '/media/posters/2139-pAIWRGu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hands Clasped Circular Toe Touch (male)', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.', '["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3218', '/media/exercises/3218-B5xca8s.gif', '/media/posters/3218-B5xca8s.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hands Reversed Clasped Circular Toe Touch (male)', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your arms extended to the sides.', '["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down with your hands and clasp them together behind your legs.","Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Continue the circular motion until your hands touch your toes.","Reverse the motion and bring your hands back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3215', '/media/exercises/3215-yq3GAJX.gif', '/media/posters/3215-yq3GAJX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Handstand', 'TRICEPS', 'SHOULDERS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Find an open space with enough room to perform a handstand.', '["Find an open space with enough room to perform a handstand.","Place your hands on the ground shoulder-width apart, fingers pointing forward.","Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Once in a handstand position, engage your triceps to support your body weight.","Hold the handstand for as long as you can maintain balance.","To come down, slowly lower your legs back to the ground.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3302', '/media/exercises/3302-XooAdhl.gif', '/media/posters/3302-XooAdhl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hanging Leg Hip Raise', 'ABS', 'HIP FLEXORS,LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1764', '/media/exercises/1764-VEcJRo2.gif', '/media/posters/1764-VEcJRo2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hanging Oblique Knee Raise', 'ABS', 'OBLIQUES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat on the other side, twisting your torso in the opposite direction.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1761', '/media/exercises/1761-BaE7O6U.gif', '/media/posters/1761-BaE7O6U.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hanging Straight Leg Hip Raise', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0474', '/media/exercises/0474-pj0X0tF.gif', '/media/posters/0474-pj0X0tF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hanging Straight Twisting Leg Hip Raise', 'ABS', 'OBLIQUES,HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your legs straight.', '["Hang from a pull-up bar with your arms fully extended and your legs straight.","Engage your core and lift your legs up towards your chest, keeping them straight.","Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Pause for a moment, then return to the starting position.","Repeat the movement, but this time twist your hips to the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0476', '/media/exercises/0476-Q6bvyen.gif', '/media/posters/0476-Q6bvyen.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('High Knee Against Wall', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a wall with your feet hip-width apart.', '["Stand facing a wall with your feet hip-width apart.","Place your hands on the wall for support.","Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Continue alternating legs in a running motion, bringing your knees up as high as possible.","Maintain a fast pace and keep your upper body stable throughout the exercise.","Repeat for the desired duration or number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3636', '/media/exercises/3636-ealLwvX.gif', '/media/posters/3636-ealLwvX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hip Raise (bent Knee)', 'ABS', 'GLUTES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0484', '/media/exercises/0484-196HJGw.gif', '/media/posters/0484-196HJGw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hug Keens To Chest', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart.', '["Start by standing with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position.","As you squat down, bring your knees up towards your chest and hug them with your arms.","Hold this position for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1418', '/media/exercises/1418-znP9SIh.gif', '/media/posters/1418-znP9SIh.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hyght Dumbbell Fly', 'CHEST', 'SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a bench with a dumbbell in each hand, palms facing each other.', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3234', '/media/exercises/3234-P9ZRyLT.gif', '/media/posters/3234-P9ZRyLT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Hyperextension (on Bench)', 'BACK', 'GLUTES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.', '["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Slowly lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0488', '/media/exercises/0488-zkgRrbK.gif', '/media/posters/0488-zkgRrbK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Impossible Dips', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.', '["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.","Bend your knees and cross your ankles.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3289', '/media/exercises/3289-05Cf2v8.gif', '/media/posters/3289-05Cf2v8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1471-ZgsNQ6d.gif', poster_url = '/media/posters/1471-ZgsNQ6d.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1471', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Inchworm') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Inchworm V. 2', 'ABS', 'SHOULDERS,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a standing position with your feet hip-width apart.', '["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Continue walking your hands forward, repeating the movement for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3698', '/media/exercises/3698-TV87DNB.gif', '/media/posters/3698-TV87DNB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Incline Close-grip Push-up', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.', '["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0490', '/media/exercises/0490-1YB40kg.gif', '/media/posters/0490-1YB40kg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Incline Leg Hip Raise (leg Straight)', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.', '["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Place your hands on the sides of the bench for support.","Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0491', '/media/exercises/0491-eVxAzgz.gif', '/media/posters/0491-eVxAzgz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Incline Push-up (on Box)', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.', '["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3785', '/media/exercises/3785-F7vjXqT.gif', '/media/posters/3785-F7vjXqT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Incline Reverse Grip Push-up', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.', '["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0494', '/media/exercises/0494-XaaRnRn.gif', '/media/posters/0494-XaaRnRn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Incline Scapula Push Up', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Place your hands on the bench slightly wider than shoulder-width apart.","Position your feet on the ground, hip-width apart.","Lower your chest towards the bench, keeping your elbows tucked in.","As you lower, retract your shoulder blades, squeezing your scapulae together.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3011', '/media/exercises/3011-GdMa1ET.gif', '/media/posters/3011-GdMa1ET.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Incline Twisting Sit-up', 'ABS', 'OBLIQUES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Set up an incline bench at a 45-degree angle.', '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward.","As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat the movement, this time twisting your torso to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0495', '/media/exercises/0495-9ZGZuOD.gif', '/media/posters/0495-9ZGZuOD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Inverse Leg Curl (bench Support)', 'HAMSTRINGS', 'GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a bench with your hips at the edge and your legs extended straight behind you.', '["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Hold onto the bench for support.","Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0496', '/media/exercises/0496-ms7tjSG.gif', '/media/posters/0496-ms7tjSG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Inverse Leg Curl (on Pull-up Cable Machine)', 'HAMSTRINGS', 'GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Adjust the cable machine so that the ankle straps are at the lowest setting.', '["Adjust the cable machine so that the ankle straps are at the lowest setting.","Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Hold onto the handles of the bench for stability.","Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2400', '/media/exercises/2400-0rHfvy9.gif', '/media/posters/2400-0rHfvy9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Inverted Row Bent Knees', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Set up a bar at waist height and lie underneath it.', '["Set up a bar at waist height and lie underneath it.","Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your body is straight.","Pull your chest up towards the bar by squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2300', '/media/exercises/2300-VPPtusI.gif', '/media/posters/2300-VPPtusI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Inverted Row On Bench', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Set up a bench at a height that allows your body to hang freely underneath it.', '["Set up a bench at a height that allows your body to hang freely underneath it.","Lie face up on the ground with your head towards the bench.","Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your arms are fully extended.","Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2298', '/media/exercises/2298-Mxa7Cr8.gif', '/media/posters/2298-Mxa7Cr8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Inverted Row V. 2', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Set up a bar at waist height on a Smith machine or use a suspension trainer.', '["Set up a bar at waist height on a Smith machine or use a suspension trainer.","Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Walk your feet forward, leaning back until your body is at a slight angle.","Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0497', '/media/exercises/0497-uX3sUBz.gif', '/media/posters/0497-uX3sUBz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Iron Cross Stretch', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your arms extended out to the sides.', '["Lie flat on your back with your arms extended out to the sides.","Raise your legs up towards the ceiling, keeping them straight.","Slowly lower your legs to one side, aiming to touch the floor with your feet.","Hold the stretch for a few seconds, then return your legs to the starting position.","Repeat the stretch on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1419', '/media/exercises/1419-pZwUsKB.gif', '/media/posters/1419-pZwUsKB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Isometric Chest Squeeze', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Hold this position for a few seconds, focusing on contracting your chest muscles.","Release the squeeze and relax your chest muscles.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1297', '/media/exercises/1297-HbSG1Pw.gif', '/media/posters/1297-HbSG1Pw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Jack Burpee', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES,SHOULDERS,TRICEPS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a standing position with your feet shoulder-width apart.', '["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the ground in front of you.","Kick your feet back, landing in a push-up position.","Perform a push-up, lowering your chest to the ground and then pushing back up.","Jump your feet forward, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0501', '/media/exercises/0501-mr7pkqP.gif', '/media/posters/0501-mr7pkqP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Jack Jump (male)', 'CARDIO', 'QUADRICEPS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet together and your arms by your sides.', '["Stand with your feet together and your arms by your sides.","Jump up, spreading your feet apart and raising your arms above your head.","As you land, quickly jump back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3224', '/media/exercises/3224-1g5bPpA.gif', '/media/posters/3224-1g5bPpA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/2612-e1e76I2.gif', poster_url = '/media/posters/2612-e1e76I2.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_2612', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Jump Rope') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Jump Squat V. 2', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively, extending your hips and knees fully.","Land softly on the balls of your feet and immediately lower your body back into a squat position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0513', '/media/exercises/0513-TDYiji6.gif', '/media/posters/0513-TDYiji6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Advanced Windmill', 'ABS', 'OBLIQUES,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Rotate your left foot slightly to the right, and shift your weight onto your left leg.","Bend your left knee and hinge at the hip, lowering your torso towards the left side.","Keep your right arm extended overhead and your eyes on the kettlebell.","As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.","Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.","Pause for a moment, then engage your core and push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0517', '/media/exercises/0517-Kal9cQQ.gif', '/media/posters/0517-Kal9cQQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Alternating Hang Clean', 'FOREARMS', 'SHOULDERS,TRAPS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang in front of your body with your arms fully extended.","In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.","Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0518', '/media/exercises/0518-I4tibZG.gif', '/media/posters/0518-I4tibZG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Alternating Press', 'SHOULDERS', 'TRICEPS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead, fully extending your arm.","Lower the kettlebell back to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0520', '/media/exercises/0520-5KLbZWx.gif', '/media/posters/0520-5KLbZWx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Alternating Press On Floor', 'CHEST', 'SHOULDERS,TRICEPS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by lying on your back on the floor with your knees bent and feet flat on the ground.', '["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.","Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.","Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.","Continue alternating the press motion with each kettlebell for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0519', '/media/exercises/0519-7w6i0vE.gif', '/media/posters/0519-7w6i0vE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Alternating Renegade Row', 'BACK', 'CORE,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.', '["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Pull one kettlebell up towards your chest, keeping your elbow close to your body.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0521', '/media/exercises/0521-b9kqlBy.gif', '/media/posters/0521-b9kqlBy.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Alternating Row', 'BACK', 'BICEPS,FOREARMS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0522', '/media/exercises/0522-Ca76jUE.gif', '/media/posters/0522-Ca76jUE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Bent Press', 'ABS', 'SHOULDERS,TRICEPS,OBLIQUES', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Rotate your torso to the left, shifting your weight onto your left foot.","Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.","As you lower, keep your eyes on the kettlebell and your chest lifted.","Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.","As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0524', '/media/exercises/0524-kjE55n5.gif', '/media/posters/0524-kjE55n5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Bottoms Up Clean From The Hang Position', 'BICEPS', 'FOREARMS,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebell to hang down between your legs, with your arm fully extended.","In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.","Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.","Lower the kettlebell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0525', '/media/exercises/0525-4KJEpzb.gif', '/media/posters/0525-4KJEpzb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Double Alternating Hang Clean', 'BICEPS', 'FOREARMS,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang straight down in front of your body.","In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.","As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.","Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0526', '/media/exercises/0526-a4F9Oyc.gif', '/media/posters/0526-a4F9Oyc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Double Jerk', 'SHOULDERS', 'TRICEPS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebells overhead, fully extending your arms.","Bend your knees and quickly drop into a partial squat.","Explosively extend your hips and knees, driving the kettlebells overhead.","Lock out your arms and catch the kettlebells overhead with your knees slightly bent.","Stand up straight and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0527', '/media/exercises/0527-tznL2Ad.gif', '/media/posters/0527-tznL2Ad.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Double Push Press', 'SHOULDERS', 'TRICEPS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.', '["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.","As the kettlebells reach the top, press them fully overhead, locking out your arms.","Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0528', '/media/exercises/0528-I4KkPdl.gif', '/media/posters/0528-I4KkPdl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Double Snatch', 'SHOULDERS', 'TRAPEZIUS,FOREARMS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs.', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0529', '/media/exercises/0529-M74kdvm.gif', '/media/posters/0529-M74kdvm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Double Windmill', 'ABS', 'SHOULDERS,HAMSTRINGS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Extend your right arm overhead, keeping your eyes on the kettlebell.","Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.","Bend at the waist to the left, keeping your right arm extended overhead.","Lower the kettlebell towards the ground, reaching towards your left foot.","Pause for a moment, then engage your core and push through your right foot to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0530', '/media/exercises/0530-OaE7CpD.gif', '/media/posters/0530-OaE7CpD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Extended Range One Arm Press On Floor', 'CHEST', 'TRICEPS,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by lying on your back on the floor with your knees bent and feet flat on the ground.', '["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0531', '/media/exercises/0531-rseLfH3.gif', '/media/posters/0531-rseLfH3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Front Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes slightly turned out.', '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the kettlebell with both hands in front of your chest, close to your body.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0533', '/media/exercises/0533-DB0n8AG.gif', '/media/posters/0533-DB0n8AG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Goblet Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.', '["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0534', '/media/exercises/0534-ZA8b5hc.gif', '/media/posters/0534-ZA8b5hc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Lunge Pass Through', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.","Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.","Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.","Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0536', '/media/exercises/0536-WKMQzCD.gif', '/media/posters/0536-WKMQzCD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell One Arm Clean And Jerk', 'SHOULDERS', 'TRICEPS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0537', '/media/exercises/0537-vzAxBtt.gif', '/media/posters/0537-vzAxBtt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell One Arm Floor Press', 'CHEST', 'TRICEPS,SHOULDERS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground.', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.","Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.","Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1298', '/media/exercises/1298-rg59QCH.gif', '/media/posters/1298-rg59QCH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell One Arm Jerk', 'SHOULDERS', 'TRICEPS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebell overhead in a straight line, fully extending your arm.","As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.","As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.","Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.","Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.","Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0538', '/media/exercises/0538-S37C94C.gif', '/media/posters/0538-S37C94C.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell One Arm Military Press To The Side', 'SHOULDERS', 'TRICEPS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Engage your core and keep your back straight.","Press the kettlebell overhead, extending your arm fully.","Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0539', '/media/exercises/0539-yCvYdi7.gif', '/media/posters/0539-yCvYdi7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell One Arm Push Press', 'SHOULDERS', 'TRICEPS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.","Bend your knees slightly and engage your core.","Press the kettlebell overhead by extending your arm and fully extending your legs.","Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0540', '/media/exercises/0540-osdXT3K.gif', '/media/posters/0540-osdXT3K.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell One Arm Row', 'BACK', 'BICEPS,FOREARMS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0541', '/media/exercises/0541-g9AsZ8P.gif', '/media/posters/0541-g9AsZ8P.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell One Arm Snatch', 'SHOULDERS', 'TRAPEZIUS,FOREARMS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.","Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0542', '/media/exercises/0542-aXcUyKb.gif', '/media/posters/0542-aXcUyKb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Pirate Supper Legs', 'SHOULDERS', 'TRICEPS,FOREARMS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in one hand.', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the kettlebell up to shoulder height, keeping your elbow close to your body.","Extend your arm fully overhead, straightening your elbow.","Lower the kettlebell back down to shoulder height, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0543', '/media/exercises/0543-kuXhl0o.gif', '/media/posters/0543-kuXhl0o.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0544-5bpPTHv.gif', poster_url = '/media/posters/0544-5bpPTHv.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0544', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Kettlebell Pistol Squat') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Plyo Push-up', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands on the kettlebells, shoulder-width apart.', '["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.","Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0545', '/media/exercises/0545-ktf3nvW.gif', '/media/posters/0545-ktf3nvW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Seated Two Arm Military Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your back straight and feet flat on the ground.', '["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder level with your palms facing forward.","Press the kettlebells overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1438', '/media/exercises/1438-ZEkjZDi.gif', '/media/posters/1438-ZEkjZDi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0549-UHJlbu3.gif', poster_url = '/media/posters/0549-UHJlbu3.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0549', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Kettlebell Swing') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Turkish Get Up (squat Style)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CORE', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.', '["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.","Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Pressing through your right foot, lift your hips off the ground, coming into a bridge position.","Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.","Rotate your torso to the left, bringing your left hand to the ground for support.","Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.","From the kneeling position, stand up, keeping the kettlebell extended overhead.","Reverse the movement to return to the starting position.","Repeat the exercise on the other side, starting with the kettlebell in your left hand."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0551', '/media/exercises/0551-Ha7SZ3y.gif', '/media/posters/0551-Ha7SZ3y.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Two Arm Clean', 'SHOULDERS', 'TRAPS,FOREARMS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0552', '/media/exercises/0552-7Ba7bQ2.gif', '/media/posters/0552-7Ba7bQ2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Two Arm Military Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Engage your core and press the kettlebells overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0553', '/media/exercises/0553-blBXysN.gif', '/media/posters/0553-blBXysN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kettlebell Two Arm Row', 'BACK', 'BICEPS,FOREARMS', 'KETTLEBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1345', '/media/exercises/1345-wf24o8S.gif', '/media/posters/1345-wf24o8S.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kick Out Sit', 'HAMSTRINGS', 'QUADRICEPS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Lean back slightly and place your hands on the edge of the bench or chair for support.","Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0555', '/media/exercises/0555-v7p5bYl.gif', '/media/posters/0555-v7p5bYl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Knee Touch Crunch', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3640', '/media/exercises/3640-dTg95eZ.gif', '/media/posters/3640-dTg95eZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kneeling Lat Stretch', 'BACK', 'SHOULDERS,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Kneel on the ground with your knees hip-width apart and your toes pointing back.', '["Kneel on the ground with your knees hip-width apart and your toes pointing back.","Extend your arms overhead and interlace your fingers.","Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1346', '/media/exercises/1346-f38OEuO.gif', '/media/posters/1346-f38OEuO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kneeling Plank Tap Shoulder (male)', 'ABS', 'SHOULDERS,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a kneeling position with your hands on the ground, shoulder-width apart.', '["Start in a kneeling position with your hands on the ground, shoulder-width apart.","Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Return the hand to the ground and repeat with the other hand.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3239', '/media/exercises/3239-h1ezqSu.gif', '/media/posters/3239-h1ezqSu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Kneeling Push-up (male)', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.', '["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3211', '/media/exercises/3211-ZOuKWir.gif', '/media/posters/3211-ZOuKWir.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Korean Dips', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Position yourself between two parallel bars with your arms extended and supporting your body weight.', '["Position yourself between two parallel bars with your arms extended and supporting your body weight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3288', '/media/exercises/3288-rWoBmi5.gif', '/media/posters/3288-rWoBmi5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/3419-UpWmA5E.gif', poster_url = '/media/posters/3419-UpWmA5E.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_3419', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('L-Sit on Floor') AND (media_url IS NULL OR media_url = '');
UPDATE exercises SET media_url = '/media/exercises/0562-QYysSLV.gif', poster_url = '/media/posters/0562-QYysSLV.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0562', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Landmine 180') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Landmine Lateral Raise', 'SHOULDERS', 'TRAPS,UPPER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, resting it on the front of your shoulders.","Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3237', '/media/exercises/3237-eXMFHww.gif', '/media/posters/3237-eXMFHww.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lean Planche', 'ABS', 'SHOULDERS,CHEST,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands shoulder-width apart and your body straight.', '["Start in a push-up position with your hands shoulder-width apart and your body straight.","Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Keep your elbows slightly bent and your body straight as you lean forward.","Hold this position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3300', '/media/exercises/3300-LYJodFS.gif', '/media/posters/3300-LYJodFS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/2271-hoXt6wv.gif', poster_url = '/media/posters/2271-hoXt6wv.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_2271', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Left hook. Boxing') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Leg Pull In Flat Bench', 'ABS', 'HIP FLEXORS,LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat bench with your legs extended straight out in front of you.', '["Sit on a flat bench with your legs extended straight out in front of you.","Place your hands on the bench beside your hips for support.","Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0570', '/media/exercises/0570-OyoZ3Pu.gif', '/media/posters/0570-OyoZ3Pu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Alternate Leg Press', 'QUADS', 'HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat and foot platform of the leverage machine to your desired position.', '["Adjust the seat and foot platform of the leverage machine to your desired position.","Sit on the machine with your back against the backrest and your feet on the foot platform.","Place your hands on the handles or sides of the machine for stability.","Push one foot against the foot platform, extending your leg until it is almost fully straight.","Pause for a moment, then slowly bend your leg and return to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2287', '/media/exercises/2287-V07qpXy.gif', '/media/posters/2287-V07qpXy.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Alternating Narrow Grip Seated Row', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and footplate position to ensure proper alignment.', '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your back straight and feet flat on the footplate.","Grasp the handles with a narrow grip, palms facing each other.","Keep your chest up and shoulders back throughout the exercise.","Pull one handle towards your torso while keeping the other handle stationary.","Squeeze your shoulder blades together at the end of the movement.","Slowly return the handle to the starting position and repeat with the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0571', '/media/exercises/0571-w2oRpuH.gif', '/media/posters/0571-w2oRpuH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Assisted Chin-up', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the leverage machine to your desired resistance level.', '["Adjust the leverage machine to your desired resistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your body straight.","Engage your back muscles and pull your body up towards the handles, leading with your chest.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0572', '/media/exercises/0572-MaMuGH6.gif', '/media/posters/0572-MaMuGH6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0574', '/media/exercises/0574-X3cqyXz.gif', '/media/posters/0574-X3cqyXz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Bent-over Row With V-bar', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself facing the machine.', '["Adjust the seat height and position yourself facing the machine.","Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3200', '/media/exercises/3200-LuBEORI.gif', '/media/posters/3200-LuBEORI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Bicep Curl', 'BICEPS', 'FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back against the pad.', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.","Exhale and curl the handles upward, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0575', '/media/exercises/0575-q6y3OhV.gif', '/media/posters/0575-q6y3OhV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Chest Press', 'CHEST', 'TRICEPS,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back flat against the pad.', '["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0576', '/media/exercises/0576-DOoWcnA.gif', '/media/posters/0576-DOoWcnA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Deadlift', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and foot platform to your desired position.', '["Adjust the seat height and foot platform to your desired position.","Sit on the machine with your back against the pad and your feet flat on the foot platform.","Grasp the handles or the sides of the seat for stability.","Engage your glutes and hamstrings, and push through your heels to lift the weight up.","Keep your back straight and avoid rounding your shoulders.","Extend your hips fully at the top of the movement, squeezing your glutes.","Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0578', '/media/exercises/0578-GUT8I22.gif', '/media/posters/0578-GUT8I22.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Donkey Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the leverage machine to the appropriate height for your body.', '["Adjust the leverage machine to the appropriate height for your body.","Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Place your hands on the handles or the support bars for stability.","Engage your calves and lift your heels as high as possible, using the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1253', '/media/exercises/1253-C9LuR4A.gif', '/media/posters/1253-C9LuR4A.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Front Pulldown', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.', '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.","Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0579', '/media/exercises/0579-7F1DVzn.gif', '/media/posters/0579-7F1DVzn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Gripless Shrug', 'BACK', 'SHOULDERS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the leverage machine.', '["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with your palms facing inwards and your arms fully extended.","Keeping your back straight, exhale and elevate your shoulders as high as possible.","Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0580', '/media/exercises/0580-f91FwXG.gif', '/media/posters/0580-f91FwXG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Gripless Shrug V. 2', 'BACK', 'SHOULDERS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back against the pad.', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles or bars with an overhand grip, keeping your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1439', '/media/exercises/1439-cbuFJrn.gif', '/media/posters/1439-cbuFJrn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Gripper Hands', 'FOREARMS', 'BICEPS,TRICEPS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and grip the handles of the leverage machine.', '["Adjust the seat height and grip the handles of the leverage machine.","Keep your back straight and your feet flat on the ground.","Exhale and squeeze the handles, contracting your forearms.","Hold the contraction for a second, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2288', '/media/exercises/2288-mKwcrHn.gif', '/media/posters/2288-mKwcrHn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Hammer Grip Preacher Curl', 'BICEPS', 'FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the leverage machine.', '["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the preacher pad, ensuring your chest is pressed against it.","Grasp the handles with a hammer grip (palms facing each other).","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1615', '/media/exercises/1615-OAguZoG.gif', '/media/posters/1615-OAguZoG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever High Row', 'BACK', 'BICEPS,REAR DELTOIDS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and foot platform to a comfortable position.', '["Adjust the seat height and foot platform to a comfortable position.","Sit on the machine with your chest against the pad and your feet flat on the foot platform.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0581', '/media/exercises/0581-nZZZy9m.gif', '/media/posters/0581-nZZZy9m.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Hip Extension V. 2', 'GLUTES', 'HAMSTRINGS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to fit your body and sit on it with your back against the backrest.', '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your feet on the footrests and grip the handles for stability.","Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2286', '/media/exercises/2286-OPqShYN.gif', '/media/posters/2286-OPqShYN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Horizontal One Leg Press', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.', '["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Place your hands on the handles or sides of the machine for stability.","Push the footplate away from your body by extending your leg, keeping your back against the backrest.","Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2611', '/media/exercises/2611-9KU9TYF.gif', '/media/posters/2611-9KU9TYF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Incline Chest Press V. 2', 'CHEST', 'TRICEPS,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and backrest angle on the leverage machine to a comfortable position.', '["Adjust the seat height and backrest angle on the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.","Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1479', '/media/exercises/1479-o17Jfkt.gif', '/media/posters/1479-o17Jfkt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Kneeling Leg Curl', 'HAMSTRINGS', 'GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to fit your body and select the desired weight.', '["Adjust the machine to fit your body and select the desired weight.","Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position, fully extending your knees.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0582', '/media/exercises/0582-nnmCTLN.gif', '/media/posters/0582-nnmCTLN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Kneeling Twist', 'ABS', 'OBLIQUES,LOWER BACK', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.', '["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.","Grasp the handles or the sides of the machine for stability.","Keeping your core engaged, twist your torso to one side as far as comfortably possible.","Pause for a moment, then slowly return to the starting position.","Repeat the twist to the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0583', '/media/exercises/0583-sZOR9EV.gif', '/media/posters/0583-sZOR9EV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Lateral Raise', 'SHOULDERS', 'TRAPS,UPPER BACK', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back against the pad.', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Exhale and raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0584', '/media/exercises/0584-dRTfGZT.gif', '/media/posters/0584-dRTfGZT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Leg Extension', 'QUADS', 'HAMSTRINGS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and backrest of the machine to fit your body.', '["Adjust the seat height and backrest of the machine to fit your body.","Sit on the machine with your back against the backrest and your feet on the footpad.","Grasp the handles or sidebars for stability.","Extend your legs forward by straightening your knees, lifting the weight.","Pause for a moment at the top, then slowly lower the weight back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0585', '/media/exercises/0585-my33uHU.gif', '/media/posters/0585-my33uHU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Lying Leg Curl', 'HAMSTRINGS', 'CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to fit your body and select the desired weight.', '["Adjust the machine to fit your body and select the desired weight.","Lie face down on the machine with your legs straight and your heels against the padded lever.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0586', '/media/exercises/0586-17lJ1kr.gif', '/media/posters/0586-17lJ1kr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Lying Two-one Leg Curl', 'HAMSTRINGS', 'GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to fit your body and sit on it with your back against the backrest.', '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your legs on the lever pad, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper body still, exhale and curl your legs up towards your glutes.","Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3195', '/media/exercises/3195-UXpKJoq.gif', '/media/posters/3195-UXpKJoq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Military Press', 'SHOULDERS', 'TRICEPS,UPPER CHEST', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back against the backrest.', '["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0587', '/media/exercises/0587-CggQhII.gif', '/media/posters/0587-CggQhII.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Narrow Grip Seated Row', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and footrests to ensure proper form.', '["Adjust the seat height and footrests to ensure proper form.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with a narrow grip, palms facing each other.","Keep your back straight and lean slightly forward.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0588', '/media/exercises/0588-IGjKj1v.gif', '/media/posters/0588-IGjKj1v.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever One Arm Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.","Bend forward at the hips, keeping your back straight and your head up.","Let the barbell hang in front of you with your arms fully extended.","Pull the barbell up towards your chest, keeping your elbows close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0589', '/media/exercises/0589-Fhdtwf3.gif', '/media/posters/0589-Fhdtwf3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever One Arm Lateral High Row', 'BACK', 'BICEPS,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself facing the machine.', '["Adjust the seat height and position yourself facing the machine.","Grasp the handle with one hand and keep your back straight.","Pull the handle towards your body, keeping your elbow close to your side.","Squeeze your back muscles at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1356', '/media/exercises/1356-OIFMAp1.gif', '/media/posters/1356-OIFMAp1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever One Arm Lateral Wide Pulldown', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.","Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.","Slowly return the handle to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1347', '/media/exercises/1347-tTuZSDT.gif', '/media/posters/1347-tTuZSDT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever One Arm Shoulder Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back against the pad.', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the lever handle with one hand and position your elbow at a 90-degree angle.","Press the lever upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the lever back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0590', '/media/exercises/0590-2KGnL6M.gif', '/media/posters/0590-2KGnL6M.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Overhand Triceps Dip', 'TRICEPS', 'CHEST,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to the appropriate height and secure your body in position.', '["Adjust the machine to the appropriate height and secure your body in position.","Grasp the handles with an overhand grip and position your body so that your arms are fully extended.","Lower your body by bending your elbows, keeping your upper arms close to your sides.","Continue lowering until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0591', '/media/exercises/0591-D5yqP2p.gif', '/media/posters/0591-D5yqP2p.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Preacher Curl', 'BICEPS', 'FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the leverage machine.', '["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the pad and grip the handles with an underhand grip.","Keep your back straight and your elbows positioned on the pad.","Exhale and curl your forearms towards your upper arms, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0592', '/media/exercises/0592-b6hQYMb.gif', '/media/posters/0592-b6hQYMb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Preacher Curl V. 2', 'BICEPS', 'FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.', '["Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale as you slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1614', '/media/exercises/1614-ye84CTU.gif', '/media/posters/1614-ye84CTU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Pullover', 'BACK', 'TRICEPS,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat and handles of the leverage machine to a comfortable position.', '["Adjust the seat and handles of the leverage machine to a comfortable position.","Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Keep your arms slightly bent and your core engaged.","Slowly pull the handles towards your chest, squeezing your lats.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2285', '/media/exercises/2285-4U7iLb5.gif', '/media/posters/2285-4U7iLb5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Reverse Grip Lateral Pulldown', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.', '["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2736', '/media/exercises/2736-ky8FLU8.gif', '/media/posters/2736-ky8FLU8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Reverse Grip Preacher Curl', 'BICEPS', 'FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the leverage machine.', '["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with an underhand grip, palms facing up.","Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1616', '/media/exercises/1616-kj3hy6W.gif', '/media/posters/1616-kj3hy6W.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Reverse Grip Vertical Row', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and footplate position to ensure proper alignment.', '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an underhand grip, palms facing up.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1348', '/media/exercises/1348-ZqNOWQ6.gif', '/media/posters/1348-ZqNOWQ6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Reverse Hyperextension', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the leverage machine to fit your body and secure your feet in the foot pads.', '["Adjust the leverage machine to fit your body and secure your feet in the foot pads.","Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Cross your arms over your chest or place them behind your head.","Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0593', '/media/exercises/0593-Krmb3cB.gif', '/media/posters/0593-Krmb3cB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Reverse T-bar Row', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and footplate position on the leverage machine.', '["Adjust the seat height and footplate position on the leverage machine.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1349', '/media/exercises/1349-BgljGjd.gif', '/media/posters/1349-BgljGjd.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Rotary Calf', 'CALVES', 'SOLEUS,ANKLE STABILIZERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.', '["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate, with your heels hanging off the edge.","Grasp the handles or the sides of the machine for stability.","Push through the balls of your feet, raising your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2315', '/media/exercises/2315-MrgP9L6.gif', '/media/posters/2315-MrgP9L6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Calf Press', 'CALVES', 'SOLEUS,HAMSTRINGS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat of the machine so that your shoulders are aligned with the lever pad.', '["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.","Place your toes on the lower portion of the platform and position your knees under the lever pad.","Grasp the handles on the sides of the seat for stability.","Press the lever pad down by extending your ankles, lifting your heels as high as possible.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2335', '/media/exercises/2335-Ie9UGty.gif', '/media/posters/2335-Ie9UGty.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Crunch', 'ABS', 'OBLIQUES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the leverage machine with your back against the pad and your feet flat on the floor.', '["Sit on the leverage machine with your back against the pad and your feet flat on the floor.","Grasp the handles or place your hands on the side pads for support.","Engage your abs and slowly lean back, allowing the pad to move with you.","Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1452', '/media/exercises/1452-Wgaz7pm.gif', '/media/posters/1452-Wgaz7pm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Crunch (chest Pad)', 'ABS', 'OBLIQUES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and chest pad position according to your comfort.', '["Adjust the seat height and chest pad position according to your comfort.","Sit on the machine with your back against the chest pad and your feet flat on the floor.","Grasp the handles or side bars for stability.","Engage your abs and slowly lean back, allowing the chest pad to move with you.","Pause for a moment at the maximum contraction, feeling the tension in your abs.","Slowly return to the starting position by contracting your abs and pulling yourself back up.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0595', '/media/exercises/0595-ZnJHhMk.gif', '/media/posters/0595-ZnJHhMk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Crunch V. 2', 'ABS', 'OBLIQUES,HIP FLEXORS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the leverage machine with your back against the pad and your feet secured under the footpads.', '["Sit on the leverage machine with your back against the pad and your feet secured under the footpads.","Place your hands on the handles or the sides of the seat for support.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly return to the starting position, allowing your back to round slightly.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3760', '/media/exercises/3760-eXFXCY0.gif', '/media/posters/3760-eXFXCY0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Dip', 'TRICEPS', 'CHEST,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.', '["Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.","Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1451', '/media/exercises/1451-BRImeP8.gif', '/media/posters/1451-BRImeP8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Fly', 'CHEST', 'DELTOIDS,TRAPEZIUS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back against the pad.', '["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with a pronated grip and keep your elbows slightly bent.","Exhale and push the handles forward, bringing them together in front of your chest.","Pause for a moment, squeezing your chest muscles.","Inhale and slowly return to the starting position, allowing your chest muscles to stretch.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0596', '/media/exercises/0596-v3xmPAR.gif', '/media/posters/0596-v3xmPAR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Good Morning', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height so that your hips are slightly higher than your knees.', '["Adjust the seat height so that your hips are slightly higher than your knees.","Sit on the machine with your back against the pad and your feet flat on the footrests.","Grasp the handles or the sides of the seat for stability.","Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.","Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3759', '/media/exercises/3759-XsCcxCC.gif', '/media/posters/3759-XsCcxCC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Hip Abduction', 'QUADS', 'GLUTES,HAMSTRINGS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height so that your knees are at a 90-degree angle.', '["Adjust the seat height so that your knees are at a 90-degree angle.","Sit on the machine with your back against the backrest and your feet on the footrests.","Place your hands on the side handles for stability.","Engage your abductors and slowly push your legs apart, away from the midline of your body.","Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0597', '/media/exercises/0597-CHpahtl.gif', '/media/posters/0597-CHpahtl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Leg Curl', 'HAMSTRINGS', 'CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to fit your body and sit on it with your back against the backrest.', '["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your lower legs under the padded lever, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper legs stationary, exhale and curl your legs up as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0599', '/media/exercises/0599-Zg3XY7P.gif', '/media/posters/0599-Zg3XY7P.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Leg Raise Crunch', 'ABS', 'HIP FLEXORS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the leverage machine with your back against the backrest and your feet on the footrests.', '["Sit on the leverage machine with your back against the backrest and your feet on the footrests.","Grasp the handles or sidebars for stability.","Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.","Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0600', '/media/exercises/0600-PQ2AtC3.gif', '/media/posters/0600-PQ2AtC3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Reverse Fly', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0602', '/media/exercises/0602-myfUsKf.gif', '/media/posters/0602-myfUsKf.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Reverse Fly (parallel Grip)', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0601', '/media/exercises/0601-xiHiJcA.gif', '/media/posters/0601-xiHiJcA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Seated Squat Calf Raise On Leg Press Machine', 'CALVES', 'QUADRICEPS,HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.', '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.","Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.","Release the safety handles and push the footplate away from you by extending your knees.","Once your knees are fully extended, slowly lower your heels by flexing your calves.","Pause for a moment at the bottom, then push the footplate back up by extending your calves.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1385', '/media/exercises/1385-IeDEXTe.gif', '/media/posters/1385-IeDEXTe.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Shoulder Press', 'SHOULDERS', 'TRICEPS,CHEST', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back against the backrest.', '["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands at shoulder level.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0603', '/media/exercises/0603-67n3r98.gif', '/media/posters/0603-67n3r98.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Shoulder Press V. 2', 'SHOULDERS', 'TRICEPS,CHEST', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and backrest of the leverage machine to a comfortable position.', '["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0869', '/media/exercises/0869-vqsbmL0.gif', '/media/posters/0869-vqsbmL0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Shoulder Press V. 3', 'SHOULDERS', 'TRICEPS,CHEST', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and backrest of the leverage machine to a comfortable position.', '["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2318', '/media/exercises/2318-dNFYIU1.gif', '/media/posters/2318-dNFYIU1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Shrug', 'BACK', 'SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the leverage machine with your back against the pad.', '["Adjust the seat height and position yourself on the leverage machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0604', '/media/exercises/0604-ZZKbeMw.gif', '/media/posters/0604-ZZKbeMw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Standing Calf Raise', 'CALVES', 'SOLEUS,ANKLE STABILIZERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the machine to your height and stand with your feet shoulder-width apart.', '["Adjust the machine to your height and stand with your feet shoulder-width apart.","Place your shoulders under the pads and hold onto the handles for stability.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0605', '/media/exercises/0605-ykUOVze.gif', '/media/posters/0605-ykUOVze.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Standing Chest Press', 'CHEST', 'SHOULDERS,TRICEPS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your feet flat on the ground.', '["Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Grasp the handles with an overhand grip and position your hands at chest level.","Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3758', '/media/exercises/3758-WbNq5Xu.gif', '/media/posters/3758-WbNq5Xu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever T Bar Row', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and footplate position to ensure proper alignment.', '["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0606', '/media/exercises/0606-aaXr7ld.gif', '/media/posters/0606-aaXr7ld.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever T-bar Reverse Grip Row', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1351', '/media/exercises/1351-FVM1AUZ.gif', '/media/posters/1351-FVM1AUZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lever Unilateral Row', 'BACK', 'BICEPS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself facing the machine.', '["Adjust the seat height and position yourself facing the machine.","Grasp the handles with an overhand grip and keep your back straight.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1313', '/media/exercises/1313-oROuvrX.gif', '/media/posters/1313-oROuvrX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('London Bridge', 'BACK', 'SHOULDERS,BICEPS,FOREARMS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Attach the rope to a high anchor point.', '["Attach the rope to a high anchor point.","Stand facing away from the anchor point with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Lean forward slightly, keeping your back straight and core engaged.","Pull the rope towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0609', '/media/exercises/0609-bLyQokI.gif', '/media/posters/0609-bLyQokI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Low Glute Bridge On Floor', 'GLUTES', 'HAMSTRINGS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your arms by your sides, palms facing down.","Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3013', '/media/exercises/3013-u0cNiij.gif', '/media/posters/3013-u0cNiij.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1352-ANbbry2.gif', poster_url = '/media/posters/1352-ANbbry2.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1352', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Lower Back Curl') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lunge With Jump', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart.', '["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Land softly with your left foot forward and immediately lower your body into a lunge position.","Continue alternating between lunges and jumps for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3582', '/media/exercises/3582-PM1PZjg.gif', '/media/posters/3582-PM1PZjg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lunge With Twist', 'ABS', 'QUADRICEPS,GLUTES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart.', '["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Pause for a moment, then return to the starting position.","Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1688', '/media/exercises/1688-K9VL0Jq.gif', '/media/posters/1688-K9VL0Jq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lying (side) Quads Stretch', 'QUADS', 'HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs straight.', '["Lie on your side with your legs straight.","Bend your top leg and grab your ankle or foot with your hand.","Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0613', '/media/exercises/0613-BWnJR72.gif', '/media/posters/0613-BWnJR72.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lying Elbow To Knee', 'ABS', 'HIP FLEXORS,LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, extend your right leg straight out and lift it off the ground.","Pause for a moment, then return to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2312', '/media/exercises/2312-AQIhRjM.gif', '/media/posters/2312-AQIhRjM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lying Leg Raise Flat Bench', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a flat bench with your back pressed against it.', '["Lie flat on a flat bench with your back pressed against it.","Place your hands under your glutes for support.","Keep your legs straight and together, and lift them up towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0620', '/media/exercises/0620-WhuFnR7.gif', '/media/posters/0620-WhuFnR7.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Lying Leg-hip Raise', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs extended and your arms by your sides.', '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, raising them towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0865', '/media/exercises/0865-9IxJdtC.gif', '/media/posters/0865-9IxJdtC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Machine Inner Chest Press', 'CHEST', 'TRICEPS,SHOULDERS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your back flat against the pad.', '["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1301', '/media/exercises/1301-wDN97Ca.gif', '/media/posters/1301-wDN97Ca.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('March Sit (wall)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your back against a wall and your feet hip-width apart.', '["Stand with your back against a wall and your feet hip-width apart.","Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Lift your right foot off the ground and bring your knee towards your chest.","Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Continue alternating between lifting your right and left foot for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0624', '/media/exercises/0624-sVQCCeG.gif', '/media/posters/0624-sVQCCeG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Medicine Ball Catch And Overhead Throw', 'BACK', 'SHOULDERS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.', '["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.","Bend your knees slightly and engage your core.","Lower your body into a squat position, keeping your back straight and chest up.","Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.","Release the ball at the top of the movement and catch it on the way down.","Lower your body back into the squat position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1353', '/media/exercises/1353-PsVS1QP.gif', '/media/posters/1353-PsVS1QP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Medicine Ball Chest Push From 3 Point Stance', 'CHEST', 'SHOULDERS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.', '["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Extend your legs and position your body in a straight line.","Lower your chest towards the ground while keeping your back straight.","Push the medicine ball away from your body, extending your arm fully.","Return to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1303', '/media/exercises/1303-dCJnuVq.gif', '/media/posters/1303-dCJnuVq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Medicine Ball Chest Push Multiple Response', 'CHEST', 'TRICEPS,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a medicine ball at chest level.', '["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1304', '/media/exercises/1304-7aolH9D.gif', '/media/posters/1304-7aolH9D.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Medicine Ball Chest Push Single Response', 'CHEST', 'TRICEPS,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding the medicine ball at chest level.', '["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1305', '/media/exercises/1305-jeHtrlO.gif', '/media/posters/1305-jeHtrlO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Medicine Ball Chest Push With Run Release', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a medicine ball at chest level.', '["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","As you push the ball forward, release it and let it roll forward.","Quickly run forward and catch the ball before it hits the ground.","Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.","Continue alternating legs and repeating the exercise for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1312', '/media/exercises/1312-pX9Elbe.gif', '/media/posters/1312-pX9Elbe.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Medicine Ball Close Grip Push Up', 'TRICEPS', 'CHEST,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands on the medicine ball, shoulder-width apart.', '["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1701', '/media/exercises/1701-8K7m2SS.gif', '/media/posters/1701-8K7m2SS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Medicine Ball Overhead Slam', 'BACK', 'SHOULDERS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.', '["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.","Engage your core and keep your back straight.","Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.","As you slam the ball down, use your entire body to generate power, including your shoulders and core.","Catch the ball on the bounce and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1354', '/media/exercises/1354-oHg8eop.gif', '/media/posters/1354-oHg8eop.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Medicine Ball Supine Chest Throw', 'TRICEPS', 'CHEST,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back on a bench with your knees bent and feet flat on the ground.', '["Lie flat on your back on a bench with your knees bent and feet flat on the ground.","Hold the medicine ball with both hands, extending your arms straight up above your chest.","Lower the medicine ball towards your chest, keeping your elbows close to your body.","Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.","Catch the medicine ball and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1750', '/media/exercises/1750-Al3tP0D.gif', '/media/posters/1750-Al3tP0D.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Mixed Grip Chin-up', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.', '["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0627', '/media/exercises/0627-T8UpLkb.gif', '/media/posters/0627-T8UpLkb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Modified Hindu Push-up (male)', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Lower your body towards the ground, bending your elbows and keeping your core engaged.","As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3217', '/media/exercises/3217-epOSYUZ.gif', '/media/posters/3217-epOSYUZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Modified Push Up To Lower Arms', 'FOREARMS', 'TRICEPS,CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands directly under your shoulders and your body in a straight line.', '["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1421', '/media/exercises/1421-arvaszz.gif', '/media/posters/1421-arvaszz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0628-O95afRA.gif', poster_url = '/media/posters/0628-O95afRA.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0628', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Monster Walk') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Mountain Climber', 'CARDIO', 'CORE,SHOULDERS,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0630', '/media/exercises/0630-RJgzwny.gif', '/media/posters/0630-RJgzwny.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Muscle-up (on Vertical Bar)', 'BACK', 'BICEPS,TRICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.', '["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Continue pulling until your chest reaches the bar and your elbows are fully bent.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1401', '/media/exercises/1401-Af0EW2I.gif', '/media/posters/1401-Af0EW2I.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Narrow Push-up On Exercise Ball', 'TRICEPS', 'CHEST,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.', '["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ball by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2328', '/media/exercises/2328-4cWjYEN.gif', '/media/posters/2328-4cWjYEN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Negative Crunch', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0634', '/media/exercises/0634-szIn2UK.gif', '/media/posters/0634-szIn2UK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Oblique Crunch V. 2', 'ABS', 'OBLIQUES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your knees bent and feet flat on the ground.', '["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1495', '/media/exercises/1495-cJgSTmh.gif', '/media/posters/1495-cJgSTmh.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Oblique Crunches Floor', 'ABS', 'OBLIQUES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your knees bent and feet flat on the floor.', '["Lie on your back with your knees bent and feet flat on the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the floor.","Repeat on the other side, alternating sides with each repetition."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0635', '/media/exercises/0635-QUDd8WS.gif', '/media/posters/0635-QUDd8WS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Olympic Barbell Hammer Curl', 'BICEPS', 'FOREARMS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.', '["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.","Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0636', '/media/exercises/0636-o1ntciW.gif', '/media/posters/0636-o1ntciW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Olympic Barbell Triceps Extension', 'TRICEPS', 'SHOULDERS', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.', '["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0637', '/media/exercises/0637-wu5LXwz.gif', '/media/posters/0637-wu5LXwz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('One Arm Dip', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand facing away from a bench or chair, with your feet shoulder-width apart.', '["Stand facing away from a bench or chair, with your feet shoulder-width apart.","Place one hand on the bench or chair behind you, fingers pointing towards your body.","Extend your legs out in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0639', '/media/exercises/0639-FAoIFMw.gif', '/media/posters/0639-FAoIFMw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('One Arm Slam (with Medicine Ball)', 'ABS', 'SHOULDERS,BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.', '["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.","Bend your knees slightly and engage your core.","Raise the medicine ball above your head, fully extending your arm.","Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.","Catch the medicine ball on the bounce and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0640', '/media/exercises/0640-jCrtE9b.gif', '/media/posters/0640-jCrtE9b.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('One Arm Towel Row', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm fully, allowing the towel to hang in front of you.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1773', '/media/exercises/1773-bKWbrTA.gif', '/media/posters/1773-bKWbrTA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('One Leg Donkey Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes pointing forward.', '["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a stable surface for support, such as a wall or a bar.","Lift one leg off the ground, keeping your knee slightly bent.","Raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1386', '/media/exercises/1386-A2upspL.gif', '/media/posters/1386-A2upspL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('One Leg Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Extend one leg forward, keeping it off the ground.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Push through your heel to return to the starting position.","Repeat with the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1476', '/media/exercises/1476-C31LMnP.gif', '/media/posters/1476-C31LMnP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Outside Leg Kick Push-up', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Continue alternating leg kicks and push-ups for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0642', '/media/exercises/0642-jNU1gFQ.gif', '/media/posters/0642-jNU1gFQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Overhead Triceps Stretch', 'TRICEPS', 'SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand or sit upright with your feet shoulder-width apart.', '["Stand or sit upright with your feet shoulder-width apart.","Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0643', '/media/exercises/0643-Z5YStHW.gif', '/media/posters/0643-Z5YStHW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Pelvic Tilt', 'ABS', 'LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides.","Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Hold this position for a few seconds, focusing on contracting your abs.","Release the tilt and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3147', '/media/exercises/3147-NKJ8o6x.gif', '/media/posters/3147-NKJ8o6x.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1422-D9qe7CM.gif', poster_url = '/media/posters/1422-D9qe7CM.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1422', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Pelvic Tilt Into Bridge') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Posterior Step To Overhead Reach', 'ABS', 'GLUTES,HAMSTRINGS,QUADRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart and your arms by your sides.', '["Stand with your feet hip-width apart and your arms by your sides.","Take a step back with your right foot, landing on the ball of your foot.","Bend your left knee and lower your body into a lunge position.","As you lower into the lunge, simultaneously reach your arms overhead.","Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1687', '/media/exercises/1687-ErqK3UL.gif', '/media/posters/1687-ErqK3UL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Potty Squat', 'ABS', 'QUADRICEPS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes pointing slightly outward.', '["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Keep your chest up and your back straight throughout the movement.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3119', '/media/exercises/3119-75Bgtjy.gif', '/media/posters/3119-75Bgtjy.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Potty Squat With Support', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes pointing slightly outward.', '["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold onto a stable support, such as a chair or wall, for balance.","Lower your body down into a squat position by bending your knees and pushing your hips back.","Keep your chest up and your back straight throughout the movement.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3132', '/media/exercises/3132-b63ZzGe.gif', '/media/posters/3132-b63ZzGe.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Power Point Plank', 'ABS', 'SHOULDERS,TRICEPS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and squeeze your glutes to maintain a stable position.","Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Hold this position for the desired amount of time, keeping your core and glutes engaged.","To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3665', '/media/exercises/3665-hCjGsRQ.gif', '/media/posters/3665-hCjGsRQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Prisoner Half Sit-up (male)', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3203', '/media/exercises/3203-mgejmGP.gif', '/media/posters/3203-mgejmGP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Prone Twist On Stability Ball', 'ABS', 'OBLIQUES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.', '["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Place your hands behind your head or cross them over your chest.","Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Pause for a moment, then return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1707', '/media/exercises/1707-1IG6gVF.gif', '/media/posters/1707-1IG6gVF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Pull Up (neutral Grip)', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.', '["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0651', '/media/exercises/0651-0V2YQjW.gif', '/media/posters/0651-0V2YQjW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Pull-in (on Stability Ball)', 'ABS', 'HIP FLEXORS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the sides of the stability ball for support.","Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.","Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0650', '/media/exercises/0650-UQr48Oi.gif', '/media/posters/0650-UQr48Oi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push And Pull Bodyweight', 'CHEST', 'TRICEPS,DELTOIDS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1689', '/media/exercises/1689-wXvUZC8.gif', '/media/posters/1689-wXvUZC8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push To Run', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands shoulder-width apart and your body in a straight line.', '["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your hands to extend your arms and return to the starting position.","Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating knees as fast as you can while maintaining good form.","Continue for the desired duration or number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3638', '/media/exercises/3638-PrQbjvB.gif', '/media/posters/3638-PrQbjvB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push Up On Bosu Ball', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the bosu ball on the ground with the flat side facing up.', '["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1307', '/media/exercises/1307-wVompEp.gif', '/media/posters/1307-wVompEp.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up (bosu Ball)', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the bosu ball on the ground with the flat side facing up.', '["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0653', '/media/exercises/0653-2kr2lWy.gif', '/media/posters/0653-2kr2lWy.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up (on Stability Ball)', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.', '["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0655', '/media/exercises/0655-Y4BRNQF.gif', '/media/posters/0655-Y4BRNQF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0656-tgryw5Y.gif', poster_url = '/media/posters/0656-tgryw5Y.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0656', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Push-up (on Stability Ball)') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up (wall)', 'CHEST', 'TRICEPS,DELTOIDS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a wall, about arm''s length away.', '["Stand facing a wall, about arm''s length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your feet hip-width apart.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push back up to the starting position, straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0659', '/media/exercises/0659-LEH9jxP.gif', '/media/posters/0659-LEH9jxP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up (wall) V. 2', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a wall, about arm''s length away.', '["Stand facing a wall, about arm''s length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back with your feet, keeping them hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the wall, keeping your body straight.","Pause for a moment, then push yourself back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0658', '/media/exercises/0658-NCmbLCw.gif', '/media/posters/0658-NCmbLCw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up Close-grip Off Dumbbell', 'TRICEPS', 'CHEST,SHOULDERS', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands placed close together, directly under your shoulders.', '["Start in a push-up position with your hands placed close together, directly under your shoulders.","Hold a dumbbell in each hand, resting them on the ground.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0660', '/media/exercises/0660-KZXAtKQ.gif', '/media/posters/0660-KZXAtKQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up Inside Leg Kick', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.","As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.","Lower your leg back down and repeat the push-up, then switch to the other leg.","Continue alternating leg kicks with each push-up repetition."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0661', '/media/exercises/0661-0br45wL.gif', '/media/posters/0661-0br45wL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up Medicine Ball', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands on the medicine ball, shoulder-width apart.', '["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0663', '/media/exercises/0663-W8KAlkI.gif', '/media/posters/0663-W8KAlkI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up On Lower Arms', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a plank position with your forearms on the ground and elbows directly below your shoulders.', '["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1467', '/media/exercises/1467-4Jt8QsQ.gif', '/media/posters/1467-4Jt8QsQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up Plus', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3145', '/media/exercises/3145-pvBMLHA.gif', '/media/posters/3145-pvBMLHA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Push-up To Side Plank', 'ABS', 'SHOULDERS,CHEST,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands shoulder-width apart and your body in a straight line.', '["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push back up to the starting position.","Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Hold the side plank position for a few seconds, then return to the starting position.","Repeat the push-up and side plank on the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0664', '/media/exercises/0664-KhHJ338.gif', '/media/posters/0664-KhHJ338.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Quads', 'QUADS', 'HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Keep your chest up and your back straight.","Lower yourself until your thighs are parallel to the ground.","Push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3533', '/media/exercises/3533-6YUfHPL.gif', '/media/posters/3533-6YUfHPL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Quarter Sit-up', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3201', '/media/exercises/3201-enxnJcM.gif', '/media/posters/3201-enxnJcM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Quick Feet V. 2', 'QUADS', 'CALVES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your arms by your sides.', '["Stand with your feet shoulder-width apart and your arms by your sides.","Begin by rapidly moving your feet up and down, as if you were running in place.","Keep your movements quick and light, focusing on staying on the balls of your feet.","Continue for the desired duration or number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3552', '/media/exercises/3552-mweqJin.gif', '/media/posters/3552-mweqJin.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Raise Single Arm Push-up', 'CHEST', 'TRICEPS,SHOULDERS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Extend one arm straight out to the side, parallel to the ground.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position, using your chest muscles to lift your body.","Repeat with the other arm extended."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0666', '/media/exercises/0666-13TpY4H.gif', '/media/posters/0666-13TpY4H.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rear Decline Bridge', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your feet flat on the ground and your knees bent.', '["Lie on your back with your feet flat on the ground and your knees bent.","Place your arms by your sides with your palms facing down.","Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0668', '/media/exercises/0668-UpAlold.gif', '/media/posters/0668-UpAlold.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rear Deltoid Stretch', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand tall with your feet shoulder-width apart.', '["Stand tall with your feet shoulder-width apart.","Extend your right arm across your chest, placing your left hand on your right elbow.","Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0669', '/media/exercises/0669-xifhB5W.gif', '/media/posters/0669-xifhB5W.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rear Pull-up', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0670', '/media/exercises/0670-CbFSYC1.gif', '/media/posters/0670-CbFSYC1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Reclining Big Toe Pose With Rope', 'HAMSTRINGS', 'CALVES,GLUTES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your legs extended and your arms by your sides.', '["Lie on your back with your legs extended and your arms by your sides.","Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.","Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.","Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1582', '/media/exercises/1582-K5xgdvI.gif', '/media/posters/1582-K5xgdvI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Resistance Band Hip Thrusts On Knees (female)', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Start by kneeling on the ground with your knees hip-width apart and your feet flexed.', '["Start by kneeling on the ground with your knees hip-width apart and your feet flexed.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on your hips or extend them out in front of you for balance.","Engage your glutes and core muscles.","Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.","Hold the position for a moment, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3236', '/media/exercises/3236-Pjbc0Kt.gif', '/media/posters/3236-Pjbc0Kt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Resistance Band Leg Extension', 'QUADS', 'HAMSTRINGS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Attach the resistance band to a sturdy anchor point and secure it around your ankle.', '["Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Stand facing the anchor point with your feet shoulder-width apart.","Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Pause for a moment at the top, then slowly return your leg to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3007', '/media/exercises/3007-Y1MsI1l.gif', '/media/posters/3007-Y1MsI1l.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Resistance Band Seated Biceps Curl', 'BICEPS', 'FOREARMS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a chair or bench with your back straight and feet flat on the ground.', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.","Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the resistance band back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3123', '/media/exercises/3123-XFc3vpY.gif', '/media/posters/3123-XFc3vpY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Resistance Band Seated Chest Press', 'CHEST', 'SHOULDERS,TRICEPS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a chair or bench with your back straight and feet flat on the ground.', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Extend your arms forward, pushing the resistance band away from your chest.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3124', '/media/exercises/3124-4x5Okof.gif', '/media/posters/3124-4x5Okof.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Resistance Band Seated Hip Abduction', 'QUADS', 'GLUTES,HAMSTRINGS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a chair or bench with your back straight and feet flat on the ground.', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on the sides of the chair or bench for support.","Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.","Pause for a moment at the end of the movement, then slowly bring your knees back together.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3006', '/media/exercises/3006-0xDpB4L.gif', '/media/posters/3006-0xDpB4L.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Resistance Band Seated Shoulder Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on a chair or bench with your back straight and feet flat on the ground.', '["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Press the band overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the band back down to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3122', '/media/exercises/3122-S93zLTG.gif', '/media/posters/3122-S93zLTG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Resistance Band Seated Straight Back Row', 'BACK', 'BICEPS,SHOULDERS', 'BAND', 'INTERMEDIATE', 'COMPOUND', 'Sit on the floor with your legs extended and loop the resistance band around your feet.', '["Sit on the floor with your legs extended and loop the resistance band around your feet.","Hold the ends of the resistance band with your hands, palms facing each other.","Keep your back straight and lean slightly back, engaging your core.","Pull the resistance band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3144', '/media/exercises/3144-Nu7jqFE.gif', '/media/posters/3144-Nu7jqFE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Reverse Dip', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Position yourself between two parallel bars with your arms fully extended and your body straight.', '["Position yourself between two parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0672', '/media/exercises/0672-NZ5Qqkz.gif', '/media/posters/0672-NZ5Qqkz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Reverse Grip Pull-up', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Grab the pull-up bar with an underhand grip, hands shoulder-width apart.', '["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0674', '/media/exercises/0674-YAk5dIw.gif', '/media/posters/0674-YAk5dIw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Reverse Hyper Extension (on Stability Ball)', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.', '["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for stability.","Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0675', '/media/exercises/0675-vM5YS2g.gif', '/media/posters/0675-vM5YS2g.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Reverse Hyper On Flat Bench', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.', '["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Hold onto the bench for stability.","Keeping your legs straight, raise them up towards the ceiling as high as you can.","Squeeze your glutes at the top of the movement.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1423', '/media/exercises/1423-OrETs32.gif', '/media/posters/1423-OrETs32.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Reverse Plank With Leg Lift', 'ABS', 'GLUTES,HAMSTRINGS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.', '["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Hold for a moment, then lower your leg back down.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3663', '/media/exercises/3663-tFToB7l.gif', '/media/posters/3663-tFToB7l.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rocking Frog Stretch', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by kneeling on the ground with your knees hip-width apart.', '["Start by kneeling on the ground with your knees hip-width apart.","Place your hands on the ground in front of you for support.","Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Hold this position for a few seconds, feeling a stretch in your glutes.","Slowly return to the starting position by bending your knees and lowering your hips back down.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2571', '/media/exercises/2571-2Dk4xQV.gif', '/media/posters/2571-2Dk4xQV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Rocky Pull-up Pulldown', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of a pull-up bar with your feet shoulder-width apart.', '["Stand in front of a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0678', '/media/exercises/0678-cQ19bBP.gif', '/media/posters/0678-cQ19bBP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Roller Back Stretch', 'BACK', 'HAMSTRINGS,GLUTES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by sitting on the ground with your legs extended in front of you.', '["Start by sitting on the ground with your legs extended in front of you.","Place the roller perpendicular to your body, just below your glutes.","Slowly roll your body backwards, allowing the roller to move up your back.","Continue rolling until the roller reaches your upper back.","Pause for a moment, then slowly roll back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2208', '/media/exercises/2208-isofgzg.gif', '/media/posters/2208-isofgzg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Roller Body Saw', 'ABS', 'SHOULDERS,TRICEPS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start in a plank position with your forearms on the roller and your body in a straight line.', '["Start in a plank position with your forearms on the roller and your body in a straight line.","Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2204', '/media/exercises/2204-XeMvLgE.gif', '/media/posters/2204-XeMvLgE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Roller Hip Lat Stretch', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by kneeling on the ground with the roller positioned under your hips.', '["Start by kneeling on the ground with the roller positioned under your hips.","Place your hands on the roller for support.","Slowly roll the roller forward, extending your hips and stretching your glutes.","Hold the stretch for a few seconds, then roll back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2205', '/media/exercises/2205-0L2KwtI.gif', '/media/posters/2205-0L2KwtI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Roller Hip Stretch', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by sitting on the ground with your legs extended in front of you.', '["Start by sitting on the ground with your legs extended in front of you.","Place the roller under your glutes, just above your knees.","Lean back and place your hands on the ground behind you for support.","Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.","Pause for a moment at the end of the movement, feeling a stretch in your glutes.","Slowly roll the roller back to the starting position, extending your legs.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2202', '/media/exercises/2202-oMypNrz.gif', '/media/posters/2202-oMypNrz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Roller Reverse Crunch', 'ABS', 'HIP FLEXORS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.', '["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.","Place the roller between your feet and grip it with your toes.","Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.","Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2206', '/media/exercises/2206-SKXQAx3.gif', '/media/posters/2206-SKXQAx3.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Roller Seated Shoulder Flexor Depresor Retractor', 'CHEST', 'DELTOIDS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat surface with your legs extended in front of you.', '["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.","Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2203', '/media/exercises/2203-8coXSYU.gif', '/media/posters/2203-8coXSYU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Roller Seated Single Leg Shoulder Flexor Depresor Retractor', 'CHEST', 'DELTOIDS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat surface with your legs extended in front of you.', '["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean back slightly and engage your core muscles.","Raise the roller up to shoulder level, keeping your arms straight.","Slowly lower the roller back down to your thighs.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2209', '/media/exercises/2209-CjETvlw.gif', '/media/posters/2209-CjETvlw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Roller Side Lat Stretch', 'BACK', 'SHOULDERS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.', '["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.","Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2207', '/media/exercises/2207-c3Pfhti.gif', '/media/posters/2207-c3Pfhti.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Run', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing upright with your feet hip-width apart.', '["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0685', '/media/exercises/0685-oLrKqDH.gif', '/media/posters/0685-oLrKqDH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Run (equipment)', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing upright with your feet hip-width apart.', '["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0684', '/media/exercises/0684-y5p0H8a.gif', '/media/posters/0684-y5p0H8a.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Scapula Dips', 'BACK', 'RHOMBOIDS,DELTOIDS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart and your arms extended in front of you.', '["Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3012', '/media/exercises/3012-7xeukSt.gif', '/media/posters/3012-7xeukSt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Scapula Push-up', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your chest towards the ground, keeping your elbows close to your body.","As you lower, squeeze your shoulder blades together and push your chest forward.","Pause for a moment at the bottom, then push back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3021', '/media/exercises/3021-jV65tKx.gif', '/media/posters/3021-jV65tKx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Scissor Jumps (male)', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Jump off the ground and simultaneously cross your right leg in front of your left leg.","As you land, quickly switch legs, crossing your left leg in front of your right leg.","Continue alternating legs and jumping as quickly as possible.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3219', '/media/exercises/3219-Eh2v5Iu.gif', '/media/posters/3219-Eh2v5Iu.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Calf Stretch (male)', 'CALVES', 'HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a chair or bench with your feet flat on the ground.', '["Sit on the edge of a chair or bench with your feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1390', '/media/exercises/1390-17bqEXD.gif', '/media/posters/1390-17bqEXD.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Glute Stretch', 'GLUTES', 'HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your legs extended in front of you.', '["Sit on the ground with your legs extended in front of you.","Bend your right knee and cross your right ankle over your left thigh.","Place your right hand on the ground behind you for support.","With your left hand, gently press down on your right knee to deepen the stretch.","Hold the stretch for 30 seconds to 1 minute.","Switch sides and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1424', '/media/exercises/1424-DeDThfG.gif', '/media/posters/1424-DeDThfG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Leg Raise', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on a flat bench with your back straight and your feet flat on the ground.', '["Sit on a flat bench with your back straight and your feet flat on the ground.","Place your hands on the sides of the bench for support.","Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0689', '/media/exercises/0689-Hgs6Nl1.gif', '/media/posters/0689-Hgs6Nl1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Lower Back Stretch', 'BACK', 'GLUTES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a chair with your feet flat on the ground.', '["Sit on the edge of a chair with your feet flat on the ground.","Place your hands on your thighs or on the sides of the chair for support.","Slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your lower back and hold for 20-30 seconds.","Slowly return to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0690', '/media/exercises/0690-QFmz6ch.gif', '/media/posters/0690-QFmz6ch.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Piriformis Stretch', 'GLUTES', 'HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your legs extended in front of you.', '["Sit on the ground with your legs extended in front of you.","Bend your right knee and place your right foot on the outside of your left knee.","Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2567', '/media/exercises/2567-QY39eBr.gif', '/media/posters/2567-QY39eBr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Side Crunch (wall)', 'ABS', 'OBLIQUES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the floor with your back against a wall and your legs extended in front of you.', '["Sit on the floor with your back against a wall and your legs extended in front of you.","Bend your knees and place your feet flat on the floor, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lean to one side, bringing your elbow towards your hip.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0691', '/media/exercises/0691-Y9hNPcN.gif', '/media/posters/0691-Y9hNPcN.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Seated Wide Angle Pose Sequence', 'HAMSTRINGS', 'QUADRICEPS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your legs extended in a wide angle.', '["Sit on the ground with your legs extended in a wide angle.","Flex your feet and engage your quadriceps.","Place your hands on the ground behind you for support.","Keeping your back straight, lean forward from your hips.","Continue leaning forward until you feel a stretch in your hamstrings.","Hold this position for a few breaths.","Slowly release the stretch and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1587', '/media/exercises/1587-HIgYKAB.gif', '/media/posters/1587-HIgYKAB.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Self Assisted Inverse Leg Curl', 'HAMSTRINGS', 'GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back on a mat or bench with your legs extended.', '["Lie flat on your back on a mat or bench with your legs extended.","Place your hands by your sides or under your glutes for support.","Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0697', '/media/exercises/0697-GwYwElT.gif', '/media/posters/0697-GwYwElT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1766-ZSY3MsL.gif', poster_url = '/media/posters/1766-ZSY3MsL.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1766', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Self Assisted Inverse Leg Curl') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Self Assisted Inverse Leg Curl (on Floor)', 'HAMSTRINGS', 'GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs extended and your arms by your sides.', '["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and place your feet flat on the ground, hip-width apart.","Lift your hips off the ground, engaging your glutes and hamstrings.","Slowly curl your legs towards your glutes, keeping your hips lifted.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Lower your hips back down to the ground.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0696', '/media/exercises/0696-E4PwJqI.gif', '/media/posters/0696-E4PwJqI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Semi Squat Jump (male)', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively, extending your hips and knees while swinging your arms for momentum.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3222', '/media/exercises/3222-6FMU51h.gif', '/media/posters/3222-6FMU51h.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Short Stride Run', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Find an open space or a treadmill to perform the exercise.', '["Find an open space or a treadmill to perform the exercise.","Stand tall with your feet hip-width apart.","Start jogging in place, lifting your knees high and pumping your arms.","After a few seconds, start taking short strides forward, maintaining a quick pace.","Continue running with short strides for the desired duration or distance."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3656', '/media/exercises/3656-CcWEoWV.gif', '/media/posters/3656-CcWEoWV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Shoulder Grip Pull-up', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Grab the pull-up bar with a shoulder-width grip, palms facing away from you.', '["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Hang freely with your arms fully extended.","Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1763', '/media/exercises/1763-YtgD7Xq.gif', '/media/posters/1763-YtgD7Xq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Shoulder Tap', 'ABS', 'SHOULDERS,TRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line.', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Continue alternating shoulder taps while keeping your hips and torso stable.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3699', '/media/exercises/3699-yRpV5TC.gif', '/media/posters/3699-yRpV5TC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0699-qEse6fe.gif', poster_url = '/media/posters/0699-qEse6fe.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0699', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Shoulder Tap Push-up') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side Bridge Hip Abduction', 'QUADS', 'GLUTES,OBLIQUES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs extended and stacked on top of each other.', '["Lie on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Pause for a moment at the top, then lower your leg back down.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1774', '/media/exercises/1774-WL4EmxJ.gif', '/media/posters/1774-WL4EmxJ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side Bridge V. 2', 'ABS', 'OBLIQUES,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs extended and stacked on top of each other.', '["Lie on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the starting position.","Repeat on the other side."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0705', '/media/exercises/0705-RKjH6Lt.gif', '/media/posters/0705-RKjH6Lt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side Hip (on Parallel Bars)', 'ABS', 'OBLIQUES,HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand between two parallel bars with your feet shoulder-width apart.', '["Stand between two parallel bars with your feet shoulder-width apart.","Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Engage your abs and slowly lift your legs to the side, keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0709', '/media/exercises/0709-jTkSc6o.gif', '/media/posters/0709-jTkSc6o.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side Hip Abduction', 'QUADS', 'GLUTES,QUADRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your hands on your hips.', '["Stand with your feet shoulder-width apart and your hands on your hips.","Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0710', '/media/exercises/0710-7WaDzyL.gif', '/media/posters/0710-7WaDzyL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side Lying Hip Adduction (male)', 'QUADS', 'GLUTES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs straight and stacked on top of each other.', '["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3667', '/media/exercises/3667-c8f5cSY.gif', '/media/posters/3667-c8f5cSY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side Plank Hip Adduction', 'QUADS', 'OBLIQUES,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by lying on your side with your legs extended and stacked on top of each other.', '["Start by lying on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1775', '/media/exercises/1775-VO2qeJg.gif', '/media/posters/1775-VO2qeJg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side Push-up', 'TRICEPS', 'SHOULDERS,CHEST,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by lying on your side with your legs extended and stacked on top of each other.', '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0717', '/media/exercises/0717-wpbD28t.gif', '/media/posters/0717-wpbD28t.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side-to-side Chin', 'BACK', 'BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body relaxed.","Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Once your chin is above the bar, lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0720', '/media/exercises/0720-isAAZWA.gif', '/media/posters/0720-isAAZWA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Side-to-side Toe Touch (male)', 'ABS', 'OBLIQUES,HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your arms extended to the sides.', '["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Repeat the side-to-side bending motion for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3213', '/media/exercises/3213-WCAvOfC.gif', '/media/posters/3213-WCAvOfC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Single Leg Bridge With Outstretched Leg', 'GLUTES', 'HAMSTRINGS,QUADRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your knees bent and feet flat on the ground.', '["Lie on your back with your knees bent and feet flat on the ground.","Extend one leg straight out in front of you.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3645', '/media/exercises/3645-rmEukuS.gif', '/media/posters/3645-rmEukuS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Single Leg Calf Raise (on A Dumbbell)', 'CALVES', 'ANKLES,FEET', 'DUMBBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet hip-width apart and hold a dumbbell in one hand.', '["Stand with your feet hip-width apart and hold a dumbbell in one hand.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch to the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0727', '/media/exercises/0727-fKZgDEO.gif', '/media/posters/0727-fKZgDEO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Single Leg Platform Slide', 'HAMSTRINGS', 'GLUTES,QUADRICEPS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with one foot on a platform or slide board.', '["Start by standing with one foot on a platform or slide board.","Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Keep your core engaged and maintain a straight posture throughout the movement.","Slowly return to the starting position by sliding your foot back to the initial position.","Repeat the movement for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0730', '/media/exercises/0730-LNE3wfo.gif', '/media/posters/0730-LNE3wfo.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Single Leg Squat (pistol) Male', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and arms extended in front of you.', '["Stand with your feet shoulder-width apart and arms extended in front of you.","Lift your right foot off the ground and extend it forward.","Slowly lower your body down by bending your left knee and pushing your hips back.","Keep your chest up and your back straight as you lower yourself down.","Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1759', '/media/exercises/1759-nqs5HGV.gif', '/media/posters/1759-nqs5HGV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sit-up V. 2', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0735', '/media/exercises/0735-Bn6TXyO.gif', '/media/posters/0735-Bn6TXyO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sit-up With Arms On Chest', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your knees bent and feet flat on the ground.', '["Lie flat on your back with your knees bent and feet flat on the ground.","Cross your arms over your chest.","Engaging your abs, lift your upper body off the ground towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3679', '/media/exercises/3679-6ZCiYWQ.gif', '/media/posters/3679-6ZCiYWQ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Skater Hops', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump to the right, landing on your right foot.","As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Immediately jump to the left, landing on your left foot.","As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Continue alternating sides, jumping and tapping the ground with each leg.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3361', '/media/exercises/3361-zfNHMN9.gif', '/media/posters/3361-zfNHMN9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ski Ergometer', 'TRICEPS', 'SHOULDERS,FOREARMS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and footrests to a comfortable position.', '["Adjust the seat height and footrests to a comfortable position.","Grasp the handles with an overhand grip, palms facing down.","Sit up straight with your feet flat on the footrests.","Extend your arms straight out in front of you, keeping your elbows slightly bent.","Engage your triceps and push the handles down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2142', '/media/exercises/2142-vpQaQkH.gif', '/media/posters/2142-vpQaQkH.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Ski Step', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,GLUTES,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Bend your knees slightly and keep your back straight.","Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Continue alternating jumps from side to side, mimicking a skiing motion.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3671', '/media/exercises/3671-5MRH8H2.gif', '/media/posters/3671-5MRH8H2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Skin The Cat', 'BACK', 'SHOULDERS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by hanging from a bar with your arms fully extended and your body relaxed.', '["Start by hanging from a bar with your arms fully extended and your body relaxed.","Engage your core and lift your legs up, bringing your knees towards your chest.","Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3304', '/media/exercises/3304-MSfvriJ.gif', '/media/posters/3304-MSfvriJ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled 45 Degrees One Leg Press', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a 45-degree angle.', '["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the footplate.","Place one foot on the footplate and extend your leg, pushing the sled away from you.","Slowly bend your knee and lower the sled back to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1425', '/media/exercises/1425-WWD6FzI.gif', '/media/posters/1425-WWD6FzI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled 45в° Calf Press', 'CALVES', 'HAMSTRINGS', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a 45-degree angle.', '["Adjust the sled machine to a 45-degree angle.","Place your feet on the sled platform with your toes pointing forward.","Push the sled platform away from you by extending your ankles and calves.","Pause for a moment at the top, then slowly lower the sled platform back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0738', '/media/exercises/0738-qCNVnaU.gif', '/media/posters/0738-qCNVnaU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled 45в° Leg Press', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat and footplate of the sled machine to a comfortable position.', '["Adjust the seat and footplate of the sled machine to a comfortable position.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Continue pushing until your legs are almost fully extended, but without locking your knees.","Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0739', '/media/exercises/0739-10Z2DXU.gif', '/media/posters/0739-10Z2DXU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled 45в° Leg Press (back Pov)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat of the sled machine so that your knees are at a 45-degree angle.', '["Adjust the seat of the sled machine so that your knees are at a 45-degree angle.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards your body, controlling the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1464', '/media/exercises/1464-yn2lLSI.gif', '/media/posters/1464-yn2lLSI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled 45° Leg Press (side Pov)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.', '["Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push against the footplate to extend your legs, straightening them completely.","Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1463', '/media/exercises/1463-2Qh2J1e.gif', '/media/posters/1463-2Qh2J1e.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled 45в° Leg Wide Press', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a 45-degree angle.', '["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the foot platform.","Position your feet wider than shoulder-width apart.","Push against the foot platform to extend your legs and straighten your knees.","Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0740', '/media/exercises/0740-tj41Nu6.gif', '/media/posters/0740-tj41Nu6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled Closer Hack Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.', '["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.","Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Grip the handles on the sides of the machine for stability.","Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0741', '/media/exercises/0741-gf3ZjB9.gif', '/media/posters/0741-gf3ZjB9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled Forward Angled Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.', '["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Place your hands on the handles or the sides of the machine for support.","Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0742', '/media/exercises/0742-XDOiFns.gif', '/media/posters/0742-XDOiFns.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled Hack Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a comfortable position for your height.', '["Adjust the sled machine to a comfortable position for your height.","Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Hold onto the handles or bars for stability.","Lower your body by bending your knees and hips, keeping your back straight and chest up.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0743', '/media/exercises/0743-Qa55kX1.gif', '/media/posters/0743-Qa55kX1.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled Lying Calf Press', 'CALVES', 'HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a comfortable weight.', '["Adjust the sled machine to a comfortable weight.","Sit on the sled machine with your back against the pad and your feet on the platform.","Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.","Push the platform away from you by extending your ankles, keeping your knees slightly bent.","Continue pushing until your calves are fully contracted.","Hold the contraction for a moment, then slowly lower the platform back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2334', '/media/exercises/2334-g376LuL.gif', '/media/posters/2334-g376LuL.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled Lying Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the sled machine to a comfortable weight.', '["Adjust the sled machine to a comfortable weight.","Lie on your back on the sled machine with your feet on the footplate.","Position your feet shoulder-width apart and slightly angled outwards.","Grip the handles of the sled machine for stability.","Engage your glutes and core muscles.","Push through your heels and extend your legs to lift the sled.","Lower the sled back down by bending your knees and hips.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0744', '/media/exercises/0744-9n2149Z.gif', '/media/posters/0744-9n2149Z.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sled One Leg Calf Press On Leg Press', 'CALVES', 'HAMSTRINGS,GLUTES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.', '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Place your toes and the balls of your feet on the sled, keeping your heels off.","Push the sled forward by extending your ankles, keeping your knees slightly bent.","Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1392', '/media/exercises/1392-u0pLNgz.gif', '/media/posters/1392-u0pLNgz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sledge Hammer', 'ABS', 'FOREARMS,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.', '["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.","Engage your core and keep your back straight.","Swing the sledge hammer down towards the ground, using your core and upper body strength.","As you swing down, pivot your hips and transfer the force to the hammer.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1496', '/media/exercises/1496-REXmfVC.gif', '/media/posters/1496-REXmfVC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Back Shrug', 'BACK', 'SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and allow the barbell to hang in front of your thighs.","Lift your shoulders straight up towards your ears, squeezing your traps at the top.","Hold for a moment, then lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0746', '/media/exercises/0746-MzNnwx9.gif', '/media/posters/0746-MzNnwx9.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Behind Neck Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height of the smith machine so that the bar is at shoulder level.', '["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Lower the bar down to the back of your neck, keeping your elbows pointing forward.","Press the bar up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0747', '/media/exercises/0747-Gpn4ADc.gif', '/media/posters/0747-Gpn4ADc.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the height of the smith machine bar to chest level.', '["Adjust the height of the smith machine bar to chest level.","Lie flat on the bench with your feet firmly planted on the ground.","Grip the bar with an overhand grip slightly wider than shoulder-width apart.","Unrack the bar and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar touches your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0748', '/media/exercises/0748-trqKQv2.gif', '/media/posters/0748-trqKQv2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Bent Knee Good Morning', 'GLUTES', 'HAMSTRINGS,LOWER BACK', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart, toes pointing forward.', '["Start by standing with your feet shoulder-width apart, toes pointing forward.","Place the barbell across your upper back, resting it on your traps.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to raise your torso back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0749', '/media/exercises/0749-1bQkKZK.gif', '/media/posters/0749-1bQkKZK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the bar at hip height.', '["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1359', '/media/exercises/1359-ZX9UZmj.gif', '/media/posters/1359-ZX9UZmj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Close-grip Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the bench with your feet flat on the ground.', '["Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0751', '/media/exercises/0751-WcHl7ru.gif', '/media/posters/0751-WcHl7ru.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Deadlift', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,LOWER BACK', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the bar at hip height.', '["Set up the smith machine with the bar at hip height.","Stand with your feet shoulder-width apart, toes pointing slightly outward.","Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.","Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.","Stand up straight, fully extending your hips and knees.","Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0752', '/media/exercises/0752-UfePqpx.gif', '/media/posters/0752-UfePqpx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Decline Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the decline bench to the desired angle.', '["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0753', '/media/exercises/0753-ETZfAbZ.gif', '/media/posters/0753-ETZfAbZ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Decline Reverse-grip Press', 'CHEST', 'TRICEPS,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the smith machine to a decline position.', '["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0754', '/media/exercises/0754-MY9P1WA.gif', '/media/posters/0754-MY9P1WA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Front Squat (clean Grip)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES,CORE', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the barbell at shoulder height.', '["Set up the smith machine with the barbell at shoulder height.","Stand facing the barbell with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.","Keep your chest up, back straight, and core engaged.","Lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1433', '/media/exercises/1433-lFhb2Rw.gif', '/media/posters/1433-lFhb2Rw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Full Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the barbell at shoulder height.', '["Set up the smith machine with the barbell at shoulder height.","Stand with your feet shoulder-width apart, toes slightly turned out.","Step under the bar and position it across your upper back, resting on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar and take a step back, maintaining a stable stance.","Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3281', '/media/exercises/3281-NNoHCEA.gif', '/media/posters/3281-NNoHCEA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Hack Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the barbell on the smith machine to an appropriate height for your body.', '["Adjust the barbell on the smith machine to an appropriate height for your body.","Stand with your feet shoulder-width apart, toes slightly pointed outwards.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your chest up as you unrack the barbell.","Take a step back and position your feet slightly wider than shoulder-width apart.","Bend your knees and lower your body down, keeping your chest up and back straight.","Continue descending until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0755', '/media/exercises/0755-ZuPXtCK.gif', '/media/posters/0755-ZuPXtCK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Hip Raise', 'ABS', 'GLUTES,HAMSTRINGS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.', '["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.","Place your hands on the barbell, slightly wider than shoulder-width apart.","Engage your core and glutes, then push through your heels to raise your hips off the ground.","Continue lifting until your body forms a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0756', '/media/exercises/0756-CqhoytW.gif', '/media/posters/0756-CqhoytW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Incline Bench Press', 'CHEST', 'SHOULDERS,TRICEPS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the bench to a 30-45 degree incline.', '["Adjust the bench to a 30-45 degree incline.","Sit on the bench with your back flat against the pad and feet firmly on the ground.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0757', '/media/exercises/0757-5v7KYld.gif', '/media/posters/0757-5v7KYld.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Incline Reverse-grip Press', 'CHEST', 'TRICEPS,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat of the smith machine to a comfortable incline angle.', '["Adjust the seat of the smith machine to a comfortable incline angle.","Sit on the machine with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.","Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar is just above your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0758', '/media/exercises/0758-78VqWQK.gif', '/media/posters/0758-78VqWQK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Incline Shoulder Raises', 'CHEST', 'DELTOIDS,TRAPEZIUS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the smith machine to an incline position.', '["Adjust the smith machine to an incline position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Raise the barbell up towards the ceiling, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0759', '/media/exercises/0759-ayAHcEm.gif', '/media/posters/0759-ayAHcEm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Leg Press', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat and footplate of the smith machine to a comfortable position.', '["Adjust the seat and footplate of the smith machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grasp the handles or sides of the machine for stability.","Push the footplate away from you by extending your legs, keeping your back against the backrest.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards you, returning to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0760', '/media/exercises/0760-7zdxRTl.gif', '/media/posters/0760-7zdxRTl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Low Bar Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.', '["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Stand with your feet shoulder-width apart, toes slightly turned outwards.","Step under the bar and position it across your upper back, resting it on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar by straightening your legs and stepping back from the rack.","Take a deep breath and brace your core.","Initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your chest up and your back straight throughout the movement.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1434', '/media/exercises/1434-RGLscZM.gif', '/media/posters/1434-RGLscZM.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Machine Bicep Curl', 'BICEPS', 'FOREARMS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the height of the smith machine bar to be at waist level.', '["Adjust the height of the smith machine bar to be at waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1683', '/media/exercises/1683-zILLZ98.gif', '/media/posters/1683-zILLZ98.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Machine Decline Close Grip Bench Press', 'TRICEPS', 'CHEST,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the bench on the smith machine to a decline position.', '["Adjust the bench on the smith machine to a decline position.","Lie down on the bench with your feet firmly planted on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1625', '/media/exercises/1625-yB9SvIF.gif', '/media/posters/1625-yB9SvIF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Machine Incline Tricep Extension', 'TRICEPS', 'SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat of the smith machine so that the bar is at shoulder height.', '["Adjust the seat of the smith machine so that the bar is at shoulder height.","Sit on the bench with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.","Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1752', '/media/exercises/1752-o8aOcrz.gif', '/media/posters/1752-o8aOcrz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Machine Reverse Decline Close Grip Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the smith machine to a decline position.', '["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1626', '/media/exercises/1626-QyO6Uma.gif', '/media/posters/1626-QyO6Uma.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Narrow Row', 'BACK', 'BICEPS,REAR DELTOIDS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your feet flat on the floor.', '["Adjust the seat height and position yourself on the machine with your feet flat on the floor.","Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.","Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0761', '/media/exercises/0761-JGKowMS.gif', '/media/posters/0761-JGKowMS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith One Arm Row', 'BACK', 'BICEPS,FOREARMS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the height of the smith machine bar to waist level.', '["Adjust the height of the smith machine bar to waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with one hand using an overhand grip, with your palm facing down.","Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1360', '/media/exercises/1360-Q4DSJPC.gif', '/media/posters/1360-Q4DSJPC.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith One Leg Floor Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Position yourself on the floor under the smith machine bar, facing away from the machine.', '["Position yourself on the floor under the smith machine bar, facing away from the machine.","Place the balls of your feet on a raised surface, such as a weight plate or block.","Position the smith machine bar across your lower legs, just above your ankles.","Hold onto the bar with your hands for stability.","Raise your heels off the ground by extending your ankles, lifting your body up.","Pause at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1393', '/media/exercises/1393-9GXrTE6.gif', '/media/posters/1393-9GXrTE6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Rear Delt Row', 'SHOULDERS', 'TRAPEZIUS,RHOMBOIDS,BICEPS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0762', '/media/exercises/0762-nFUwqG6.gif', '/media/posters/0762-nFUwqG6.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Reverse Calf Raises', 'CALVES', 'HAMSTRINGS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the smith machine bar to a height just below your shoulders.', '["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support, keeping your back straight and core engaged.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0763', '/media/exercises/0763-ywaNfuh.gif', '/media/posters/0763-ywaNfuh.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/1394-Lsqrgh4.gif', poster_url = '/media/posters/1394-Lsqrgh4.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_1394', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Smith Reverse Calf Raises') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Reverse Grip Bent Over Row', 'BACK', 'BICEPS,FOREARMS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the bar at hip height.', '["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1361', '/media/exercises/1361-aaxA3cm.gif', '/media/posters/1361-aaxA3cm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Reverse-grip Press', 'CHEST', 'TRICEPS,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the height of the smith machine bar to chest level.', '["Adjust the height of the smith machine bar to chest level.","Stand facing the bar with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step back and position yourself with a slight bend in your knees.","Keep your chest up and core engaged throughout the exercise.","Lower the bar towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0764', '/media/exercises/0764-zK8Fu1W.gif', '/media/posters/0764-zK8Fu1W.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Seated One Leg Calf Raise', 'CALVES', 'HAMSTRINGS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Sit on the machine with your back against the pad and your feet on the footrest.', '["Sit on the machine with your back against the pad and your feet on the footrest.","Place one leg on the footrest and keep the other leg off the footrest.","Using your calf muscles, raise your heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1395', '/media/exercises/1395-0S75mYG.gif', '/media/posters/1395-0S75mYG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Seated Shoulder Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height so that the handles are at shoulder level.', '["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Lower the handles down to shoulder level, keeping your elbows slightly bent.","Press the handles up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0765', '/media/exercises/0765-xUwnBMT.gif', '/media/posters/0765-xUwnBMT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Seated Wrist Curl', 'FOREARMS', 'BICEPS,BRACHIALIS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench in front of a Smith machine with your feet flat on the ground.', '["Sit on a bench in front of a Smith machine with your feet flat on the ground.","Grasp the barbell with an underhand grip, hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1426', '/media/exercises/1426-B6dAO1t.gif', '/media/posters/1426-B6dAO1t.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Shoulder Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.', '["Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Press the bar upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0766', '/media/exercises/0766-903mzG8.gif', '/media/posters/0766-903mzG8.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Shrug', 'BACK', 'SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and your shoulders relaxed.","Lift your shoulders up towards your ears, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0767', '/media/exercises/0767-OUQ0ZyW.gif', '/media/posters/0767-OUQ0ZyW.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Sprint Lunge', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the barbell at hip height.', '["Set up the smith machine with the barbell at hip height.","Stand facing away from the machine with your feet shoulder-width apart.","Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.","Bend your left knee and lower your body into a lunge position, keeping your back straight.","Push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0769', '/media/exercises/0769-HsjbB1z.gif', '/media/posters/0769-HsjbB1z.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the barbell at an appropriate height for your squat.', '["Set up the smith machine with the barbell at an appropriate height for your squat.","Stand with your feet shoulder-width apart, toes slightly turned out.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grip the barbell with a wide grip, slightly wider than shoulder-width apart.","Engage your core and unrack the barbell, stepping back to clear the rack.","Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0770', '/media/exercises/0770-jFtipLl.gif', '/media/posters/0770-jFtipLl.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Standing Back Wrist Curl', 'FOREARMS', 'BICEPS,TRICEPS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Stand facing the smith machine with your feet shoulder-width apart.', '["Stand facing the smith machine with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, hands shoulder-width apart.","Keep your back straight and your elbows close to your body.","Slowly curl your wrists upwards, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0771', '/media/exercises/0771-hfmQ0Tz.gif', '/media/posters/0771-hfmQ0Tz.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Standing Behind Head Military Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height of the smith machine so that the bar is at shoulder level.', '["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Position the bar behind your head, resting on your upper traps.","Keep your core engaged and your chest lifted throughout the exercise.","Press the bar overhead by extending your arms, fully straightening them.","Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0772', '/media/exercises/0772-ht8xDrP.gif', '/media/posters/0772-ht8xDrP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Standing Leg Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.', '["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.","Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.","Place your hands on the bar for stability.","Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0773', '/media/exercises/0773-6MaEjVA.gif', '/media/posters/0773-6MaEjVA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Standing Military Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.","Press the barbell upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0774', '/media/exercises/0774-jjUPrze.gif', '/media/posters/0774-jjUPrze.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Sumo Squat', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Set up the smith machine with the barbell at hip height.', '["Set up the smith machine with the barbell at hip height.","Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Position yourself under the barbell, resting it on your upper back and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3142', '/media/exercises/3142-dzz6BiV.gif', '/media/posters/3142-dzz6BiV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Toe Raise', 'CALVES', 'ANKLES,SHINS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.', '["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.","Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.","Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your back straight throughout the exercise.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1396', '/media/exercises/1396-Y4QlY8z.gif', '/media/posters/1396-Y4QlY8z.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Upright Row', 'SHOULDERS', 'TRAPS,BICEPS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, facing the smith machine.', '["Stand with your feet shoulder-width apart, facing the smith machine.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell up towards your chin, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0775', '/media/exercises/0775-1DN3iz4.gif', '/media/posters/0775-1DN3iz4.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Wide Grip Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the bench to a comfortable position on the smith machine.', '["Adjust the bench to a comfortable position on the smith machine.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1308', '/media/exercises/1308-zoOvPcx.gif', '/media/posters/1308-zoOvPcx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Smith Wide Grip Decline Bench Press', 'CHEST', 'TRICEPS,SHOULDERS', 'SMITH_MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the decline bench to the desired angle.', '["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1309', '/media/exercises/1309-wi2H9QX.gif', '/media/posters/1309-wi2H9QX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0776-dG5Smob.gif', poster_url = '/media/posters/0776-dG5Smob.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0776', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Snatch Pull') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Sphinx', 'BACK', 'GLUTES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.', '["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Slowly lower your chest back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1362', '/media/exercises/1362-DIVyqrU.gif', '/media/posters/1362-DIVyqrU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Spider Crawl Push Up', 'GLUTES', 'CORE,CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Bring your right knee towards your right elbow, keeping it off the ground.","As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Push back up to the starting position and repeat with your left knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0778', '/media/exercises/0778-P9GFBME.gif', '/media/posters/0778-P9GFBME.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Spine Stretch', 'BACK', 'HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your legs extended in front of you.', '["Sit on the ground with your legs extended in front of you.","Place your hands on the ground behind you, fingers pointing towards your body.","Engage your core and slowly lean back, keeping your back straight.","Continue leaning back until you feel a stretch in your spine.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1363', '/media/exercises/1363-JbC2iaV.gif', '/media/posters/1363-JbC2iaV.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Spine Twist', 'ABS', 'OBLIQUES,LOWER BACK', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your legs extended in front of you.', '["Sit on the ground with your legs extended in front of you.","Bend your knees and place your feet flat on the ground, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side, bringing your left elbow towards your right knee.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2329', '/media/exercises/2329-2jl9K55.gif', '/media/posters/2329-2jl9K55.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/2368-9E25EOx.gif', poster_url = '/media/posters/2368-9E25EOx.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_2368', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Split Squats') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Squat On Bosu Ball', 'QUADS', 'GLUTES,HAMSTRINGS,CALVES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Place the bosu ball on the ground with the flat side up.', '["Place the bosu ball on the ground with the flat side up.","Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.","Lower your body down by bending your knees and hips, as if sitting back into a chair.","Keep your chest up and your weight on your heels.","Lower yourself until your thighs are parallel to the ground.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1705', '/media/exercises/1705-T2fA5Ir.gif', '/media/posters/1705-T2fA5Ir.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Squat To Overhead Reach', 'QUADS', 'GLUTES,HAMSTRINGS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and toes slightly turned out.', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body down into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Return to the starting position by lowering your arms and bending your knees to squat down again.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1685', '/media/exercises/1685-QChZi3x.gif', '/media/posters/1685-QChZi3x.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Squat To Overhead Reach With Twist', 'QUADS', 'GLUTES,HAMSTRINGS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and toes slightly turned out.', '["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, raise your arms overhead and twist your torso to one side.","Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Continue alternating sides with each squat repetition."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1686', '/media/exercises/1686-5BZHW9s.gif', '/media/posters/1686-5BZHW9s.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Stability Ball Crunch (full Range Hands Behind Head)', 'ABS', 'HIP FLEXORS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your upper body back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2297', '/media/exercises/2297-Gn5FwYT.gif', '/media/posters/2297-Gn5FwYT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Stalder Press', 'TRICEPS', 'SHOULDERS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by standing with your feet shoulder-width apart and your arms extended overhead.', '["Start by standing with your feet shoulder-width apart and your arms extended overhead.","Bend your knees slightly and engage your core.","Lower your body down into a squat position while keeping your arms extended overhead.","As you squat down, press your arms down towards the ground, engaging your triceps.","Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3291', '/media/exercises/3291-zd4P4B2.gif', '/media/posters/3291-zd4P4B2.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Standing Archer', 'BACK', 'SHOULDERS,BICEPS,FOREARMS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your knees slightly bent.', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Rotate your torso to the right, keeping your arms extended and your back straight.","As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Hold the position for a moment, then return to the starting position.","Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3669', '/media/exercises/3669-JF8AkMX.gif', '/media/posters/3669-JF8AkMX.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Standing Behind Neck Press', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'BARBELL', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.', '["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.","Keep your back straight and core engaged.","Press the barbell overhead by extending your arms, fully extending your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0788', '/media/exercises/0788-xDh0lJr.gif', '/media/posters/0788-xDh0lJr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Standing Calf Raise (on A Staircase)', 'CALVES', 'ANKLES,FEET', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.', '["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Hold onto a railing or wall for balance if needed.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1490', '/media/exercises/1490-6HmFgmx.gif', '/media/posters/1490-6HmFgmx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Standing Calves', 'CALVES', 'HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, toes pointing forward.', '["Stand with your feet shoulder-width apart, toes pointing forward.","Raise your heels off the ground as high as possible, standing on your toes.","Hold the position for a moment, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1397', '/media/exercises/1397-XIHEoCG.gif', '/media/posters/1397-XIHEoCG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Standing Calves Calf Stretch', 'CALVES', 'HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand facing a wall or sturdy object, about an arm''s length away.', '["Stand facing a wall or sturdy object, about an arm''s length away.","Place your hands on the wall or object at shoulder height.","Step back with one foot, keeping your heel flat on the ground.","Bend your front knee slightly and lean forward, keeping your back leg straight.","You should feel a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Repeat on the other leg."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1398', '/media/exercises/1398-qOKcgVP.gif', '/media/posters/1398-qOKcgVP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Standing Hamstring And Calf Stretch With Strap', 'HAMSTRINGS', 'CALVES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand upright with your feet shoulder-width apart.', '["Stand upright with your feet shoulder-width apart.","Hold the strap with both hands and place it around the ball of your foot.","Keep your leg straight and slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your hamstring and calf muscles.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat with the other leg.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1599', '/media/exercises/1599-xTjr103.gif', '/media/posters/1599-xTjr103.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0794-1jXLYEw.gif', poster_url = '/media/posters/0794-1jXLYEw.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0794', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Standing Lateral Stretch') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Standing Wheel Rollerout', 'ABS', 'LOWER BACK,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.', '["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.","Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.","Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.","Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0796', '/media/exercises/0796-KtRomty.gif', '/media/posters/0796-KtRomty.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Star Jump (male)', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your arms by your sides.', '["Stand with your feet shoulder-width apart and your arms by your sides.","Bend your knees slightly and jump up explosively.","As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Land softly on the balls of your feet with your knees slightly bent.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3223', '/media/exercises/3223-HtfCpfi.gif', '/media/posters/3223-HtfCpfi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Stationary Bike Run V. 3', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position to ensure proper alignment.', '["Adjust the seat height and position to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace.","Maintain a steady rhythm and increase the resistance as desired.","Engage your core muscles to maintain stability and proper posture.","Continue pedaling for the desired duration of your workout.","Gradually decrease the resistance and slow down before coming to a complete stop.","Stretch your legs and cool down after the workout."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2138', '/media/exercises/2138-H1PESYI.gif', '/media/posters/2138-H1PESYI.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Stationary Bike Walk', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position on the stationary bike to ensure proper alignment.', '["Adjust the seat height and position on the stationary bike to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace, keeping your back straight and core engaged.","Maintain a steady rhythm and increase the resistance level if desired.","Continue pedaling for the desired duration of your cardio workout.","Cool down by gradually reducing your pace and resistance level.","Stretch your leg muscles after the workout to prevent tightness and promote recovery."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0798', '/media/exercises/0798-a8VDgLw.gif', '/media/posters/0798-a8VDgLw.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Straddle Maltese', 'ABS', 'SHOULDERS,CHEST', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.', '["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Spread your legs wide apart, forming a straddle position.","Engage your core and slowly lower your body until your arms are parallel to the ground.","Hold this position for a few seconds, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3314', '/media/exercises/3314-HfqciZF.gif', '/media/posters/3314-HfqciZF.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Straddle Planche', 'ABS', 'SHOULDERS,TRICEPS,CHEST', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.', '["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3298', '/media/exercises/3298-BL3GHeY.gif', '/media/posters/3298-BL3GHeY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Straight Leg Outer Hip Abductor', 'QUADS', 'GLUTES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your side with your legs straight and stacked on top of each other.', '["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1427', '/media/exercises/1427-mQ1tBXn.gif', '/media/posters/1427-mQ1tBXn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Superman Push-up', 'CHEST', 'CORE,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Repeat the movement, this time lifting your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0803', '/media/exercises/0803-4GqRrAk.gif', '/media/posters/0803-4GqRrAk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Suspended Abdominal Fallout', 'ABS', 'OBLIQUES,HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Attach a suspension trainer to a high anchor point and adjust the straps to waist height.', '["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Lean forward at the waist, keeping your body straight and your core engaged.","Lower your body as far as you can while maintaining control and tension in your abs.","Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0805', '/media/exercises/0805-X3TCNEU.gif', '/media/posters/0805-X3TCNEU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Swimmer Kicks V. 2 (male)', 'GLUTES', 'HAMSTRINGS,QUADRICEPS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on a mat with your arms extended overhead.', '["Lie face down on a mat with your arms extended overhead.","Engage your core and lift your chest and legs off the ground simultaneously.","Kick your legs up and down in a fluttering motion, as if you were swimming.","Continue kicking for the desired number of repetitions.","Lower your chest and legs back down to the starting position."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3433', '/media/exercises/3433-SP3hUez.gif', '/media/posters/3433-SP3hUez.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Swing 360', 'CARDIO', 'SHOULDERS,CORE', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and knees slightly bent.', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold your arms straight out in front of you, parallel to the ground.","Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Remember to breathe throughout the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3318', '/media/exercises/3318-tnaj0mT.gif', '/media/posters/3318-tnaj0mT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Three Bench Dip', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your hands gripping the edge, fingers pointing forward.', '["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1753', '/media/exercises/1753-DQ0cqkT.gif', '/media/posters/1753-DQ0cqkT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/2459-oZjMu1t.gif', poster_url = '/media/posters/2459-oZjMu1t.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_2459', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Tire Flip') AND (media_url IS NULL OR media_url = '');
UPDATE exercises SET media_url = '/media/exercises/0811-jQGwmxN.gif', poster_url = '/media/posters/0811-jQGwmxN.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0811', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Trap Bar Deadlift') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Triceps Dip (bench Leg)', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.', '["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0812', '/media/exercises/0812-VuoerH0.gif', '/media/posters/0812-VuoerH0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Triceps Dip (between Benches)', 'TRICEPS', 'CHEST,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.', '["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0813', '/media/exercises/0813-Wgbn9qo.gif', '/media/posters/0813-Wgbn9qo.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Twin Handle Parallel Grip Lat Pulldown', 'BACK', 'BICEPS,RHOMBOIDS,REAR DELTOIDS', 'CABLE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the seat height and position yourself facing the cable machine.', '["Adjust the seat height and position yourself facing the cable machine.","Grasp the handles with an overhand grip, hands shoulder-width apart.","Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Lean back slightly and keep your chest up, maintaining a neutral spine.","Pull the handles down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0818', '/media/exercises/0818-rkg41Fb.gif', '/media/posters/0818-rkg41Fb.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Twist Hip Lift', 'GLUTES', 'OBLIQUES,HAMSTRINGS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie on your back with your knees bent and feet flat on the ground.', '["Lie on your back with your knees bent and feet flat on the ground.","Place your hands by your sides for support.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Return to the starting position and repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1466', '/media/exercises/1466-AX1kB0o.gif', '/media/posters/1466-AX1kB0o.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Twisted Leg Raise', 'ABS', 'OBLIQUES,HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs extended and your arms by your sides.', '["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift both legs off the ground, keeping them straight.","As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2802', '/media/exercises/2802-C0eCeEt.gif', '/media/posters/2802-C0eCeEt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Twisted Leg Raise (female)', 'ABS', 'OBLIQUES,HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on your back with your legs extended and your arms by your sides.', '["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and lift your legs off the ground, bringing them towards your chest.","As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2801', '/media/exercises/2801-yT9tk17.gif', '/media/posters/2801-yT9tk17.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Two Toe Touch (male)', 'BACK', 'HAMSTRINGS,GLUTES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and your arms extended out to the sides.', '["Stand with your feet shoulder-width apart and your arms extended out to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with both hands, keeping your legs straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3231', '/media/exercises/3231-p195zsJ.gif', '/media/posters/3231-p195zsJ.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Upward Facing Dog', 'BACK', 'SHOULDERS,CHEST', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Lie face down on the floor with your legs extended behind you.', '["Lie face down on the floor with your legs extended behind you.","Place your hands on the floor next to your lower ribs, fingers pointing forward.","Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.","Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.","Hold this position for a few breaths, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1366', '/media/exercises/1366-01qpYSe.gif', '/media/posters/1366-01qpYSe.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('V-sit On Floor', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Sit on the floor with your legs extended in front of you.', '["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the ground, keeping them straight.","Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3420', '/media/exercises/3420-ZuXu4Eq.gif', '/media/posters/3420-ZuXu4Eq.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Vertical Leg Raise (on Parallel Bars)', 'ABS', 'HIP FLEXORS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Hang from the parallel bars with your arms fully extended and your body straight.', '["Hang from the parallel bars with your arms fully extended and your body straight.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0826', '/media/exercises/0826-ZNgOYQU.gif', '/media/posters/0826-ZNgOYQU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/2141-rjtuP6X.gif', poster_url = '/media/posters/2141-rjtuP6X.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_2141', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Walk Elliptical Cross Trainer') AND (media_url IS NULL OR media_url = '');
UPDATE exercises SET media_url = '/media/exercises/3655-J9zIWig.gif', poster_url = '/media/posters/3655-J9zIWig.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_3655', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Walking High Knees Lunge') AND (media_url IS NULL OR media_url = '');
UPDATE exercises SET media_url = '/media/exercises/3666-rjiM4L3.gif', poster_url = '/media/posters/3666-rjiM4L3.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_3666', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Walking on Incline Treadmill') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Walking On Stepmill', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,GLUTES,CALVES', 'MACHINE', 'INTERMEDIATE', 'COMPOUND', 'Adjust the stepmill machine to a comfortable level.', '["Adjust the stepmill machine to a comfortable level.","Step onto the machine and place your hands on the handrails for support.","Start walking by placing one foot on a step and then the other, alternating between legs.","Maintain an upright posture and engage your core muscles.","Continue walking for the desired duration or distance.","Gradually increase the intensity or speed as you become more comfortable with the exercise.","Remember to cool down and stretch after completing the exercise."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2311', '/media/exercises/2311-j9Q5crt.gif', '/media/posters/2311-j9Q5crt.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Close Grip Chin-up On Dip Cage', 'BACK', 'BICEPS,FOREARMS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.', '["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.","Hang from the bars with your arms fully extended, feet off the ground, and body straight.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.","Continue pulling until your chin is above the bars, then pause for a moment.","Slowly lower your body back down to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2987', '/media/exercises/2987-Gk1r408.gif', '/media/posters/2987-Gk1r408.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Cossack Squats (male)', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.', '["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.","Hold a weight in front of your chest with both hands.","Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.","Go as low as you can while maintaining balance and keeping your chest up.","Push through the heel of the bent leg to return to the starting position.","Repeat on the other side, alternating between legs."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3643', '/media/exercises/3643-GWoKnIm.gif', '/media/posters/3643-GWoKnIm.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Decline Sit-up', 'ABS', 'HIP FLEXORS,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Lie flat on a decline bench with your feet secured under the foot pads.', '["Lie flat on a decline bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3670', '/media/exercises/3670-EZeDVzO.gif', '/media/posters/3670-EZeDVzO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Donkey Calf Raise', 'CALVES', 'HAMSTRINGS,GLUTES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand on a raised platform with your toes on the edge and your heels hanging off.', '["Stand on a raised platform with your toes on the edge and your heels hanging off.","Hold onto a stable object for support.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0833', '/media/exercises/0833-LmaFNZS.gif', '/media/posters/0833-LmaFNZS.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Drop Push Up', 'CHEST', 'TRICEPS,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.', '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.","As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.","Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.","Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.","Continue alternating between the wider and narrower hand positions for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1310', '/media/exercises/1310-PSlvNMs.gif', '/media/posters/1310-PSlvNMs.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Front Plank', 'ABS', 'SHOULDERS,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by lying face down on the floor.', '["Start by lying face down on the floor.","Place your forearms on the ground, with your elbows directly under your shoulders.","Extend your legs straight out behind you, with your toes on the ground.","Engage your core and lift your body off the ground, balancing on your forearms and toes.","Keep your body in a straight line from your head to your heels.","Hold this position for the desired amount of time.","Lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2135', '/media/exercises/2135-VBAWRPG.gif', '/media/posters/2135-VBAWRPG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Front Raise', 'SHOULDERS', 'BICEPS,FOREARMS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0834', '/media/exercises/0834-e4aFmFY.gif', '/media/posters/0834-e4aFmFY.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Hanging Leg-hip Raise', 'ABS', 'HIP FLEXORS,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0866', '/media/exercises/0866-QOA0FD0.gif', '/media/posters/0866-QOA0FD0.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Hyperextension (on Stability Ball)', 'BACK', 'GLUTES,HAMSTRINGS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.', '["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0835', '/media/exercises/0835-8urJS9b.gif', '/media/posters/0835-8urJS9b.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Kneeling Step With Swing', 'SHOULDERS', 'TRICEPS,CORE', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start in a kneeling position with your knees hip-width apart and your back straight.', '["Start in a kneeling position with your knees hip-width apart and your back straight.","Hold a weight in each hand, with your arms extended straight down in front of you.","Engage your core and swing the weights up and overhead, keeping your arms straight.","Lower the weights back down to the starting position and repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3641', '/media/exercises/3641-7uFJuXp.gif', '/media/posters/3641-7uFJuXp.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Lunge With Swing', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart, holding a weight in each hand.', '["Stand with your feet shoulder-width apart, holding a weight in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Push off with your right foot and return to the starting position, swinging the weights back down.","Repeat with your left foot and continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3644', '/media/exercises/3644-5WiFcYk.gif', '/media/posters/3644-5WiFcYk.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Muscle Up', 'BACK', 'BICEPS,TRICEPS,SHOULDERS,CHEST', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.', '["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest reaches the bar, then pause for a moment.","Slowly lower yourself back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3286', '/media/exercises/3286-JsOV1SU.gif', '/media/posters/3286-JsOV1SU.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Muscle Up (on Bar)', 'BACK', 'BICEPS,TRICEPS,SHOULDERS,FOREARMS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.', '["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your elbows and pull your chest towards the bar, keeping your body straight.","Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3312', '/media/exercises/3312-MCkqdKE.gif', '/media/posters/3312-MCkqdKE.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted One Hand Pull Up', 'BACK', 'BICEPS,FOREARMS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arm fully extended and your body straight.","Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3290', '/media/exercises/3290-fXfqg1E.gif', '/media/posters/3290-fXfqg1E.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Overhead Crunch (on Stability Ball)', 'ABS', 'OBLIQUES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands and extend your arms overhead.","Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your torso back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0840', '/media/exercises/0840-xmM75XG.gif', '/media/posters/0840-xmM75XG.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Pull-up', 'BACK', 'BICEPS,FOREARMS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.', '["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0841', '/media/exercises/0841-HMzLjXx.gif', '/media/posters/0841-HMzLjXx.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Round Arm', 'SHOULDERS', 'TRICEPS,UPPER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows.","Continue lifting your arms until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0844', '/media/exercises/0844-VLYXo8S.gif', '/media/posters/0844-VLYXo8S.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Russian Twist', 'ABS', 'OBLIQUES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your knees bent and your feet flat on the floor.', '["Sit on the ground with your knees bent and your feet flat on the floor.","Hold a weight or medicine ball with both hands in front of your chest.","Lean back slightly, keeping your back straight and your core engaged.","Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0846', '/media/exercises/0846-fZFZ704.gif', '/media/posters/0846-fZFZ704.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Russian Twist (legs Up)', 'ABS', 'OBLIQUES,HIP FLEXORS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.', '["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the ground on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0845', '/media/exercises/0845-WU9BLIs.gif', '/media/posters/0845-WU9BLIs.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Russian Twist V. 2', 'ABS', 'OBLIQUES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the ground with your knees bent and feet flat on the floor.', '["Sit on the ground with your knees bent and feet flat on the floor.","Hold the weight with both hands in front of your chest.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2371', '/media/exercises/2371-YIUAtYf.gif', '/media/posters/2371-YIUAtYf.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Seated Bicep Curl (on Stability Ball)', 'BICEPS', 'FOREARMS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your back straight.', '["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.","Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the medicine ball back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0847', '/media/exercises/0847-b4b6afT.gif', '/media/posters/0847-b4b6afT.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Seated Twist (on Stability Ball)', 'ABS', 'OBLIQUES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands close to your chest.","Engage your core and slowly rotate your torso to one side, keeping your hips stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0849', '/media/exercises/0849-s34Y4LR.gif', '/media/posters/0849-s34Y4LR.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Side Bend (on Stability Ball)', 'ABS', 'OBLIQUES,LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on a stability ball with your feet shoulder-width apart and flat on the ground.', '["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.","Hold a weight in one hand and place your other hand on your hip.","Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0850', '/media/exercises/0850-6bOA1Oi.gif', '/media/posters/0850-6bOA1Oi.jpg', 'licensed', 'image', 'verified', 'dataset-record');
UPDATE exercises SET media_url = '/media/exercises/0852-JZuApnB.gif', poster_url = '/media/posters/0852-JZuApnB.jpg', media_provider = 'licensed', media_type = 'image', review_status = 'verified', source = 'exercises-dataset', external_id = 'hasaneyldrm_0852', attribution = 'Exercise dataset by hasaneyldrm (LogPress open dataset)' WHERE LOWER(name) = LOWER('Weighted Squat') AND (media_url IS NULL OR media_url = '');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Standing Curl', 'BICEPS', 'FOREARMS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.","Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0853', '/media/exercises/0853-M5Y7GPg.gif', '/media/posters/0853-M5Y7GPg.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Standing Hand Squeeze', 'FOREARMS', 'BICEPS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a weight in each hand.', '["Stand with your feet shoulder-width apart and hold a weight in each hand.","Extend your arms straight in front of you, palms facing each other.","Squeeze your hands together as hard as you can, engaging your forearms.","Hold the squeeze for a few seconds, then release.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0854', '/media/exercises/0854-bjqbauy.gif', '/media/posters/0854-bjqbauy.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Straight Bar Dip', 'CHEST', 'TRICEPS,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Position yourself between parallel bars with your arms fully extended and your body straight.', '["Position yourself between parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3313', '/media/exercises/3313-Ff18ItA.gif', '/media/posters/3313-Ff18ItA.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Stretch Lunge', 'GLUTES', 'QUADRICEPS,HAMSTRINGS,CALVES', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart.', '["Stand with your feet shoulder-width apart.","Take a step forward with your right foot, keeping your back straight.","Lower your body by bending your knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3642', '/media/exercises/3642-13VW2VO.gif', '/media/posters/3642-13VW2VO.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Svend Press', 'CHEST', 'SHOULDERS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.', '["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.","Keep your elbows slightly bent and your palms facing each other.","Press the weight plate straight out in front of you, fully extending your arms.","Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0856', '/media/exercises/0856-I1OBLnn.gif', '/media/posters/0856-I1OBLnn.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Three Bench Dips', 'TRICEPS', 'CHEST,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.', '["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Lower your body by bending your elbows, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1754', '/media/exercises/1754-gtO1ErP.gif', '/media/posters/1754-gtO1ErP.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Tricep Dips', 'TRICEPS', 'CHEST,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.', '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the front of the bench with your legs extended in front of you.","Keep your back close to the bench and your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1755', '/media/exercises/1755-bZq4bwK.gif', '/media/posters/1755-bZq4bwK.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Weighted Triceps Dip On High Parallel Bars', 'TRICEPS', 'CHEST,SHOULDERS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.', '["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1767', '/media/exercises/1767-K1vlode.gif', '/media/posters/1767-K1vlode.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Wheel Rollerout', 'ABS', 'LOWER BACK', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Kneel on the floor and place the wheel roller in front of you.', '["Kneel on the floor and place the wheel roller in front of you.","Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0857', '/media/exercises/0857-NAgVB3t.gif', '/media/posters/0857-NAgVB3t.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Wheel Run', 'CARDIO', 'QUADRICEPS,HAMSTRINGS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a plank position with your hands on the wheel and your body straight.', '["Start in a plank position with your hands on the wheel and your body straight.","Engage your core and start rolling the wheel forward by extending your arms.","Continue rolling until your body is fully extended and your arms are overhead.","Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_3637', '/media/exercises/3637-km2Ljzj.gif', '/media/posters/3637-km2Ljzj.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Wide-grip Chest Dip On High Parallel Bars', 'CHEST', 'TRICEPS,SHOULDERS', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.', '["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_2363', '/media/exercises/2363-O2K9Vb5.gif', '/media/posters/2363-O2K9Vb5.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('World Greatest Stretch', 'HAMSTRINGS', 'GLUTES,QUADRICEPS,CALVES', 'BODYWEIGHT', 'INTERMEDIATE', 'COMPOUND', 'Start in a lunge position with your right foot forward and your left foot back.', '["Start in a lunge position with your right foot forward and your left foot back.","Place your hands on the ground on either side of your right foot.","Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Rotate your torso to the right, reaching your right arm up towards the ceiling.","Hold this position for a few seconds, then return to the starting position.","Switch sides and repeat the stretch with your left foot forward."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_1604', '/media/exercises/1604-DFGXwZr.gif', '/media/posters/1604-DFGXwZr.jpg', 'licensed', 'image', 'verified', 'dataset-record');
MERGE INTO exercises (name, primary_muscle, secondary_muscles, equipment, difficulty, movement_type, form_tips, steps_json, mistakes_json, default_sets, default_reps, is_custom, attribution, source, external_id, media_url, poster_url, media_provider, media_type, review_status, match_method) KEY(name) VALUES ('Wrist Rollerer', 'FOREARMS', 'BICEPS,TRICEPS', 'OTHER', 'INTERMEDIATE', 'COMPOUND', 'Attach a weight to one end of a rope or bar.', '["Attach a weight to one end of a rope or bar.","Hold the other end of the rope or bar with both hands, palms facing down.","Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Slowly roll the weight up towards your hands by flexing your wrists.","Pause for a moment at the top, then slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions."]', '["Rushing repetitions without controlled cadence.","Losing proper core bracing and spinal alignment."]', 3, '8-12', false, 'Exercise dataset by hasaneyldrm (LogPress open dataset)', 'exercises-dataset', 'hasaneyldrm_0859', '/media/exercises/0859-bd5b860.gif', '/media/posters/0859-bd5b860.jpg', 'licensed', 'image', 'verified', 'dataset-record');